INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41001455838', 'Pulseira Feminina de Prata 925 Elo Cadeado e Trevo', 'Pulseira Feminina de Prata 925 Elo Cadeado e Trevo: Elegância e Sorte A Pulseira Feminina de Prata 925 Elo Cadeado e Trevo é a escolha ideal para quem deseja adicionar um toque de sofisticação e simbolismo ao seu visual. Seu design elegante, com elos tipo cadeado e um delicado trevo, traz não apenas beleza, mas também o simbolismo da sorte e prosperidade. Feita em Prata 925, essa pulseira é uma peça durável e cheia de estilo, perfeita para o uso diário ou para ocasiões especiais. Especificações da Pulseira Tamanho: 18cm + (2cm de extensor) Largura: 1mm Tamanho do Trevo: 1,2cm Fecho: Bóia Peso: 1,77g Material: Prata 925 Destaques da Pulseira Design elegante com elos tipo cadeado e trevo, simbolizando sorte e prosperidade Feita com Prata 925, garantindo durabilidade, brilho e resistência. Fecho tipo bóia, oferecendo segurança e praticidade no uso diário. Sorte e Sofisticação em Uma Só Peça A Pulseira Feminina de Prata 925 Elo Cadeado e Trevo é perfeita para quem deseja carregar consigo uma peça cheia de significado, estilo e sofisticação. Seu design delicado e o simbolismo do trevo tornam esta pulseira uma escolha única e significativa, ideal para complementar qualquer look. Cuidados com a Joia Evite o contato com produtos químicos para preservar o brilho da prata. Guarde em local seco e seguro para evitar arranhões e oxidação. Limpe regularmente com uma flanela macia para manter a beleza e o brilho da peça. Simbolismo e Beleza no Seu Estilo Adicione a Pulseira Feminina de Prata 925 Elo Cadeado e Trevo ao seu pulso e carregue consigo uma peça cheia de sorte, sofisticação e elegância. Uma escolha perfeita para quem deseja um acessório com significado e estilo.', 165.99, 99.99, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ymh18wu5h531', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F41001455838', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797670594', 'Escapamento Fortuna Modelo Original - Honda Cb 500 1997 a 2005', 'HB Moto Peças e Acessórios é a nova loja online de produtos da Fortuna, produtos de Qualidade e melhor preço do mercado. A Fortuna Escapamentos é um empresa que trabalha com o que há de melhor e mais moderno no segmento de escapamento e acessórios para motos, com produtos inovadores, qualidade, tecnologia e segurança. Todos os produtos são desenvolvido com matéria prima de primeira qualidade e produtos importados. . Compra 100% Segura e Garantida! . Produto disponível para envio! - O Produto é Pronto para Instalação de acordo com o modelo da Moto, e Encaixa -se Perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação. COMPATÍVEIS COM AS MOTOS : Moto Honda Cb 500 Acessível aos Anos 1997 a 2005 Ponteira em Aço carbono CÓDIGO: AF105 (PRETO) MODELO: Original MARCA: Fortuna COR: Preto Não acompanha a guarnição de vedação DUVIDAS ESTAMOS A DISPOSIÇÃO', 969.97, 969.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-7renb-m8m8lscp2amx98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398614987%2F18797670594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397686703', 'Centopeia sem pés - Cortez', 'Lili é uma centopeia especial. Nasceu sem nenhum pé, justamente numa família de muitos pés e, por tradição, responsável pela entrega das correspondências da cidade. Só que o pai da Lili, o senhor Centopeia, teve uma ideia genial: Fez cem rodinhas e colocou-as na filha para que ela pudesse andar. E algo aconteceu, já no primeiro dia de escola, que mostrou para a Lili que ser diferente pode ser algo belo e cheio de possibilidades. Quer descobrir o que foi?', 54.39, 54.39, NULL, 'Books & Magazines > Books > Politics, Law & Social Sciences', 'https://cf.shopee.com.br/file/sg-11134201-7rd4x-lw1zel0ixjnfd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F20397686703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899181937', 'Pneu Moto Bmw S1000 Tras 190/55-17 Pilot Power 2ct Michelin', 'Encontre a segurança e a estabilidade de que você precisa para percorrer as estradas que tanto deseja. Sinta-se confiante ao pilotar, garantindo uma aderência precisa em sua viagem. Os pneus da Michelin garantem a segurança e eficiência que você precisa, cuidando do meio ambiente de forma notável. Sua qualidade é refletida em cada frenagem, pois são resistentes ao desgaste. Se furar, seu pneu o protege Este produto sem câmara contém a pressão do ar entre o pneu e o aro. Garante um maior suporte e segurança, pois o revestimento interno envolve o objeto com o qual você perfurou e mantém o ar no interior. A segurança que você procura Com excelente capacidade de evacuação de água, com a finalidade de evitar o aquaplaning. Seu melhor parceiro quando o assunto é aventura É um pneu com alto desempenho e grande aderência na estrada, ideal para aventuras.', 1484.94, 1484.94, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhhk78rzpxc27f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819034845%2F23899181937', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
