INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22535007917', 'Mordedor Mãozinha Macio Para Dentição Alivio Gengiva Do Bebê Azul Rosa Mamita', 'Descrição_x000D_ _x000D_ O Mordedor Mãozinha possui abertura no meio para facilitar o manuseio do bebê. Além disso, são bem macios para facilitar na dentição do bebê._x000D_ _x000D_ Mordedor desenvolvido especialmente para auxiliar no alivio e desconforto da dentição. Produz uma sensação estimulante ao ser tocada pela boca da criança_x000D_ _x000D_ Livre de BPA. Contém 1 unidade. Composição: PVCProduto certificado pelo INMETRO. _x000D_ _x000D_ _x000D_ ATENÇÃO! Antes do uso recomenda-se colocar em água fervente durante 5 minutos e ao ferver o produto, espere esfriar totalmente antes de dar à criança._x000D_ _x000D_ *IMAGEM MERAMENTE ILUSTRATIVA*_x000D_ _x000D_ Lembrando que os nossos produtos acompanham NOTA FISCAL.', 12.99, 8.9, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/br-11134207-820l8-mpuvae3j5amab9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F22535007917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51159378907', '03 Bisnagas Decoradas 350Ml Para Molhos Ketchup Mostarda Maionese Lanchonete Plástico Dosador Refil', 'Kit 3 Bisnagas para Molhos 350ml – Ketchup, Mostarda e Maionese Organize e agilize sua cozinha com esse kit prático de bisnagas para molhos. Ideal para uso diário em casa ou em ambientes profissionais como lanchonetes, food trucks e restaurantes. Descrição do Produto: As bisnagas possuem capacidade de 350ml cada, com material flexível que facilita o manuseio e aplicação dos molhos. A tampa com bico dosador permite controle preciso, evitando desperdícios e sujeira. Além disso, contam com vedação segura para evitar vazamentos. Diferenciais: Fácil de apertar e usar Tampa com vedação eficiente Reutilizável e fácil de limpar Ideal para ketchup, mostarda, maionese, barbecue e outros molhos Design funcional para organização da cozinha Especificações: Capacidade: 350ml cada unidade Material: Plástico resistente e flexível Quantidade: 3 unidades Conteúdo da Embalagem: 1 Bisnaga para Ketchup 1 Bisnaga para Mostarda 1 Bisnaga para Maionese Indicado para: Cozinhas domésticas Lanchonetes e restaurantes Food trucks Organização e praticidade no preparo de alimentos Produto prático, durável e essencial para quem busca mais agilidade no dia a dia.', 30.9, 20.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-820ln-mnepuqi54iki02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F51159378907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
