INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21078023555', 'Kit Carenagem Plástica Cromo Forte 5 Peças Para Moto Nxr Bros 150 2009 2010 2011', 'As carenagens e peças plásticas Cromo Forte são produzidas nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricado em ABS 100% virgem, as carenagens Cromo Forte são extremamente resistentes aos raios UV, tornando-se assim o melhor custo-benefício do mercado. Características: - Marca: Cromo Forte; - Modelo: Original; - Tonalidade de cores semelhante ao original; - Moto compatível: NXR 150 Bros 2009 a 2011 (Confira a relação de cores e anos abaixo). Aplicação: - Amarelo Trancoso: 2009; - Laranja: 2011; - Laranja Canoa: 2010; - Preto: 2009, 2010 e 2011; - Vermelho Caucaia: 2009 e 2010; - Vermelho Clívia: 2011. Componentes do Kit: - 1 Aba do Tanque (Par); - 1 Carenagem do Farol; - 1 Paralama Dianteiro; - 1 Rabeta; - 1 Tampa Lateral (Par). Atenção! - Devido ao desgaste da pintura da motocicleta com o passar do tempo, pode haver uma pequena divergência na tonalidade das cores. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada.', 378.84, 238.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134201-820m4-mqxdmvk5c3yca9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F21078023555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297475764', 'Slider Protetor De Motor Peças Acessórios Super Adventure Moto Cbr 250 2012 Em Alumínio Par', 'O Protetor de Motor Slider CBR 250 Super Adventure protege sua motocicleta em caso de quedas, sua posição estratégica garante que ele será a parte a tocar o chão, evitando danos no motor. Especificações: - Disponível nas cores: Azul, Polido, Preto e Vermelho; - Fabricado em alumínio; - Parafusos Allen Cabeça Cilíndrica; - Bucha cônica; - Anel em poliuretano; - Valor referente ao par; - Marca: Super Adventure. Aplicação: - CBR 250 2012. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada.', 556.74, 279.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Frame Sliders', 'https://cf.shopee.com.br/file/sg-11134201-7rbl3-lnkcs4hswofa41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F21297475764', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
