INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19199678454', 'Quebra-Cabeça Puzzle Coleção Futebol Atlético Mineiro 200 Peças Mimo Toys - 2569', 'Monte o Quebra-Cabeça Colecionável dos Craques do Atlético e divirta-se enquanto constrói sua coleção! Com 200 peças de papel cartão, este quebra-cabeça é perfeito para os fãs do Atlético e proporciona uma experiência divertida e desafiadora. Ao concluir, você terá uma imagem incrível dos craques do time. Este brinquedo é ideal para crianças a partir de 3 anos, podendo ser jogado por uma ou mais pessoas. Além de proporcionar diversão, ele estimula a percepção visual, a concentração e o raciocínio lógico. A experiência de montagem dura cerca de 1 hora, sendo uma ótima atividade para exercitar a mente enquanto se diverte. Características: Indicado para crianças a partir de 3 anos Participantes: 1 ou mais jogadores Tempo de duração: Aproximadamente 1 hora Conteúdo: 200 peças de papel cartãoMaterial: aproximadamente 35 cm x 48 cm Benefícios: Percepção visual, concentração e raciocínio lógico Características: - Marca: Mimo - Modelo: 2569 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01 Quebra-Cabeça Puzzle Coleção Futebol Atlético Mineiro 200 Peças Mimo Toys', 50.0, 50.0, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7reoe-m80jca9ilha835', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F19199678454', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699694864', 'Pneus 90/90-21 007 Medium Soft + 110/100-18 B007 Infinity', 'Pneus 90/90-21 007 Medium Soft + 110/100-18 B007 Infinity Pneu Aro 21 Borilli 90/90-21 Exc 007 Medium Soft Sobre o produto: O modelo EXC 007 MEDIUM SOFT, com seus blocos alternados, o que proporciona maior estabilidade e tração, auxiliando também na sua limpeza. Informações adicionais: Marca: Borilli Modelo: Exc 007 Medium Soft Medida: 90/90-21 Largura: 90mm Perfil: 90% Aro: 21 Índice de velocidade: R - 170 Km/h Índice de peso: 57 - 230 Kg Posição: Dianteiro Tipo de montagem: Com câmara Garantia: 5 anos contra defeitos de fábrica Pneu Aro 18 Borilli 110/100-18 B007 Infinity Exc Sobre o produto: O modelo B007 INFINITY EXC possui uma banda de rodagem com blocos alternados e com maior espaçamento, possibilita a vazão da água e de pedras, melhorando seu poder de tração. Informações adicionais: Marca: Borilli Modelo: B007 Infinity Exc Medida: 110/100-18 Largura: 110mm Perfil: 100% Aro: 18 Índice de velocidade: R - 170 Km/h Índice de peso: 64 - 280 Kg Posição: Traseira Tipo de montagem: Com câmara Garantia: 5 anos contra defeitos de fábrica Obsevações: IMAGEM MERAMENTE ILUSTRATIVA VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU', 829.27, 829.27, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-8259o-mqqhymunhh5a96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F18699694864', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093497657', 'Maleta Anti-Impacto Com Rodas Mai 545 - Vonder', 'Maleta Anti-Impacto Com Rodas Mai 545 - Vonder Destaques e diferenciais: Possui válvula manual de compensação de pressão que equilibra a pressão interior com a exterior, facilitando a abertura da maleta, alça extensível e rodas que facilitam o transporte, além de duas travas e porta-cadeados. Possui na parte interna espumas removíveis que oferecem máxima proteção. Na parte superior, a espuma é tipo "caixa de ovos" e, na parte inferior, a espuma é pré-recortada em blocos, que se moldam ao formato e tamanho de cada objeto, conforme necessidade. Aplicações e dicas de uso: Indicada para acondicionamento de produtos que requerem maior cuidado no transporte e armazenamento, pois possui proteção contra impactos e umidade (IP54) Características Técnicas: Comprimento da maleta para ferramentas: 559,0 mm Largura da maleta para ferramentas: 351,0 mm Altura da maleta para ferramentas: 229,0 mm Material da maleta para ferramentas: Plástico (PP) Capacidade máxima da maleta para ferramentas (kgf): 20,0 kgf Garantia: Garantia legal: 90 dias Conteúdo Embalagem: 1 Maleta anti-impacto', 1209.83, 912.96, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2wv39ufpddx5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23093497657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
