INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598428339', 'Baixo 4 Cordas Shelter Jazz Bass SHJB75 Pro', 'Somos a RCK AUDIO, sua loja virtual de Instrumentos Musicais e Áudio Profissional - Há mais de 10 anos no mercado - Mais de 150.000 clientes atendidos - Todos os produtos com Nota Fiscal - Revenda autorizada oficial do produto - Criterioso processo de embalagem e expedição ; Baixo 4 Cordas Shelter Jazz Bass SHJB75 Pro Baixo Shelter Jazz Bass 4 cordas SHJB75 Pro com corpo em Basswood, braço e escala em Maple e captação Wilkinson™ O Shelter SHJB75 Pro é um baixo de 4 cordas com design inspirado no lendário Jazz Bass dos anos 70, oferecendo timbre encorpado, visual vintage e excelente conforto ao tocar. Pensado para músicos que valorizam qualidade e estilo, esse modelo entrega sonoridade rica em frequências médias e agudas, perfeita para linhas de baixo expressivas e com presença. Com corpo em Basswood, braço em maple e dois captadores single-coil tipo JB Wilkinson™, o SHJB75 Pro é ideal para diversos estilos musicais, como funk, rock, pop, soul, jazz, reggae e R&B. Especificações: Construção: Braço parafusado; Corpo: Basswood; Braço: Maple; Escala: Maple; Ferragens: Cromadas; 43 mm Nut (Pestana); 20 trastes; Captadores: 2 JB Wilkinson™; Circuito: Passivo; Controles: 1 Volume, 1 Tone; Disponível em 5 cores: 3TS, CAR, BK, OW, SBL.', 1726.99, 1726.99, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7reof-m8or18j4j3xl3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F22598428339', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
