INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9233963260', 'Bíblia Nvi Em Ordem Cronológica - Capa Luxo Preta', 'A Bíblia em ordem cronológica é uma ferramenta indispensável para os estudiosos da Palavra de Deus.Em vez de se deter nos meticulosos recortes das Escrituras o leitor terá diante de si um bem engendrado quebra-cabeça dos acontecimentos históricos.Nunca a linha dos acontecimentos históricos relacionados à Bíblia esteve tão vem representada. O resultado supera todas as expectativas. Todos os versículos das Escrituras foram dispostos conforme seu lugar na cronologia.Os salmos foram inseridos na época de sua composição. A história de Israel e a história de Judá no período do reino dividido são apresentadas em colunas paralelas com a vida de cada rei posicionada em sua época e lugar. Peso 0.9500 ISBN 9788573678901 Título BIBLIA NVI EM ORDEM CRONOLOGICA LX PRETA EAN 9788573678901', 152.92, 152.92, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdqfowspwt7546', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F9233963260', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
