INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498831478', 'Película para Samsung Galaxy Z Fold 7 - Privacidade Hydrogel - Gshield', 'DESCRIÇÃO Aumente a resistência do seu Samsung Galaxy Z Fold 7 com a película de Hydrogel! A Película de Privacidade de Hydrogel para Samsung Galaxy Z Fold 7 da Gshield é a escolha ideal para reforçar a proteção da tela do seu dispositivo enquanto preserva sua privacidade. Desenvolvida com a inovadora tecnologia hidro nano pet e TPU Soft Gel, essa película é resistente contra riscos indesejados. O revestimento oleofóbico da película não apenas aprimora a resistência contra arranhões, mas também reduz as marcas de digitais na tela, proporcionando uma visão clara e nítida em todos os momentos. A adaptação perfeita às extremidades curvadas do seu dispositivo assegura uma cobertura completa do visor, preservando a estética e funcionalidade do aparelho. Escolher a Película de Hydrogel Gshield é optar por um escudo de proteção sofisticado, que une tecnologia de ponta e durabilidade para manter a tela do seu celular impecável. Cuide do seu Samsung Galaxy Z Fold 7 com estilo e confiança, investindo na excelência em proteção que só a Gshield proporciona. Clique aqui para acessar os manuais dos produtos Gshield. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: GshieldEspessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Dimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais. Certificações: US Military', 87.97, 87.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rdy2-mdkqzjylnzkk33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22498831478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698868419', 'Película para Garmin Venu X1 - Hydrogel HD - Gshield', 'DESCRIÇÃO A Película de Hydrogel da Gshield oferece proteção avançada para a tela do seu smartwatch, garantindo uma experiência duradoura e sem preocupações. Com tecnologia inovadora de hidro nano PET e TPU Soft Gel, essa película protege contra riscos indesejados. O revestimento oleofóbico não só aprimora a resistência a arranhões, mas também minimiza marcas de digitais, proporcionando uma visualização sempre clara e nítida. A película se ajusta perfeitamente às extremidades curvas do seu dispositivo, assegurando uma cobertura total sem comprometer a estética e a funcionalidade. Optar pela Película de Hydrogel Gshield é escolher um escudo sofisticado que combina tecnologia de ponta e durabilidade, mantendo a tela do seu relógio sempre impecável. Cuide do seu smartwatch com estilo e confiança, escolhendo a excelência em proteção que só a Gshield oferece. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: GshieldEspessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-824g8-me7jvrxoac5ha5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23698868419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498831495', 'Película para Xiaomi Poco F7 - Traseira Hydrogel HD - Gshield', 'DESCRIÇÃO Aumente a resistência do seu Xiaomi Poco F7 com a película de Hydrogel! A Película de Hydrogel da Gshield oferece uma proteção avançada para a traseira do seu Xiaomi Poco F7, garantindo uma experiência duradoura e sem preocupações. Desenvolvida com a inovadora tecnologia hidro nano pet e TPU Soft Gel, essa película é resistente contra riscos indesejados. O revestimento oleofóbico da película não apenas aprimora a resistência contra arranhões, mas também reduz as marcas de digitais na traseira, proporcionando uma aparência limpa e sem marcas. A adaptação perfeita às extremidades curvadas do seu dispositivo assegura uma cobertura completa do dispositivo. Escolher a Película de Hydrogel Gshield é optar por um escudo de proteção sofisticado, que une tecnologia de ponta e durabilidade para manter a traseira do seu celular impecável. Cuide do seu Xiaomi Poco F7 com estilo e confiança, investindo na excelência em proteção que só a Gshield proporciona. Clique aqui para acessar os manuais dos produtos Gshield. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: Gshield Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à traseiraGrau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rdx4-mdkqzrjmki9641', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22498831495', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294205662', 'Película para Motorola Moto G55 5G - AntiBlue - Gshield', 'Você está cansado de sofrer os efeitos nocivos da luz azul? Estresse, dores de cabeça, fadiga ocular e insônia são alguns dos problemas enfrentados pelo uso excessivo do celular. Se você procura uma solução para esses problemas, então a Película AntiBlue da Gshield, é exatamente o que você precisa! A Antiblue da Gshield é fabricada com tecnologia especial para bloquear 99% da luz UV azul Prejudicial à saúde emitida pelo smartphone durante o seu uso, ela protege tanto seus olhos quanto sua pele; reduz significadamente os reflexos luminosos e também melhora drasticamente o sono noturno regulando melhor as ondas cerebrais com base na frequência da luz azul emitida pela tela do celular, proporcionando assim um bem-estar mental maior durante todo o dia! Não há nada melhor do que realizar dois investimentos em um só: cuidar da sua saúde e do seu bem material, por isso a película AntiBlue é perfeita para você! Protege o seu Motorola Moto G55 5G e a sua saúde! Principais diferenciais da AntiBlue: Previne o ressecamento dos olhos Previne o ressecamento da pele Segura para uso contínuo Tecnologia Anti-risco', 65.97, 65.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-mbpzlb81ehqu66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22294205662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
