INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9070318359', 'Livro - A chegada de Anne - Capa comum', 'Marilla e Matthew Cuthbert queriam adotar um menino ara ajudá-los na fazenda. Mas em vez disso, quem chega é uma menina, Anne, escrito com e no final! Anne sempre sonhou em ter um lar de verdade. Será que Green Gables seria esse lar? Marilla não tem tanta certeza. E a vizinha intrometida, sra. Lynde, acha que aquele não é o lugar para Anne. Neste primeiro livro de uma charmosa série que apresenta para pequenos leitores a Anne de Green Gables de L.M. Montgomery, Anne Shirley precisa provar o que em seu coração ela tem certeza: que Green Gables é exatamente onde ela deveria estar! Editora: Ciranda Cultural Edição: 1, 2021 Autor: Kallie George Idioma: Português Páginas: 64 Dimensões: L 15.50 x A 22.60 x E 0.50 ISBN: 9786555005448', 34.9, 34.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/eb91d526277c48eabcd58083e7f1cfad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9070318359', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
