INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697980141', 'Kit Lowell It Blond Shampoo Máscara Extra (4 produtos)', 'Kit Lowell Violet Platinum Shampoo e Máscara Matizadora Cabelos Loiros (4 produtos) Este Kit Contém Lowell Violet Platinum - Shampoo 240ml (2 unidades): shampoo matizador hidratante rico em pigmento violeta acinzentado, neutraliza o tom amarelado e dá brilho. Sendo uma linha ainda mais aprimorada para o cuidado dos cabelos loiros. Entrega cabelos matizados, livres de reflexos amarelados e alaranjados indesejados, ao mesmo tempo que promove hidratação e efeito platinado. Lowell Violet Platinum - Máscara Matizadora 240g (2 unidades): máscara hidratante matizadora, promove efeito platinado, neutraliza os tons amarelados e dá brilho. Reativa o brilho do cabelo com sua alta concentração de pigmentos violetas acinzentados hidratantes, além de matizar os fios. Conselho de Aplicação Shampoo: com os cabelos limpos e úmidos, aplique o shampoo massageando o couro cabeludo e espalhando pelo comprimento dos cabelos. Enxague completamente. Máscara: com ajuda de uma espátula, para evitar contaminação do produto, pegue uma quantidade e aplique com as mãos nos fios limpos e úmidos, mecha a mecha por todo o comprimento. Deixe agir de 1 a 5 minutos e enxague completamente o produto.', 726.13, 726.13, NULL, 'Beauty > Men''s Care > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-8262m-mkb51ozi4xdud5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22697980141', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
