INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293435417', 'Creamy Watery Lotion FPS 60 - Protetor Solar Facial 50ml', 'Creamy Watery Lotion FPS 60 - Protetor Solar Facial 50ml Protetor solar facial. Creamy Watery Lotion FPS 60 oferece alta proteção para a pele UVA PPD 25 contra a luz azul e luz visível. Indicado para todos os tipos de pele, principalmente as oleosas. Possui alta resistência a água e ao suor, podendo ser usado no dia a dia e durante a prática de exercícios físicos ao ar livre. Não arde o olho e não possui cheiro. Conselho de Aplicação Agite antes de usar. Aplique o produto sobre o rosto, pescoço, colo e orelhas de forma abundante. Reaplique sempre após suor intenso, após se molhar ou se secar com toalha.', 134.3, 74.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-m18uyklpnzpzb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22293435417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
