INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897733794', 'Sensor De Rotação Fiat Tipo 1.6ie 1993 A 1995 Original Gauss', 'Título do Anúncio: Sensor De Rotação Fiat Tipo 1.6ie 1993 A 1995 Gauss Está com problemas na partida ou com o desempenho do seu Fiat? O sensor de rotação é um componente crucial para o bom funcionamento do motor do seu carro. Ele informa a central eletrônica (ECU) a posição e a velocidade do virabrequim, permitindo o controle preciso da injeção de combustível e da ignição. Sem ele, o veículo pode apresentar falhas graves. A Importância do Sensor de Rotação O sensor de rotação é um componente vital no sistema de injeção eletrônica do seu veículo. Ele garante a sincronia perfeita entre a injeção de combustível e a ignição, otimizando o desempenho do motor e a eficiência do consumo. Por que Escolher o Sensor de Rotação Gauss? A Gauss é uma marca reconhecida pela qualidade e durabilidade de seus produtos automotivos. Ao escolher um sensor de rotação Gauss, você garante a precisão das informações enviadas à central eletrônica do seu veículo, contribuindo para um funcionamento suave e confiável do motor. Peças Gauss são sinônimo de segurança e performance! Aplicação / Compatibilidade Este sensor de rotação é compatível com os seguintes veículos Fiat: Elba (Motor SEVEL): 1992 a 1996 Fiorino (Motor SEVEL): 1995 a 1996 Tipo (Motor M3): 1993 a 1995 Tipo (Motor SEVEL): 1996 a 1997 Uno (Motor SEVEL): 1995 Equivalências Este sensor de rotação Gauss (AUGS671) também é compatível com os códigos: BOSCH: 0261210103 BOSCH: 0261210118 DPL: DPL508118 FIAT ORIGINAL: 7756924 FIAT ORIGINAL: 7799032 FIAT ORIGINAL: GS8303 Especificações Técnicas Categoria: Sensor de Rotação Marca: Gauss GTIN: 7898252657935 Dimensões da embalagem: 13cm x 5cm x 9cm Peso: 0.066 kg Não perca tempo! Garanta o bom funcionamento do seu veículo com um sensor de rotação de alta qualidade. Adquira agora o seu sensor de rotação Gauss e volte a dirigir com segurança e tranquilidade!', 104.99, 104.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5klm8u8hy2a79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F21897733794', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209837614', 'Xcara Ch de Cristal Ecol c P Imperial 200ml Lyor', 'A Xcara de Ch de Cristal com P Imperial Lyor 200ml oferece uma experincia refinada para quem aprecia servir e degustar com elegncia. Seu design clssico com p trabalhado adiciona sofisticao mesa, enquanto o cristal ecolgico garante brilho, leveza e um visual impecvel. Ideal para transformar momentos cotidianos em ocasies especiais, unindo estilo, funcionalidade e beleza. Caractersticas Material cristal ecolgico Cor transparente Capacidade 200ml Cristal ecolgico com transparncia e brilho P imperial com design clssico Fcil manuseio pelo peso leve Lavvel em lava-louas no Uso no micro-ondas no Dimenses Altura 11,1 cm Largura 5,6 cm Comprimento 7,3 cm Peso 220 g Contedo da embalagem 01 Xcara de Ch de Cristal com P Imperial Lyor 200ml Garantia: 03 Meses.', 11.88, 11.88, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-820nx-mnmzqdzjod8m3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F58209837614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
