INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897746569', 'Spray Camuflagem Areia 340g Rust Oleum', 'O spray de camuflagem especial Rust-Oleum fornece um acabamento ultra-plano e não refletivo para o máximo de ocultação. Aplica-se a metal, madeira, gesso ou alvenaria. Oferece proteção duradoura quando aplicado sobre o primer. Secagem rápido Interior exterior Para melhores resultados: Use folhas e galhos como estênceis. Disponível nas cores: Marrom Terra - Earth Brown Deep Forest Green Verde Exército - Army Green Caqui - khaki', 90.9, 90.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-81ztt-mn7bjw4writkda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1344829093%2F22897746569', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
