INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206647968', 'Absorvente Com Abas Libresse Noturno Boa Noite 24 Unidades', 'Libresse é uma marca com uma linha completa de produtos para o ciclo menstrual. Acreditamos que o ciclo menstrual é único. Vamos surpreender e transformar a relação com a sua menstruação, oferecendo um lugar seguro também para a higiene íntima diária. São diversas opções de acordo com a necessidade de cada pessoa que menstrua, afinal seu corpo suas regras. DIFERENCIAIS: Seu melhor aliado mais longo para uma noite tranquila com 28cm. Com 3 zonas de máxima absorção, barreiras que bloqueiam vazamentos e exclusivas abas assimétricas que se adaptam perfeitamente ao corpo e aos seus movimentos para que você se sinta sempre confortável e protegida. Produto com cobertura suave e macio, com extrato de algodão que permite a respiração da Zona V mantendo-a sempre limpa, seca e a sensação de frescor e proteção durante todo o dia. Produto dermatologicamente testado.', 23.69, 23.69, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-82620-mlnmmhorxts04b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1680822093%2F58206647968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
