INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50401551699', 'CAIXA DE AREIA SANITÁRIO PARA GATOS', 'A Estrela Pet oferece a você a CAIXA DE AREIA PARA GATOS A Caixa de Areia para Gato é a solução ideal para quem busca praticidade e conforto para seu felino. Com um design aberto e tamanho grande, proporciona amplo espaço para que seu gato se sinta à vontade durante o uso. Acompanha dois potinhos e uma pá, facilitando a limpeza e manutenção do ambiente. Este produto é perfeito para gatos de todos os tamanhos, garantindo que eles tenham um local adequado e higiênico para suas necessidades. A estrutura robusta e de fácil acesso torna a experiência mais agradável tanto para o animal quanto para o proprietário. A Caixa de Areia é uma escolha inteligente para quem valoriza a qualidade e a funcionalidade. Invista no bem-estar do seu gato e transforme a rotina de cuidados em um momento mais simples e eficiente.', 61.9, 13.9, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/br-11134207-820ln-mmk8cvxc0jr86e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F338619088%2F50401551699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57205724421', 'Sheba Petisco Cremoso Para Gatos Sabor Atum 2 Tubos 24g', 'A Estrela Pet oferece a você o SHEBA CREAMY ATUM 24G! Descubra o prazer que seu gato pode sentir com o Sheba Petisco Cremoso Para Gatos Sabor Atum. Este snack úmido é ideal para mimar seu felino, proporcionando uma experiência de sabor irresistível que vai agradar até os paladares mais exigentes. Com dois tubos de 12g cada, é fácil de servir e perfeito para momentos de carinho e recompensa. A textura cremosa do petisco torna-o uma opção deliciosa e nutritiva, ideal para gatos de todas as idades. A linha de petiscos cremosos da Sheba é desenvolvida com ingredientes de alta qualidade, garantindo que seu gato receba um lanche saboroso e saudável. Proporcione ao seu amigo peludo um momento especial com o sabor autêntico do atum, que ele certamente vai adorar. INGREDIENTES_______________ Carne de frango, carne mecanicamente separada de atum, amido de mandioca, aroma sabor frango, aroma sabor peixe, goma guar, goma xantana, EDTA dissódico, nitrito de sódio. QUANTIDADE RECOMENDADA_________ Peso | Gato Adulto • 1 a 3 kg | 1 a 2 sachês por dia • 3 a 5 kg | 2 a 3 sachês por dia', 20.9, 11.9, NULL, 'Pets > Pet Food > Cat Treats', 'https://cf.shopee.com.br/file/br-11134207-820ln-mmpyqjkn2vpjf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F338619088%2F57205724421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
