INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18561853190', 'Filtro Óleo Nissan March 1.0 1.6 2012 A 2018 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação MARCH 1.0 12V FLEX 5P 2016 MARCH 1.0 12V FLEXSTART 5P 2017 MARCH S 1.0 12V FLEX 5P 2016 até 2018 MARCH S 1.6 16V FLEX FUEL 5P 2012 até 2016 MARCH S 1.6 16V FLEXSTART 5P 2017 MARCH SR 1.6 16V FLEX FUEL 5P 2012 até 2014 MARCH SV 1.0 12V FLEX 5P 2016 até 2018 MARCH SV 1.6 16V FLEX FUEL 2012 até 2016 MARCH SV 1.6 16V FLEXSTART 5P MEC. 2017 Conteúdo Da Embalagem 1 Filtro de Óleo Tipo de Veículo para Carros Marca Fundada em 1969, a Wega Motors Brasil possui sede própria em Itajaí/SC, com uma moderna instalação que produz uma ampla gama de produtos para o mercado de reparação automotiva na linha leve e pesada. A Wega Motors é certificada em Sistema de Gestão da Qualidade ISO9001 – Versão 2000 (pelo BVQI – Bureau Veritas Certification), certificação essa que abrange a fabricação e comercialização de filtros de óleo, ar e combustível, velas e acessórios. O Produto Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o filtro de óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor podendo causar até a fundição do mesmo. Importante • Tempo de garantia - 4 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7798159129521 Código do Fabricante JFOH00 >', 20.31, 20.31, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rblu-llxi8frrqe6x05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F18561853190', NULL, NULL, '2026-07-28