INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26338106430', 'Cofre Abertura Elétrico Chaves De Emergência Preto', 'Cofre Eletrônico Digital com Senha ou Chave 23x17x17 Proteja seus bens mais valiosos com praticidade e segurança! Este Cofre Eletrônico Digital combina resistência, tecnologia e design compacto, sendo ideal para uso em residências, escritórios, hotéis ou estabelecimentos comerciais. 🔒 Segurança e Resistência Estrutura em aço puro com pintura resistente à corrosão, garantindo maior durabilidade. Porta ultra reforçada com ferrolhos maciços e dobradiça em aço sólido. Fechadura eletrônica com abertura por senha numérica ou chave de segurança reserva. ✅ Praticidade e Conforto Carpete interno de proteção para preservar joias, documentos e objetos delicados. Orifícios para fixação com parafusos e buchas inclusos, oferecendo máxima segurança ao prender em paredes ou móveis. Design compacto: perfeito para diferentes ambientes. 📦 Conteúdo da Embalagem 2 Chaves de segurança 2 Parafusos e buchas de fixação 1 Carpete interno de proteção 1 Manual de instruções 📏 Dimensões Externas Altura: 17 cm Largura: 23 cm Profundidade: 17 cm Peso: 2,5 kg ✨ Proteção com qualidade e confiança para o seu dia a dia! Garantia do vendedor: 7 dias', 264.0, 159.99, NULL, 'Home & Living > Safety & Security > Safes', 'https://cf.shopee.com.br/file/br-11134207-820lt-mn5t350ihqtddb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F26338106430', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
