INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13246321718', 'Pedigree Biscrok Filhotes 300g', 'Idade: Filhote Pet: Cachorros Porte de Raça: Médio, Pequeno e Grande Quantidade: 300g Sabor: Frango Indicação: Cães Filhotes Composição: Farinha de trigo, quirera de arroz, farinha de vísceras, gordura de frango, glúten de trigo, leite integral em pó (0,45%), açúcar, minerais (cloreto de sódio - sal comum -, fosfato bicálcico), metabissulfito de sódio, sorbato de potássio, hidrolisado de fígado de ave e suíno e BHT. Níveis de Garantia: Umidade (máx.) 100 g/kg (10%) Proteína Bruta (mín.) 130 g/kg (13%) Extrato Etéreo (mín.) 55 g/kg (5,5%) Matéria Fibrosa (máx.) 40 g/kg (4%) Matéria Mineral (máx.) 70 g/kg (7%) Cálcio (mín.) 2000 mg/kg (0,2%) Cálcio (máx.) 15 g/kg (1,5%) Fósforo (mín.) 1.000 mg/kg (0,1%) Fósforo (máx.) 10 g/kg (1%) Sódio (mín.) 1.000 mg/kg (0,1%) Ácido Linoleico (mín.) 10 g/kg (1%) Quantidade Diária Recomendada*: 1-6 kg: 2-6 meses até 5 biscoitos por dia; 6-10 meses até 6 biscoitos por dia; 6-12 kg: 2-6 meses até 7 biscoitos por dia; 6-10 meses até 8 biscoitos por dia; 12-20 kg: 2-6 meses até 10 biscoitos por dia; 6-10 meses até 12 biscoitos por dia; 20-40 kg: 2-6 meses até 12 biscoitos por dia; 6-10 meses até 15 biscoitos por dia; Mais de 40 kg: 2-6 meses 15 ou mais biscoitos por dia; 6-10 meses 20 ou mais biscoitos por dia; *Os valores são orientativos e devem ser adaptados à raça, ao comportamento e nível de atividade do seu cão, para mantê-lo sempre com o peso adequado. Este produto não substitui o alimento completo. Código de barras: 7896029041949', 25.9, 19.43, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/d88c60befdad441aa2fd175595a32925', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F13246321718', NULL, NULL, '2026-07-28T02:11:31.708458+00