INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692053040', 'VODKA ABSOLUT RAINBOW 1000ML', 'Ao longo dos anos, a Absolut fez todos os tipos de atividades voltadas a comunidade LGBTQIA+, incluindo a primeira garrafa de destilados a usar a bandeira do arco-íris, que foi feita em colaboração com Gilbert Baker, o designer por trás da bandeira original. Para nós, a bandeira do arco-íris representa as diversas vozes da comunidade LGBTQIA+ se unindo, celebrando a diferença na unidade. Agora, quando a bandeira do arco-íris está prestes a completar 40 anos, chegou a hora de dar ao arco-íris um lugar permanente em nosso portfólio. Desta vez com pinceladas, serigrafadas no vidro, criando uma forte conexão com os artistas criativos que se inspiraram na garrafa Absolut no passado. Absolut Rainbow Edition é limitada em volume, mas não em tempo', 159.9, 159.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lkjr2ntphxm0de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F22692053040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
