INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698863653', 'Furadeira de Bancada Profissional Torkz TRE0016, 13mm, 220 Volts', 'Furadeira de Bancada Profissional Torkz TRE0016, 220 Volts Características: Marca: Torkz Modelo: TRE0016 Ref.: 7898603823491 Aplicação: Ideal para o uso em marcenarias, serralherias, carpintarias e oficinas em geral Especificações Função: Perfuração Indicação de uso: A ferramenta destina-se a perfurações em geral em carpintarias, serralherias, oficinas, marcenarias, entre outros. Para furos em madeira, plásticos e materiais ferrosos. Material: Aço, alumínio e plástico Rotação (motor): 1700 rpm Motor: 350 W Mandril: 1/2” (0 - 13 mm) Nº de velocidades: 5 velocidades Velocidades: 620 rpm, 1110 rpm, 1750 rpm, 2370 rpm e 3120 rpm Eixo do mandril: B16 Altura total (cota A): 580 mm Distância mandril/base (cota B): 240 mm Distância mandril/mesa (cota C): 155 mm Curso mandril (cota D): 50 mm Dimensão mesa (E x F): 165 x 160 mm Dimensão base (G x H): 170 x 270 mm Diâmetro da coluna: 46 mm Dimensões embalagem: 456 x 376 x 246 mm Itens Inclusos: 01 Furadeira de bancada 350W 01 Morsa 2.1/2 01 Chave Mandril 01 Chave Allen 01 Manual de instruções Alimentação: Potência: 350 Watts (1/2 CV) Voltagem: 220 Volts Dimensões: Tamanho do produto (AxLxP): 58 x 23 x 44 cm Peso: 15,55 Kg Garantia: 12 meses NÃO FATURAMOS PARA CNPJ', 872.9, 607.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824hp-me667xnuvrph4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1541325700%2F23698863653', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22035825831', 'Lâmpada Spot Led 9,9w Par30 Branco Quente 3000k 800lm', 'Lâmpada Spot Led 9,9w Par30 Branco Quente O Spot de Led tem um acabamento refinado, com alta qualidade na cor do facho de luz combinados ao mecanismo que permite alteração em sua direção. De uso interno, são ideais para destacar objetos em um ambiente, ressaltando aquilo que quer ressaltar no local, seja um quadro, textura, estátua, objetos de decoração, produto da sua loja, etc. Pode ser embutido em forros de gesso, modulares, forros de madeira, PVC ou similares, residências, apartamentos, escritórios, condomínios, estabelecimentos comerciais, vitrines, hotéis, entre outros. Características: - Iluminação de altíssima qualidade, deixando qualquer ambiente aconchegante e moderno; - Foco e excelente reprodução de cor no facho de luz; - Alta economia de energia; - Longa vida útil; - Não emite raio ultravioleta, nem infravermelho; Informações técnicas: - Potência: 9,9W - Modelo: Par30 - Material: PVC - Temperatura de cor: Branco Quente (3000k) - Luminosidade: 800LM (3000K) - Vida útil estimada em 25.000 horas - Voltagem: (Bivolt) - Ângulo de abertura: 40° - Uso: interno - Dimensões: Ø95*95mm Conteúdo da Embalagem: - 01 Lâmpada Spot Led 9,9w Par30 Branco Quente "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Imagens meramente ilustrativas', 36.98, 36.98, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7qvdo-lf198a59kdw812', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F664195321%2F22035825831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
