INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392851233', 'Cadeira Presidente Executiva Ergonômica com Acabamento Premium', 'OBSERVAÇÂO: CARO CLIENTE, POR GENTILEZA DE PREFERÊNCIA REALIZAR COMPRA DE 1 UNIDADE POR NOTA, EM QUESTÃO DE FACILITAR O TRANSPORTE ATÉ A CHEGADA. Cadeira de Escritório Office Presidente Giratória Reclinável Executiva Ergonômica Transforme seu ambiente de trabalho com conforto, elegância e funcionalidade. A Cadeira Office Presidente da Led Tools foi desenvolvida para quem busca ergonomia e sofisticação, proporcionando suporte ideal para longas horas de trabalho. Seu sistema giratório 360° e a função relax permitem máxima liberdade de movimento e conforto personalizado. Além disso, a cadeira oferece apoio lombar reforçado e ajustes de altura, garantindo postura correta e bem-estar. Ideal para escritórios, home offices e espaços corporativos. Características Técnicas: Marca: Nakasaki Sistema giratório 360° Regulagem de altura Função Relax para reclinação Apoio lombar ergonômico Fácil montagem Suporta até 120 kg Dimensões Aproximadas: Encosto: L 50cm x A 68cm | Altura do chão: 110–120cm Assento: P 52cm x L 52cm | Altura do chão: 45–55cm Braços: C 44cm x L 7cm | Altura do chão: 66–76cm Base: Estrela com diâmetro de 70cm Dimensões da Embalagem: Largura: 33cm Altura: 60cm Profundidade: 80cm Itens Inclusos: 1x Cadeira desmontada 1x Manual de montagem 1x Ferramenta para montagem 1x Nota fiscal eletrônica Garantia do Vendedor: 3 meses', 699.0, 433.39, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-820mg-mqcciuo6eqki64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177369665%2F23392851233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
