INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9145936168', 'Chocker Corrente Feminina Prata 925 Grumet 4mm - Grossa', 'Choker prata 925 grumet 4mm - Prata maciça legitima -tamanho: 35cm + 5 cm extensor -espessura: 4mm - Certificado de Garantia Prata 925 Esta linda peça, fabricada em Prata legítima, teor 925, além de linda trás a simplicidade e a elegância da beleza feminina. A Prata com teor 925, é o metal mais precioso, depois do ouro. Sua legitimidade pode ser confirmada através de sua marcação nas peças e pelo certificado de garantia que oferecemos. Garantimos a autenticidade de nossos produtos. Compre e tenha certeza de receber uma jóia com duração para o resto da vida. A prata 925 é um material que tem garantia e durabilidade permanente, assim como o ouro 18k. Nossas jóias tem certificado de autenticidade reconhecidos no mundo todo, você pode levar em qualquer joalheria para efetuar os testes e comprovar a autenticidade das mesmas.', 379.99, 379.99, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-820l6-mlxs4qrh4s1s81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F9145936168', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
