INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599562093', 'Forno Turbo Elétrico 4 Esteiras SARO FT22 2500W com Interior de Inox Preto 220V', 'O Forno Turbo Elétrico SARO FT22 foi desenvolvido para garantir eficiência máxima e resultados profissionais em sua cozinha. Com 2.500W de Potência e Resistência Blindada, ele é capaz de assar alimentos de forma rápida e uniforme, sem emissão de fumaça, ideal para cozinhas compactas ou ambientes com pouca ventilação. Sua estrutura robusta com interior em Inox e 4 Esteiras proporciona maior capacidade e durabilidade, sendo a escolha perfeita para estabelecimentos comerciais ou uso doméstico avançado. Aproveite a alta performance do Forno Turbo Elétrico SARO FT22 e eleve o nível de sua cozinha. Eficiência, economia e praticidade em um só produto. Garanta já o seu! Especificações: - Largura: 49 cm - Profundidade do Forno: 49 cm - Profundidade do Motor: 12 cm - Altura: 47 cm - NÃO EMITE FUMAÇA: Ao não emitir fumaça este forno se torna ideal para cozinhas pequenas ou ambientes com pouca ventilação. - BAIXO CONSUMO: Único forno com resistência blindada de mega potência, além de ser mais potente também é muito mais econômica. - MUITO MAIS POTÊNCIA: 2.500W de potência permite assar seu alimento muito mais rápido e com um sabor inigualável. - CARACTERÍSTICAS: - Tensão/Voltagem: 220V - Consumo: 1,2 kW/h - Potência da Resistência: 2.500W - Potência do Motor: 1/30CV - Medidas Externas: 49x60x45cm (CxLxA) - Medidas Internas: 46x44x33cm (CxLxA) - Temperatura Máxima: 250 °C - Acompanha 4 Esteiras de 35x35cm - Possui Iluminação Interna de 35W - Possui Timer de até 120 Minutos - Possui Controle de Temperatura (50-250 °C) - Possui Paredes com Isolamento Térmico - Cor: Preto', 2049.9, 1849.9, NULL, 'Home Appliances > Kitchen Appliances > Ovens', 'https://cf.shopee.com.br/file/sg-11134201-7rfi7-m3b5