INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259157585', 'Chuteira de Campo Joma Aguila Cup Branco e Preto', 'DESCRIÇÃO Chuteira de corte clássico, desenhadas para jogar em terreno firme (FG), como gramado natural dura. Construído com materiais de última geração para ajudá-lo a controlar a bola e permitir que você chute ao gol com precisão. Aproveite o modelo profissional mais sofisticado da Joma. O cabedal é confeccionado em microfibra, material leve, resistente e com excelente abrasão. Além disso, ajuda a absorver o suor, para que o pé permaneça fresco e seco mesmo nos momentos de maior desempenho. Design totalmente renovado e melhorado que elimina a lingueta enrolada para otimizar o ajuste e o conforto. No calcanhar incorporam um contraforte EXO COUNTER para proteger e dar firmeza à zona. Sola confeccionada em material sintético PU de alta qualidade com boa resistência ao desgaste por abrasão. Novo design adaptado ao tipo de terreno para controlar melhor os movimentos em terrenos firmes e não abrasivos. Eles têm uma estrutura de pinos mais alongada. FICHA TÉCNICA - Peso 249g - Futebol de Campo - Indicado para Performance - Pouco Amortecimento - Boa estabilidade - Gênero: Masculino TECNOLOGIA - Durability: Travas em PU com tecnologia DIN-40 que retarda o desgaste do solado aumentando a vida útil do calçado. - Fibertec: Material sintético leve, resistente e confortável que se assemelha ao couro natural oferecendo uma acomodação rápida ao pé. - 360°: Sistema que garante a união da entressola e cabedal facilitando a distribuição de peso em cada passada. - Exo Counter : Peça no contraforte do calçado que garante proteção e estabilidade em cada movimento. CUIDADOS - Chuteira de Campo Aguila foi especificamente projetada para uso em gramados naturais. O uso em outros tipos de gramados ou pisos pode comprometer seu desempenho e levar ao desgaste prematuro. Respeite as indicações de uso para garantir a durabilidade e eficácia do produto. - Limpar com pano úmido e não utilizar produtos químicos que possam ressecar o couro, secar à sombra e manter em local arejado.', 599.99, 300.0, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/sg-11134201-81zw0-mn7iqx9kqv43f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1737983468%2F58259157585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897470080', 'Meia Sapatilha Menina Antiderrapante com Led - Puket', '"Meia com modelagem sapatilha atoalhada com desenho divertido de patins e flocos de neve. Possui aplique de cachorro com Led que é ativado a cada pisada. Produzida com algodão macio em sua maior parte poliamida, e detalhes com fio de lurex. Possui acabamento em viés e elástico confortável. Solado com antiderrapante com aroma de morango. Indicação de uso: Ideal para praticar exercícios e brincadeiras sem o calçado e uso no dia a dia. Instruções de Lavagem: Lavagem a mão Não alvejar Instruções de Conservação: Não secar em tambor Não passar Não limpar a seco (MAIS INFORMAÇÕES, VIDE NA ETIQUETA) Instruções de Garantia: Deverá ser encaminhado dentro na embalagem original ACOMPANHADO DE NOTA FISCAL E com todos os itens constante na solicitação da compra." 64%ALGODÃO;34%POLIAMIDA;2%OUTRAS FIBRAS', 47.9, 47.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7rd5o-lui56skstz69ee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805460736%2F23897470080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
