INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9344458261', 'Kit 4 Borracha De Porta Tipo Original Duster 2011 2012 2013', 'Detalhes do Produto: Kit 04 Borracha De Porta Tipo Original Sandero e Logan 2007 Até 2014 e Duster 2011 Até 2016 Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Sandero 2007 2008 2009 2010 2011 2012 2013 2014 Logan 2007 2008 2009 2010 2011 2012 2013 2014 Duster 2011 2012 2013 2014 2015 2016 Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor de 4 borrachas (serve para todas portas) Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 04 Borrachas de porta (02 anos de garantia)', 308.98, 308.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/fda2b4fc357f5bf30286ea6fd3fde082', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F9344458261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598520017', 'Sanduicheira Grill com Acabamento Inox 127V 750W Multi - CE164', 'Sanduicheira Grill com Acabamento Inox 127V 750W Multi - CE164 Obtenha praticidade na hora de cozinhar com a Sanduicheira e Minigrill da Multi! Ideal para sanduíches, bifes, hambúrgueres, frangos, vegetais, panquecas, e muito mais. Seu material é de ótima qualidade, conta com chapas onduladas antiaderentes que fazem que o alimento não grude durante o preparo, sua comida vai ficar mais suculenta e saudável, com mais sabor e menos gordura, pois não necessita de óleo, além de facilitar na hora da limpeza. A luz indicadora de funcionamento, mostra quando o produto está em funcionamento e quando está em aquecimento, possui trava de fechamento para facilitar o armazenamento do produto quando não está em uso e também alça fria que não esquenta, te proporcionando mais segurança e estabilidade durante o preparo do seu alimento. Além de tudo tem um acabamento em inox, proporcionando ainda mais charme para o preparo do seu lanchinho a qualquer hora do dia! Ficha Técnica Marca: Multi Modelo: Sanduicheira Grill com Acabamento Inox 127V 750W Multi - CE164 Cor: Preto Tensão: 127V Potência Total: 750W Dimensões (LxAxC): 21.5 x 8 x 21.5cm Peso: 1133.000g Garantia: 1 ano Imagens meramente ilustrativas.', 131.89, 131.89, NULL, 'Home & Living > Kitchenware > Grills & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7qvd6-lgvbznlnkxqybb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F750964153%2F19598520017', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
