INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208448578', 'Prato de Sobremesa Fogli 19cm Porcelana Tramontina', 'Prato de Sobremesa Tramontina Fogli 19cm – Delicadeza e Elegância para o Seu Momento à Mesa O Prato de Sobremesa Tramontina Fogli é perfeito para quem deseja servir sobremesas com charme e sofisticação. Seu design delicado com estampa inspirada em folhas e flores traz leveza à mesa, tornando cada refeição um momento ainda mais especial. Produzido em porcelana de alta qualidade, possui resistência e durabilidade superiores, além de garantir porosidade próxima de zero — o que evita a absorção de umidade e a proliferação de fungos e bactérias. Compatível com micro-ondas e lava-louças, é uma peça prática e funcional para o dia a dia ou ocasiões especiais. Design delicado com estampa inspirada na natureza Porcelana de alta resistência e durabilidade Superfície lisa e de fácil higienização Compatível com micro-ondas e lava-louças Ideal para servir sobremesas, frutas e pequenas porções Estilo elegante que harmoniza com diversas composições de mesa Ideal para quem aprecia beleza, qualidade e sofisticação em cada detalhe da mesa posta.', 34.9, 24.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-81zus-mmt6duqwzaiqbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349137150%2F58208448578', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493742084', '4 Litros Óleo Lubrificante Motor Sintético Selenia 5w30', 'Apresentamos o Óleo Lubrificante Motor Sintético Selenia 1 Litro 5w30, da renomada marca Petronas. Este produto de alta qualidade é ideal para carros, picapes e SUVs, proporcionando uma lubrificação superior e proteção duradoura para o seu motor. Com um volume de 1 litro, este óleo sintético é perfeito para manter o seu veículo a funcionar de forma suave e eficiente. O Óleo Lubrificante Motor Sintético Selenia 1 Litro 5w30 é apresentado numa prática garrafa, tornando a sua aplicação fácil e sem complicações. O seu grau de viscosidade de 5W-30 garante um desempenho excepcional em todas as condições climáticas, protegendo o seu motor contra o desgaste e prolongando a sua vida útil. Este produto faz parte da linha Selenia Perform da Petronas, uma gama de lubrificantes de motor de alta qualidade que são conhecidos pela sua durabilidade e desempenho superior. Cada embalagem contém uma unidade de 1 litro, proporcionando uma quantidade suficiente para uma troca de óleo completa na maioria dos veículos. Investir no Óleo Lubrificante Motor Sintético Selenia 1 Litro 5w30 é investir na saúde e longevidade do seu motor. Este produto de alta qualidade da Petronas irá ajudá-lo a manter o seu veículo a funcionar de forma suave e eficiente, protegendo o seu investimento e proporcionando-lhe paz de espírito. Não perca a oportunidade de proporcionar ao seu veículo o cuidado que ele merece. Marca: Petronas Linha: Selenia Perform Grau de viscosidade: 5W-30 Tipo de recipiente: Garrafa Modelo detalhado: Selenia Tipo de óleo de motor: Sintético Durabilidade: 10 mil km', 198.0, 198.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd4r-m6qw2efkycdg90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1463823458%2F22493742084', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
