INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297458106', 'Tinta Exterior Eucatex Rendimento Extra Acrílica 18l Cores', 'Eucatex Rendimento Extra ======================================================================= #ProdutoComNotaFiscal #EnviamosParaTodoOBrasil #RetiradaEmLoja #QualidadeGarantida ======================================================================= Eucatex Rendimento Extra - Tinta Acrílica Standard Fosca Alto Rendimento • Ótima Cobertura • Uso Interno e Externo A Tinta Acrílica Eucatex Rendimento Extra é a escolha ideal para quem busca economia sem abrir mão da qualidade. Super concentrada, ela garante alto rendimento, excelente cobertura e um acabamento fosco impecável, tanto em áreas internas quanto externas. Benefícios: ✅ Super concentrada – rende muito mais ✅ Excelente cobertura com menos demãos ✅ Acabamento fosco de alta qualidade ✅ Aplicação fácil e rápida ✅ Pode ser usada em ambientes internos e externos ✅ Sem cheiro após 3 horas da aplicação Ideal para quem quer renovar paredes com economia e eficiência, com a confiança de uma marca tradicional como a Eucatex. ESPECIFICAÇÕES TÉCNICAS ======================================================================= SUPERFÍCIE: Uso externo e interno. -Alvenaria. DILUIÇÃO: Com água: -Rolo de lã, trincha e pincel: de 50% a 80% em todas as demãos -Pist0la: de 50% a 80% de água RENDIMENTO: até 170m² por embalagem / pintura acabada EMBALAGEM: Lata (18L) DEMÃOS: 2 a 3, com intervalo de 4 horas entre as demãos SECAGEM: -Ao toque: 1 hora -Entre demãos: 4 horas -Final: 12 horas APLICAÇÃO: -Rolo de lã -Pincel -Trincha -Pist0la As cores podem sofrer variações de acordo com o tipo, configuração e resolução do seu aparelho. Considere apenas como uma referência. Para uma visualização mais precisa, consulte o catálogo do produto disponível em lojas e, sempre que possível, faça um teste no local a ser pintado utilizando uma pequena quantidade de tinta na cor escolhida. ======================================================================= #suvinil #tinta branca 18 litros #tintaparaareaexterna #tinta coral 18 litros #tinta latex 18 litros #rekol #acrilica #tinta acrílica #eucatex #tinta extra #lata de tinta #acrilex #tinta de parede #externa #fosco #tinta fosca', 427.9, 270.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m15zn4gmdylvba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1027399414%2F19297458106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
