INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8815121060', 'AMOR NOS TEMPOS DO COLERA, O - RECORD', 'Um dos livros mais importantes de Gabriel García Márquez.Ainda muito jovem, o telegrafista, violinista e poeta Gabriel Elígio Garciá se apaixonou por Luiza Márquez, mas o romance enfrentou a oposição do pai da moça, coronel Nicolas, que tentou impedir o casamento enviando a filha ao interior numa viagem de um ano. Para manter seu amor, Gabriel montou, com a ajuda de amigos telegrafistas, uma rede de comunicação que alcançava Luiza onde ela estivesse.Essa é a história real dos pais de Gabriel García Márquez e foi ponto de partida de O amor nos tempos do cólera, que acompanha a paixão do telegrafista, violinista e poeta Florentino Ariza por Fermina Daza. O livro começou a ser escrito em 1984, em Cartagena de las Índias, ao final do ano sabático que García Márquez se concedeu após receber o Prêmio Nobel. Ali, o autor recolheu alguns dos episódios contados no livro, como a epidemia de cólera que assolou a cidade no final do século XIX ou o naufrágio do galeão espanhol San Jose, carregado de jóias.O amor nos tempos do cólera, como seu próprio nome entrega, é uma belíssima história de amor, daquela pontuadas por cartas perfumadas e pétalas de flores prensadas entre as folhas. E não apenas uma simples história, mas um grande tratado do amor.O tratado nunca escrito por Florentino Ariza, que guardava em três volumes três mil modelos de cartas para namorados, nos quais estavam todas as possibilidades do amor. O amor apaixonado da adolescência, o amor conjugal, o clandestino, o tímido, o amor sexual ou libertino. O tédio do amor, suas lutas, esquecimentos, metamorfoses, suas deslealdades e doenças, triunfos, angústias e prazeres. O amor por carta, o despertar desse amor, próximo ou distante, o amor louco. O amor de meio século, que encontra os amantes septuagenários se tocando pela primeira vez. O amor que se guarda e espera, enfim, sua realização.', 76.4, 76.4, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/19f5dc8f2362f40e07b4e61a31cd8634', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F8815121060', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
