INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6157450515', 'Papel De Parede Autocolante Adesivo Cimento Queimado Lavável', 'Produto em tons predominante de branco e cinza, não tem relevo. Papel de parede é um adesivo vinílico, autocolante e lavável. Produzido em impressão digital, sem relevo. Ideal para decoração de sala, quarto, cozinha, banheiro ou outros ambientes. Cada unidade contem a medida de 3,00 metros de altura x 40 centímetros de largura. Papel de parede, autocolante, lavável e fosco. Impresso em material 0.10 Material: PVC vinílico, polimérico fosco e não tem cheiro. Antibactericida, Antimofo e não propaga chamas Dica para aplicação: Limpe o local com um pano úmido, certifique-se de retirar todo o pó da parede para melhor fixação do produto. Abra o papel em uma superfície plana, verifique a emenda do produto e alinhamento do mesmo. Vitalidade da aplicação, média esperada: Interna 5 anos. Externa 2 anos.', 54.9, 32.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/3e87d56de0cb889dfe2f430668cd8d7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F6157450515', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
