INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12523628344', 'MOTOR DE PARTIDA CATERPILLAR 120B Motor 3306 3304 24V 12 DENTES', 'CHUCAR | Especialistas em Peças Elétricas Automotivas Qualidade • Agilidade • Confiança há mais de 30 anos ATENÇÃO Compare o código da peça antiga/original com o informado neste anúncio antes da compra. DESCRIÇÃO DO PRODUTO Motor de arranque CATERPILLAR 120B 24V 12 DENTES Aplicação: CATERPILLAR 120B Motor 3306 3304 OEM: 9000084007 2Y1920 C7007 D20412 RD17086 SOBRE A CHUCAR Especialistas na distribuição de peças elétricas automotivas há mais de 30 anos. Produtos com garantia, nota fiscal e envio rápido para todo o Brasil. LOJA FÍSICA Atendimento de segunda a sexta, das 08h às 18h. Para mais informações, consulte nossos vendedores. MARCA Enviada conforme disponibilidade em estoque ambas certificadas com padrão de qualidade equivalente. Produto novo e lacrado. ENVIO Pedidos confirmados até 14h são enviados no mesmo dia útil. - Em caso de dúvida, informe modelo, ano e motorização no campo de perguntas.', 2400.0, 2400.0, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/br-11134207-81ztq-ml22knfyx4oxaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F554529780%2F12523628344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294236380', 'Kit Escovas Com Esponja Para Mamadeiras E Bicos - Buba', '🍼 Kit 2 Escovas Para Lavar Mamadeira e Bico Azul - Buba Chega de sofrer para limpar os cantinhos da mamadeira do seu bebê! O Kit de Escovas da Buba foi desenhado especialmente para alcançar as áreas mais difíceis, garantindo uma higienização completa, rápida e sem esforço. É o cuidado e a segurança que o seu pequeno merece, com a praticidade que você precisa no dia a dia. ✨ Por que escolher o Kit de Escovas Buba? • Dupla Eficiência: Vem com 1 escova grande (para o corpo da mamadeira) e 1 escova menor (perfeita para o bico). • Limpeza Sem Riscos: A escova maior possui uma esponja macia na ponta, que remove os resíduos de leite mais difíceis sem riscar ou danificar o plástico/vidro. • Formato Anatômico: Cerdas flexíveis e cabeça curva que se adaptam a qualquer formato de mamadeira. • Secagem Rápida e Higiênica: O cabo possui um gancho prático para pendurar, evitando o acúmulo de bactérias na pia. • 100% Seguro: Produto totalmente Livre de BPA e Ftalatos (atóxico). 🛠️ Especificações Técnicas: • Marca: Buba (Original) • Cor: Azul • Material: Cabo e cerdas em Polipropileno (durável), base em aço inoxidável e esponja de alta qualidade. • Dimensões Aproximadas: - Escova Grande: 23 cm - Escova Pequena: 12 cm • Conteúdo da Embalagem: 01 Escova de Mamadeira e 01 Escova de Bico. 💡 Dica de Uso e Conservação: 1 - Utilize a escova menor com movimentos suaves para lavar o interior dos bicos. 2 - Use a escova maior para o corpo da mamadeira, aproveitando a esponja para o fundo. 3 - Após o uso, enxágue bem, retire o excesso de água e pendure pelo gancho para secar naturalmente.', 15.88, 15.88, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-mc98akr5cf4h31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22294236380', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
