INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994195788', 'Cômoda Penteadeira Modena 100% MDF 6 Gavetas e Espelho', 'A Cômoda Penteadeira Modena 100% MDF 6 Gavetas e Espelho é o móvel perfeito para criar seu cantinho de beleza. Fabricada em 100% MDF de alta qualidade, combina funcionalidade e sofisticação para elevar sua rotina de cuidados pessoais. Acabamento: Pintura U.V. Touch com 7 camadas de proteção, garantindo proteção e beleza duradoura. Destaques: Imagem Ambientada Meramente Ilustrativa, Itens de Decoração e demais Produtos não fazem parte da Oferta. Informações Técnicas: Fabricante: MH Móveis Ambiente: QuartoEstrutura em 100% MDFAcabamento com pintura U.V. Touch com 7 camadas de proteção 6 Gavetas Corrediças Telescópicas 1 Espelho Dimensões Totais (Queen): Altura1,66m Largura1,79m Profundidade45,4cm Garantia:6 Meses Contra defeitos de Fabricação', 979.1, 881.19, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvk-mbwits42iiljc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1573190120%2F23994195788', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
