INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198401946', 'Par Farol De Milha Asx Toyota 12-60v 5.000 Lumens 40w 6000k', 'Descrição OBS: APÓS INSTALADO NOS PRIMEIROS DIAS O FAROL DE MILHA PODE FICAR EMBAÇADO (SUADO) É NORMAL, QUANTO MAIS USAR MAIS RÁPIDO ELE SOME ESSE EMBAÇADO. DESCRIÇÃO Kit farol de milha LED o mais novo lançamento da ASX, trazendo inovação e qualidade em iluminação. Um kit padrão original que já é em led, não precisando colocar nenhuma lâmpada, com um foco e linha de corte perfeita padrão projetor LED. Além, de deixar um visual muito mais moderno em seu veiculo, sendo um farol auxiliar de LED. Fácil instalação com chicote padrão original de fábrica. Compatibilidade de instalação: TOYOTA - Corolla XEI 2010/Corolla 14/18; Hilux 16/20; Yaris 18/... Especificação Técnica: • Marca: ASX • Tamanho: Padrão Original • Material: Lente em Policarbonato • Tecnologia Japonesa: LED CHIP • Sistema de dissipação: Dissipador em Alumínio • Taxa impermeável: IP65 (resistente a água) • Eficiência de LM: 5.000 Lúmens • Ângulo de irritação: 360 graus • Temperatura de Trabalho: -40 ° C ~ 105 ° C • Consumo: 40W Cada • Voltagem: BIVOLT • Voltagem: DC 12V - 60V • Cor de Temperatura : 6000K Extremamente Branca • Projetor de Foco • Regulador de Altura Conteúdo da Embalagem: (1 KIT) PAR DE FAROL DE MILHA TOYOTA LED 40W 5000LM 6000K 12V~60V ASX Importante: - A INSTALAÇÃO DEVE SER FEITA POR UM PROFISSIONAL ESPECIALIZADO. - NÃO NOS RESPONSABILIZAMOS POR INSTALAÇÕES MAL FEITAS. - QUALQUER INSTALAÇÃO QUE DANIFIQUE O PRODUTO A GARANTIA NÃO IRÁ COBRIR.', 227.0, 227.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-820m1-mr08c5go8xl135', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1105905560%2F22198401946', NULL, NUL