INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698053642', 'Jogo 4 Pneus Pirelli Aro 15 Cinturato P1 (KA) 195/65R15 91H', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores.O pneu Pirelli Cinturato P1 foi desenvolvido pela Pirelli para equipar carros pequenos e médios, oferecendo bom desempenho em estabilidade e aderência, sem abrir mão da alta durabilidade e resistência dos pneus Pirelli. Sua banda de rodagem tem amplas nervuras, que garantem contato com o solo constante, dando apoio nas curvas e ótimas frenagens. Sobre a marca Pirelli A Pirelli nasceu na Itália há mais de 100 anos, em Milão. Com longa tradição na construção de pneus, a marca produz soluções para carros, motos, tratores, caminhões e ônibus e possui fábricas espalhadas pelo mundo. A Pirelli é a atual fornecedora de pneus da Fórmula 1, a principal categoria do automobilismo mundial, e possui longa tradição em pneus de alto desempenho.', 2543.53, 2340.05, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rff8-m32bmgkl4wqxa9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23698053642', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
