INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094185193', 'Cômoda Sapateira Londres 2004142 Atacama Off White - Aramóveis', 'Cômoda Sapateira Londres 2004142 Atacama Off White - Aramóveis Cômoda Sapateira Londres 2004142 Atacama Off White - Aramóveis Unindo sofisticação e funcionalidade a Aramóveis desenvolveu a Cômoda Londres. Este modelo conta com um design elegante e atemporal que se adapta perfeitamente a qualquer ambiente, trazendo organização e charme ao seu espaço. Suas gavetas espaçosas são ideais para armazenar roupas, acessórios e outros itens, enquanto sua construção robusta garante durabilidade e qualidade. Perfeita para quem valoriza organização sem abrir mão do estilo, a Cômoda Londres é a escolha certa para transformar sua casa com praticidade e bom gosto! Confira e aproveite! Características Técnicas: - Desenvolvido em MDP 12 e 15mm - 4 Gavetas - 2 Portas - Puxadores em PVC - Corrediças metálicas - Dobradiças metálicas - Acabamento em verniz brilho - Amplo espaço - Design moderno Dimensões: Altura: 120,8 cm Largura: 115,2 cm Profundidade: 44,6 cm OBS: Não acompanha decorações, roupas, calçados e acessórios. Informações importantes: - Não realizamos a montagem ou instalação do produto, porém acompanha manual de instruções. - Toda mercadoria segue segurada contra qualquer sinistro, em caso de anormalidade, recuse. - As caixas ou pacotes possuem identificação com o nome, cidade e quantidades de volumes relativos à compra para conferencia do recebedor.', 350.54, 350.54, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rav9-mb8a2n2kecbta2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22094185193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
