INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259661817', 'Álcool Zumbi Tradicional', 'O Álcool Zumbi 46° INPM é ideal para a limpeza geral da casa, removendo sujeiras difíceis com praticidade e eficiência. Modo de uso: Aplique o produto sobre a superfície a ser limpa e espalhe com um pano. Para limpeza, utilize 100ml do produto para cada 1l de água. Produto não recomendado para superfícies sensíveis ao álcool.', 12.99, 12.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8258l-mqnem2vnml8u2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555041%2F58259661817', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20661902522', 'Cabo Vela Ignição Ford Ka 1.0 2000 A 2008 Ngk', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação FORD KA GL 1.0I ZETEC ROCAM 2000 até 2008 KA GL IMAGE 1.0I/ 1.0I ZETEC ROCAM 2000 até 2003 KA TECNO 1.0I 8V ZETEC ROCAM 2000 Conteúdo Da Embalagem 1 Jogo de Cabo de Vela de Ignição Cor do Produto No Tipo de Veículo para Carros Marca A NGK fabrica itens automotivos desde 1959 no Brasil. Revestimentos porcelanizados, cabos de ignição e velas, terminais supressivos e cerâmicas técnicas fazem parte da extensa gama de produtos da empresa. O Produto Os cabos de ignição têm o papel de conduzir a corrente elétrica do transformador até as velas de ignição partilhando a corrente na ordem certa da ignição do motor. Desta maneira, garante uma ignição sem erros e a perfeita combustão. Só cabos em boas condições poderão permitir energia apropriada para as velas produzirem faísca de qualidade. Importante • Recomendamos que os produtos sejam aplicados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses • Valor referente ao Jogo • Imagem meramente ilustrativa EAN 7897707501311 Código do Fabricante SCF02 Combustível GASOLINA Combustível Gasolina', 114.67, 114.67, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rble-llto344cmbvt11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F20661902522', NULL, NULL, '2026-07-