INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894898613', 'Tanque D''Água de Polietileno 500 Litros - 2070089 - FORTLEV', 'Tanque D''Água de Polietileno 500 Litros - 2070089 - FORTLEV Especificações do produto: Com fechamento rápido e seguro, o Tanque Fortlev possui tampa de 1/4 de volta e vedação total, que impede a entrada de sujeira, de insetos e garante ainda mais a conservação da água. Disponíveis em volumes até 20.000 litros, os Tanques Fortlev vêm com adaptador flange instalado na saída (até 3.000 L: 50 mm x 1.1/2" e de 5.000 L à 20.000 L: 60 mm x 2"), o que facilita a instalação do produto. Características: - Função: Armazenar água a temperatura ambiente. - Aplicação: Residências, instalações comerciais, fazendas, escolas ou qualquer outra aplicação que necessite de armazenamento de água em temperatura ambiente. - Normas técnicas: Reservatórios fabricados conforme Normas NBR 14799 e 15682 da ABNT. Procedimentos de instalação conforme Normas NBR 14800 e 5626 da ABNT. Informações Técnicas: - Capacidade: 500L - (A) Altura total: 0,66 - (B) Diâmetro total: 1,17 - (C) Diâmetro da boca de inspeção: 0,60 - (D) Diâmetro da base: 1,02 - Adaptador flange para saída incluso: 50 mm x 1.1/2" *Imagens meramente ilustrativas.', 640.29, 556.78, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-8258s-mqyt2f8msxs4db', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1742467457%2F22894898613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293493853', 'Lowell Extrato de Mirtilo Mascara 450g', 'Lowell Extrato de Mirtilo Alto Impacto Máscara Capilar para todos os tipos de cabelo. Lowell Extrato de Mirtilo Alto Impacto Capilar promove um tratamento que resgata a aparência saudável do fio e garante brilho intenso. Máscara Capilar Lowell Extrato de Mirtilo foi desenvolvida para auxiliar na hidratação e regeneração completa do cabelo, sem deixar o aspecto pesado. Sua fórmula devolve a maciez e ainda forma um escudo de proteção contra a perda de proteínas. Conselho de Aplicação Com o cabelo limpo e úmido, aplique a máscara do comprimento às pontas. Deixe agir por 3 minutos e enxágue bem. Nossos Experts Ensinam O resultado da máscara capilar depende da aplicação. O ideal é aplicar nos fios úmidos. Nem molhados e nem secos, pois muita água dilui os princípios ativos e o contrário não permite que eles penetrem profundamente no cabelo.', 274.6, 274.6, NULL, 'Beauty > Men''s Care > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-825zy-mjub9nnbarcz40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22293493853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
