INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250743633', 'Filtro Ar Motor Fiat Uno 1.0/1.4 8V Fire Flex Após 2010/ Mobi 1.0 8V Após 2017/ Palio 1.4 8V Flex Após 2011 - 51854598', 'Filtro de Ar para Fiat Uno, Mobi e Palio EVO – Máxima eficiência e proteção para seu motor. Mantenha o desempenho do seu Fiat Uno 1.0/1.4 EVO 8V Fire Flex (2010 em diante), Mobi EVO 1.0 8V (2017 em diante) e Palio 1.4 8V EVO Flex (2011 em diante) com este filtro de ar de alta qualidade. Projetado para garantir a entrada de ar puro, ele protege o motor contra impurezas, aumentando a durabilidade e otimizando o consumo de combustível. Aplicações: FIAT GRAND SIENA 1.4 FLEX - APÓS 2012 FIAT PALIO (novo) 1.0 FLEX - APÓS 2012 FIAT UNO 1.0 EVO 8V Fire FLEX - APÓS 2010 FIAT UNO 1.4 EVO 8V FIRE FLEX - APÓS 2010 FIAT PALIO (novo) 1.4 8V EVO FLEX - APÓS 2011 FIAT FIORINO 1.4 EVO FLEX - APÓS 2014 FIAT UNO NOVO FURGÃO 1.4 - APÓS 2014 FIAT PUNTO 1.4 ATTRACTIVE FLEX - APÓS 2013 FIAT MOBI 1.0 8V EVO - APÓS 2017 FIAT UNO 1.3 109/101cv - APÓS 2017 FIAT UNO MILLE 1.0 FLEX 310 A 1011 EVO 75 cv - APÓS 2010 Especificações: Altura: 70,2mm Largura: 109mm Comprimento: 283,4mm Tipo de Produto: Filtro de Ar Referência: FABR19S Marca: Japanparts EAN: 7898407313655 Números Originais: 51854598', 25.9, 25.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-821eh-mh946a6je7f02d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F794835204%2F58250743633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799547509', 'L''Oréal Paris Magic Retouch Castanho Claro - Corretivo de Raiz 75ml', 'L''Oréal Paris Magic Retouch Castanho Claro Corretivo de raiz. L''Oréal Paris Magic Retouch cobre as raízes brancas em apenas 3 segundos. Sua aplicação em spray é precisa, rápida e prática; perfeita para aquela semana que não deu para ir ao cabeleireiro retocar a coloração. L''Oréal Paris Magic Retouch tem secagem rápida e sai facilmente com o simples uso de shampoo. Ele também não escorre e nem mancha. Sua fórmula se adapta à cor dos fios. 3, 2, 1 Adeus raízes! Como Usar L''Oréal Paris Magic Retouch Castanho Claro Conselho de Aplicação Primeiro, agite bem o produto. Em seguida, com o cabelo seco, penteado e ajeitado, aplique o spray diretamente na raiz com uma distância de 15cm. Dê borrifadas leves, em jatos curtos, para evitar o excesso. A aplicação de 3 segundos já é suficiente para cobrir os fios brancos. Aguarde um minuto para secar e pronto. Caso haja o acúmulo de produto no cabelo, passe um pente para tirar o excesso. Um spray de 75ml do corretivo de raiz instantâneo rende, em média, 25 aplicações. Resultado Seu cabelo fica sem as raízes brancas e você, pronta para qualquer ocasião.', 112.45, 66.9, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rdxi-m1fw1e8ui3wdd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F19799547509', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55854345944', 'Gabriela Sabatini Kit Coffret Eau de Toilette Necessaire (2 produtos)', 'Gabriela Sabatini Kit Coffret - elegância e confiança em uma fragrância irresistível Este Kit Contém Gabriela Sabatini Eau de Toilette - Perfume Feminino 60ml: é a escolha perfeita para mulheres que irradiam confiança e elegância natural. Sua fragrância floral ambarada combina frescor vibrante, flores envolventes e um toque quente que abraça a pele com sofisticação. Gabriela Sabatini Necessaire: necessaire prática e charmosa, ideal para levar sua essência favorita sempre com você. Um presente marcante, para si mesma ou para alguém especial. Conselho de Aplicação Perfume: borrife uma pequena quantidade de produto diretamente sobre a pele, que deve estar limpa e seca. Para prolongar a durabilidade da fragrância, experimente aplicá-la em áreas estratégicas do corpo, como nuca, pulsos e dobras dos cotovelos.', 274.6, 145.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8262k-mj8gbp62rif61c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F55854345944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397908169', 'Kit BRAE Divine Anti-Frizz - Shampoo 250ml (2 Unidades)', 'Kit BRAE Divine Anti-Frizz - Shampoo 250ml (2 Unidades) Shampoo para cabelos com frizz. Braé Divine deixa os fios mais alinhados e disciplinados durante a limpeza. O Shampoo Braé Divine combina ativos com tecnologias para eliminar o volume e proporcionar um cabelo mais controlado. É perfeito para quem já tem química e deseja manter o efeito liso duradouro. Como Usar Conselho de Aplicação Aplique o shampoo nos cabelos molhados e massageie o couro cabeludo até formar espuma. Enxágue. Repita o procedimento se sentir necessidade.', 209.69, 123.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdyr-m13gyiyolscnb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23397908169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699495288', 'Kit Wella Professionals Invigo Balance Aqua Pure Shampoo Extra e Válvula (4 produtos)', 'Kit Wella Professionals Invigo Balance Aqua Pure Shampoo Extra e Válvula (4 produtos) Esse Kit Contém Wella Professionals Invigo Balance Aqua Pure 1L (2 unidades): Shampoo de limpeza profunda para todos os tipos de cabelo. Wella Professionals Invigo Balance Aqua Pure Shampoo remove impurezas residuais e poluentes. Ele deixa uma sensação de frescor, especialmente devido à fragrância suave de lótus. revitaliza e cuida do couro cabeludo, além de comprimento e pontas, para que se mantenham saudáveis. Seu cabelo fica limpo e equilibrado por inteiro, além de com uma sensação fresca gostosa. Válvula Pump para 1L (2 unidades): Dosadora auxilia você a controlar o uso dos seus produtos e evitar o desperdício. Facilita a rotina dos procedimentos nos salões de beleza ou até mesmo os resultados profissionais em casa. Conselho de Aplicação Shampoo: aplique o shampoo sobre o cabelo úmido. Massageie suavemente. Em seguida, enxágue.', 447.05, 447.05, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdx4-m15pezu9vj0q66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F19699495288', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898301304', 'Gerador de Energia 3.8kva a Gasolina 110v220v 7hp Monofásico', 'Gerador de Energia 3.8kva a Gasolina 110v/220v 7hp Monofásico - NG3900B - Nagano Você merece a tranquilidade de nunca ficar no escuro. O Gerador de Energia a Gasolina Nagano NG3900B é a solução confiável para residências, comércios e indústrias que não podem parar por falta de energia. Potência e Desempenho Com potência máxima de 3.8 KVA, este gerador entrega energia suficiente para manter equipamentos essenciais e aparelhos elétricos funcionando sem interrupções, garantindo confiabilidade em qualquer situação. Desafios Quedas frequentes de energia. Interrupção de atividades comerciais e industriais. Perda de conforto e produtividade em casa. Soluções O Gerador Nagano NG3900B foi desenvolvido para suprir essas necessidades com: Partida manual para total controle na hora do uso. Alerta de nível de óleo, garantindo operação segura. Versatilidade em tensão (110/220V) com regulador AVR para aplicações em diferentes cenários. Eficiência e Sustentabilidade Com baixo consumo de combustível e motor de 7HP, 4 tempos, refrigerado a ar, este gerador alia economia à confiabilidade. A capacidade de 15 litros no tanque assegura horas de funcionamento contínuo, com a robus', 1532.8, 1532.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwm-mdnlkc5hu0juc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F18898301304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193442262', 'Cozinha Itatiaia Rose Compacta 3 Pecas Branco', 'Conjunto Cozinha Itatiaia Rose 3 Peças Branco com Paneleiro, Armário Aéreo e Nicho aberto decorativo Soluções práticas e extremamente funcionais e criativas para organizar a sua casa com praticidade, otimizando o espaço e guardando todos os seus utensílios é o que a Itatiaia te oferece! A cozinha de aço Rose possui a versatilidade que você precisa! Paneleiro com portas altas, aproveita o espaço vertical para você ganhar usabilidade. Tamanho ideal, com prateleiras bem distribuídas que cabem mantimentos, utensílios e eletrodomésticos. Possui nicho aberto decorativo e puxadores metalizados e ergonômicos, conferindo modernidade, organização, beleza e resistência. ATENÇÃO: - Não nos responsabilizamos pela montagem / instalação dos produtos. - Imagens meramente ilustrativas. - Verifique com os fabricantes dos produtos eventuais limitações à utilização de todos os recursos e funcionalidades. INFORMAÇÕES TÉCNICAS: Marca: Itatiaia Modelo: COZ ROSE BRA Linha: Rose Cor: Branco Neve Acabamento: Brilho Material: Aço Pintura/Revestimento: Pintura Eletrostática A Pó Acompanha Tampo: Não Acompanha Pia Inox: Não Quantidade De Portas: 7 Portas Tipo De Porta: Bater Dobradiças: Metálicas Necessita De Montagem: Sim Prateleiras: 6 Prateleiras Pés: Não Acompanha Puxadores: Em Ps Dimensões Do Produto Montado: 28,0 (P) x 245,0 (L) x 165,0 (A) Embalagem Peso (Kg): 32,53 Quantidade De Volumes: 1 Garantia: 12 meses SAC: 0800 032 6111', 899.9, 719.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-820mb-mq6k83lr7ksj69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F680601528%2F22193442262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
