INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56801669618', 'Bíblia Sagrada NTLH | Letra Grande | Edição com auxílios para Presos e Egressos |Brochura |Liberdade', 'Bíblia Sagrada Bíblia Sagrada possui letra grande o que a torna ideal para a leitura diária e para a compreensão da Palavra de Deus. - Letra Grande - Nova Tradução na Linguagem de Hoje (NTLH) Desfrute de uma leitura mais confortável com esta Bíblia em LETRA GRANDE, ideal para longos períodos de estudo e meditação. ✓ RECURSOS ESPECIAIS: Letra Grande para leitura facilitada Conteúdo da Bíblia Vocabulário NTLH06LG ✓ ACABAMENTO PREMIUM: Durável e resistente ao uso diário Design elegante e atemporal Perfeita para presente ou uso pessoal ✓ TRADUÇÃO : Tradução cuidadosamente elaborada para transmitir com fidelidade a mensagem das Escrituras Sagradas. Perfeita para estudo pessoal, meditação diária, uso em cultos e como presente significativo. Uma edição que combina qualidade, durabilidade e beleza. Código: NTLH060LG-LIBER | GTIN: 7899938427101 14x21cm 1480 Páginas', 50.9, 50.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821do-mh8bazeaqrk9e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F56801669618', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50205361343', 'Bíblia Diária NVI | Leitura Perfeita | Capa Dura Tecido | Coração Florido', 'Acompanha caderno exclusivo. A BÍBLIA PARA O SEU MOMENTO DIÁRIO COM DEUS! A Bíblia Diária é um convite às maravilhas da leitura da Palavra de Deus todos os dias. Nela, você encontra o texto bíblico dividido em porções do Antigo Testamento, do Novo Testamento, e dos livros poéticos, como Salmos e Provérbios, intercalados. Além disso, ela conta com o diferencial de um texto devocional sobre as leituras de cada dia, que serve como uma preparação para a porção que você lerá. É a Bíblia perfeita para acompanhar você todos os dias, pois ajudará a desenvolver profundidade no relacionamento com o Pai. Aprofunde seu conhecimento, desfrute do aprendizado da Palavra e receba uma porção do céu diariamente. Características que se destacam: Texto revisado da Nova Versão Internacional (NVI). Fonte Leitura Perfeita, uma tipologia exclusiva Thomas Nelson que promove conforto na leitura. Texto bíblico organizado por dias do ano, com diagramação própria para textos poéticos e diálogos assinalados com travessões. Textos diários não datados, para você escolher o melhor dia para iniciar sua leitura. 21X16 CM 1328 Páginas', 127.9, 123.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-82626-mjy9i3xmk4xs2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F50205361343', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
