INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197752221', 'Escova Rotativa Limpeza Rodas Bancos Tapete Limpeza Em Geral', 'Distribuído por Ismafer Ferramentas Kit Escova de Limpeza Rotativa Jogo com 3 Tamanhos Diferentes Uso com Parafusadeira e Furadeira Agora você vai limpar superfícies de banheiros, cozinha, carros e móveis em geral, sem esforço. Eles podem ser anexados à sua broca sextavada elétrica, economizando trabalho e esforço manual. Com 3 diferentes tamanhos e formas de escovas para limpar em torno de superfícies do banheiro, sofá, entre outros. Todas as escovas têm eixos de metal, que é fácil de instalar, encaixando em sua parafusadeira ou furadeira. Apropriado para carros, banheiras, pias, cozinha, cercos de chuveiro de fibra de vidro etc. Especificação: Material do fio da escova: Nylon Uso: Sofá, Box, Estofados, Banheiro, Tapetes, Banco Automotivo, Azulejo, etc Tipo do punho da escova: Parafuso hexagonal Tamanho do conector da Broca: 1/4" Tamanho: 2/3. 5/4" Peso: 245g Garantia: 3 meses pelo fornecedor SKU: 23233 Distribuído por Ismafer Ferramentas', 45.0, 29.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Brushes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m328p35uerdf2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F23197752221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892967860', 'Camera de Ré Estacionamento Automotivo Para Carro Visão Noturna Colorida Prova D''água', 'Se você é um motorista que sempre fica nervoso na hora de estacionar o carro, precisa conhecer a Câmera de Ré Automotiva Visão Noturna Colorida. Com essa câmera incrível, estacionar o seu veículo nunca mais será um problema. Os ícones de praticidade, facilidade e segurança vão te conquistar e você não vai mais conseguir ficar sem uma dessas no seu carro. A Câmera de Ré Automotiva Visão Noturna Colorida possui um design moderno e resistente, garantindo alta durabilidade. Com ela, você terá uma visão completa da parte traseira do seu veículo, mesmo no escuro, e poderá manobrar com muito mais confiança em estacionamentos lotados ou em ruas movimentadas. Especificações Técnicas: - Modelo: Borboleta Traseira - Sensor de Imagem: CMOS COLOR - Resolução Horizontal: 420TVL - Iluminação Mínima: <0,2 Lux - Ângulo de Lente: 170° - Alimentação: 12V DC - Classificação: IP67 - Sistema de Sinal: PAL/NTSC A Câmera de Ré Automotiva Visão Noturna Colorida possui linhas guias coloridas, que auxiliam na precisão das manobras. Além disso, ela é à prova d''água, garantindo seu funcionamento mesmo em dias chuvosos. A instalação da câmera é simples e rápida, e ela é compatível com a maioria dos modelos de veículos. Aproveite a postagem rápida em 24 horas úteis e adquira já a sua Câmera de Ré Automotiva Visão Noturna Colorida. Estacionar nunca foi tão fácil e seguro!', 40.97, 35.12, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Parking Cameras and Sensors', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lu7z0198790la8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F22892967860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
