INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18538666881', 'Pinador pneumático capacidade de 10 a 50 mm - 574109 - MTX', 'Produto: Pinador pneumático capacidade de 10 a 50 mm - 574109 Marca: MTX Descrição: O Pinador pneumático capacidade de 10 a 50 mm 574109 da MTX é a ferramenta ideal para profissionais que buscam eficiência e precisão em seus projetos de carpintaria e marcenaria. Desenhado especialmente para acomodar pinos que variam de 10 a 50 mm, este pinador destaca-se pela sua versatilidade e desempenho superior. Adequado para uma ampla gama de materiais, desde pisos de madeira até placas de gesso, o pinador da MTX garante uma fixação rápida e confiável, eliminando a necessidade de retoques frequentes. Equipado com uma faixa de pressão operacional de 65 a 110 psi, adapta-se perfeitamente a diversas densidades de materiais, promovendo uma aplicação precisa e sem danos. Características: • Capacidade Versátil: Aceita pinos que variam de 10 a 50mm, proporcionando flexibilidade para diversos projetos. • Alto Desempenho: Opera entre 65 a 110 psi, garantindo força e precisão na fixação dos pinos em diversas superfícies. • Design Ergonômico: Projetado pensando no conforto do usuário, facilitando o manuseio prolongado sem fadiga. • Construção Durável: Fabricado com materiais de alta qualidade para assegurar uma longa vida útil mesmo sob uso contínuo. • Aplicação Multifuncional: Perfeito para trabalhos em diversos materiais, ideal para marcenaria, decoração e muitos outros. Especificações: Medida do pino: 10 - 50 mm. Pressão de trabalho: 65 - 110 psi. Peso: 1.12 Kg', 248.95, 214.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-825ak-mr25ee42t9n0a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F18538666881', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26334604726', 'Botão Interruptor Vidro Elétrico do Passageiro Tucson 2005 até 2012 - LED Verde', 'Botão Vidro Elétrico Tucson LED Verde Interruptor Passageiro Simples 2005 2006 2007 2008 2009 2010 2011 2012 YN-KGHY2420 Autopeças Carona Dianteiro Compatível Substituição Qualidade Renove o interior do seu Tucson com o Botão de Vidro Elétrico Simples com LED Verde, compatível com modelos de 2005 a 2012. Projetado para a porta dianteira direita (lado do passageiro/carona), este interruptor de 1 botão controla o vidro elétrico com precisão, oferecendo funcionalidade, estilo e iluminação LED verde para melhor visibilidade noturna. Características Principais: Aplicação: Tucson 2005 a 2012 Posição: Dianteiro direito (passageiro) Traseiro direito (atrás do passageiro) Traseiro esquerdo (atrás do motorista) Iluminação: LED verde, ideal para uso noturno Funções: Controle do vidro elétrico do passageiro (1 botão) Código do Produto: YN-KGHY2420 EAN: 7899562624204 Perfeito para substituir botões desgastados ou defeituosos, este interruptor de alta qualidade restaura o controle total do vidro elétrico. A instalação é simples, com encaixe perfeito no painel original, garantindo compatibilidade e durabilidade. Ideal para quem busca autopeças confiáveis com excelente custo-benefício. Por que comprar conosco? Qualidade superior: Produto novo, testado e com acabamento premium Envio imediato: Postagem rápida com nota fiscal Suporte especializado: Atendimento para dúvidas e suporte na instalação Compra protegida: Segurança garantida pelo Pós-venda confiável: Assistência completa para sua satisfação Adquira agora o Botão de Vidro Elétrico com LED Verde e traga mais conforto, praticidade e estilo para o seu Tucson! Peça já a sua substituição ideal!', 35.9, 34.11, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7renz-m8xc5urcqqiodc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F26334604726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598077765', 'Chinelo Havaianas Infantil Fluffy', 'Novidade, o chinelo Havaianas Kids Fluffy promete agradar em cheio minifashionistas de todo o mundo.A sandália vem com solado degradê e traz nas tiras um tecido estampado e confortável, além do logo Havaianas em formato de tag. Ultrafofa!Garanta já esse produto cheio de estilo.', 84.99, 84.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Flip Flops', 'https://cf.shopee.com.br/file/br-11134201-820l9-mqxc76tv15ad89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1090996394%2F19598077765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22996709892', 'Chave phillips isolada 1/8 x 6" aço cromo vanádio - Sata', 'Produto: Chave phillips isolada 1/8 x 6" aço cromo vanádio Marca: Sata Descrição: A Chave phillips isolada 1/8 x 6" aço cromo vanádio" da Sata é ideal para uso profissional pesado, seu cabo ergonômico rígido e resistente injetado em PVC na cor verde transparente deixa aparente a profundidade que a haste está garantindo máxima qualidade e resistência para o trabalho diário. Sua haste isolada de acordo com NR10, garante proteção ao profissional quando utilizadas em trabalhos com áreas energizadas. Atende e supera norma - NBR 9699. Esta Norma aplica-se a ferramentas manuais isoladas e isolantes usadas para trabalho em instalações elétricas energizadas ou peças. Isolação do cabo para 1000v. Conta com ponta oxidada para evitar descascamento e proporcionar mais segurança. Possui a haste toda temperada com acabamento niquelado e cromado. Características: • Haste isolada de acordo com NR10. Garante proteção ao profissional quando utilizadas em trabalhos com áreas energizadas • Ponta oxidada: diminui o descascamento proporcionando maior segurança e durabilidade da ponta da chave • Haste fabricada em Cromo-Vanádio (Cr-V): parâmetros industriais que o profissional deseja • Extremidade sextavada no cabo: permite aperto adicional com o encaixe de uma chave • Cabo em PVC cristal: alta resistência a quedas e ressecamentos • Empunhadura ergonômica oferece agarre perfeito, sem machucar as mãos, ideal para trabalhos pesados • Cabo injetado junto a haste: formato profissional, garantia de torque sem danificar a junção das partes. Especificações: Material: aço cromo vanádio Medidas: 1/8 x 6" Material do cabo: PVC Norma: NBR 9699 Isolação do cabo: 1000v. Peso: 0.47 Kg', 32.23, 32.23, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259o-mqwgwo60gf0mf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F22996709892', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
