INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45457442194', 'Conjunto Menino Blusão c/ Capuz e Calça Moletom Journey - Angerô', 'Conjunto Menino Blusão c/ Capuz e Calça Moletom Journey - Angerô O conjunto é confeccionado em moletom flanelado. A escolha ideal para proporcionar conforto e estilo no mesmo look. O blusão possui capuz, manga longa com punho e barra ajustada. Trazendo tecido texturizado, possui bordado frontal, bolso canguru e cordão colorido no capuz, agregando charme e estilo ao visual. A calça possui possui modelagem confortável estilo jogger com cós em elástico, bolso com etiqueta frontal e punho nos pés e cor lisa. O conjunto é perfeito para os meninos que gostam de um visual casual e despojado. Principais características: Conjunto flanelado e quentinho, com bolso canguru Modelagem padrão, super confortável Jaqueta com capuz e fechamento frontal em zíper Estampa moderna com escrita em bordado Punho retilíneo na calça e jaqueta Indicado para uso casual, passeios e atividades do dia a dia Características Gerais do Produto: • Composição Parte de Baixo: 100% algodão • Composição Parte de Cima: 100% algodão • Cor: Azul Escuro e Preto • Gênero: Masculino • Fechamento: Cós em elástico • Manga: Longa com punho • Modelagem: Normal • Outros: Com capuz - Conforto garantido! Modelagem padrão. Consulte a tabela de medidas.', 169.0, 169.0, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8262i-mm0nank3snbj24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688191470%2F45457442194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
