INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26788580792', 'NAVIFORCE 8076 Business Simples Multi-Dial Cronógrafo Relógio Masculino Multifuncional À Prova D''água', 'Descrição do produto Movimento de importação, 100% novo de alta qualidade, economia de energia e durável: Movimento de importação, 100% novo de alta qualidade, economia de energia e durável. À prova d''água: 30m 98FT resistente à água diária, adequado para uso diário, lavagem à mão, dias chuvosos, respingos ou mergulho curto, SEM problemas. Não suporta banho e natação, não opere o relógio subaquático, (Obs: Por favor, não opere o botão na água) Material do vidro mineral de alta dureza (chave resistente a arranhões), caixa de liga, cabo de aço inoxidável, caixa de aço inoxidável de volta, resistente à pressão Ideias de presente: relógios são para Natal, Aniversário, Dia das Mães, Dia de Graduação e Dia dos Namorados ou como presente para negócios e festas. Atendimento a qualquer dúvida sobre o produto, por favor nos contate, ofereceremos o melhor atendimento: Qualquer dúvida sobre o produto, entre em contato conosco, ofereceremos o melhor atendimento! ——————————————————————————————————————— Nome da marca da marca: NAVIFORCE Modelo do modelo: NF8076 Características: Impermeável Movimento do movimento do quartzo: movimento de quartzo Estilo: casual moderno, esportivo, negócios, luxo Profundidade à prova d''água 3Bar (não suporta chuveiro e natação, não opere o relógio debaixo d''água); Formato da casca do escudo: Redondo Características principais do traço: - 100% novo e de alta qualidade; Mostrador de design de luxo de alta qualidade Material de proteção -material de proteção: liga de zinco Tipo de material de janela giratória: Hardlex Material da alça da alça: Couro Material da tampa inferior: aço inoxidável Tipo de fivela: fivela Especificações Aproximadas): - Diâmetro do Mostrador: 46 mm - Largura do mostrador: 22 m - Espessura da Caixa: 15 mm - Comprimento do mostrador: 260 mm -Peso: 100 g Incluído no Pacote do pacote: Incluído no Pacote: Relógio NAVIFORCE (inglês)', 173.75, 152.9, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-mc1ti5r5rsk983', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F409535179%2F26788580792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398047570', 'Cooktop Supreme Dako a Gás Branco 4 Bocas Bivolt', 'O Cooktop Supreme a gás é ideal para quem ama cozinhar e impressionar, combinando design moderno e potência. Com uma mesa de vidro branco resistente e fácil de limpar, suas grades de ferro fundido oferecem estabilidade e segurança. O sistema “Girou, acendeu” permite acender a Mega e Tripla Chama rapidamente, otimizando o tempo de preparo. Os botões removíveis facilitam a limpeza, enquanto os queimadores selados evitam a entrada de resíduos. Para uma experiência de cozinha excepcional, escolha o Cooktop Supreme! Design moderno e renovado Vidro temperado, ultra resistente e fácil de limpar Versão com 4 e 5 queimadores com Tripla Chama - Mais velocidade no preparo das receitas Grades individuais de aço ferro fundido muito estáveis e robustas Queimadores selados que impedem a entrada de sujeiras Botões removíveis para não sobrar nenhuma sujeirinha Acendimento super automático, “Girou, acendeu“ - Muito prático de usar Ficha Técnica: Marca: Dako Cor: Branco Linha: Supreme Quantidade de Bocas: 4 bocas Tipo de Acendimento:Superautomático Garantia: 12 meses Acabamento da Mesa:Vidro Temperado Funcionamento: Gás Trempes:Individual de ferro fundido com 4 pontos de apoio Botões Removíveis: Sim Dimensões do Produto (largura x altura x profundidade): 58 x 12 x 46 cm Dimensões do Nicho (largura x altura x profundidade): 51 x 20 x 34,5 cm Fabricação: Nacional Potência dos Queimadores: 1Q Dupla Chama 3,25 KW, 3Q Seme-Rápido 1,65 KW Eficiência Energética: A Padrão de Tomada: 10A', 889.0, 699.0, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-7reqf-m2qrxj00dg5ibf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F864840659%2F223