INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11173455528', 'Mangueira reforçada para jardim 1/2" com 20 metros - Tramontina', 'Produto: Mangueira reforçada para jardim 1/2" com 20 metros Marca: Tramontina Cor: Verde Descrição: A Mangueira reforçada para jardim 1/2" com 20 metros da Tramontina é recomendada para uso doméstico ou profissional na jardinagem, agricultura ou construção civil, em situações com pressão da água de até 10 bar. Perfeita para as tarefas ao ar livre, ela torna a jardinagem mais prazerosa e confortável. O material em PVC da mangueira garante resistência e alta flexibilidade, possibilitando atingir os pontos mais difíceis na hora de irrigar. Possui 20 metros de comprimentos e acompanha um esguicho com jato regulável e um adaptador com engate rosqueado. Para aumentar a durabilidade da mangueira, não deixá-la exposta ao sol após o uso. A temperatura máxima de trabalho da água deve ser 50 °C. Características: • Mangueira flexível e de fácil manuseio. • Possui 20 metros de comprimento. • Recomendada para situações de uso com pressão da água de até 10 bar [145 psi] e temperatura de 50 °C. • Para maior resistência possui 3 camadas distintas: interna em PVC, intermediária em fio de poliéster trançado e externa em PVC. • O esguicho possui prático sistema de regulagem do fluxo d’água através do regulador frontal. • O esguicho é conectado em mangueiras através de sistema de fixação rosqueado. Especificações: Polegada: 1/2" 20 metros de comprimento Itens Inclusos: 1 esguicho com jato regulável 1 adaptador com engate rosqueado Dimensões (C x L x A): 15.00 x 27.00 x 27.00 centímetros Peso: 2.42 Kg', 127.25, 127.25, NULL, 'Home & Living > Gardening > Irrigation Systems', 'https://cf.shopee.com.br/file/sg-11134201-8258q-mr04fkc7qltxe8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F11173455528', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18109351630', 'Lâmpada led bulbo 9W 810 lúmens branca fria - A60 - Elgin (110V/220V)', 'Produto: Lâmpada led bulbo 9W 810 lúmens branca fria - A60 Marca: Elgin Voltagem: 110V/220V Descrição: A Lâmpada led bulbo 9W 810 lúmens branca fria A60 da Elgin possui como diferenciais alta economia e durabilidade até 4x maior do que as lâmpadas fluorescentes, 12x maior que as lâmpadas halógenas e 33x maior que as lâmpadas incandescentes. Economiza mais de 85% de energia A luz de cor branca com temperatura de 6500K, proporciona uma situação de atenção, de foco, melhor visibilidade, deixa o ambiente sempre mais em alerta. Com alta capacidade de iluminação, a lâmpada substitui as fluorescentes, proporcionando até 75% de economia. Especificações: Vida útil: 25.000H Base E27 Fluxo luminoso: 810 lúmens Bivolt Cor: 6500k Branca fria Potência: 9W Equivalência: 60W Incandescente 16W Fluorescente. Peso: 0.03 Kg', 26.32, 26.32, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-824j0-meg2yzxzlamf68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F18109351630', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
