INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899865963', 'Bancada Carrinho De Médico Infantil Doctor Center Maxi Toys', 'Carrinho de Médico Brinquedo Infantil Doctor Center com 37 Peças - Maxi Toys Transforme a brincadeira em aprendizado com o Carrinho de Médico Infantil Doctor Center da Maxi Toys! Ideal para crianças a partir de 3 anos, este brinquedo educativo estimula a imaginação, desenvolve empatia e ensina noções básicas sobre cuidados com a saúde. Equipado com 37 acessórios de médico realistas, este brinquedo é um verdadeiro centro de atividades que convida os pequenos a mergulhar em um mundo de descobertas. Entre os destaques, está o termômetro, que emite som dando um toque ainda mais real à brincadeira. Estetoscópio, tesouras, pinças, seringas, monitor, medidor de altura, película plástica de Raio-X, entre outros, não poderiam faltar nesta brincadeira. Tudo isso em um design funcional e fácil de montar, com abertura frontal e compartimentos organizadores para guardar todos os instrumentos com praticidade e 4 rodinhas para fácil movimentação. Indicado para crianças a partir de 3 anos. Certificado pelo INMETRO, o produto garante toda a segurança necessária para o uso infantil, permitindo que pais e responsáveis fiquem tranquilos enquanto os pequenos se divertem. Perfeito para presentear em qualquer ocasião especial. O Carrinho de Médico Doctor Center da Maxi Toys é garantia de sorrisos e muitas horas de diversão educativa. Principais Características: - Idade Recomendada: A partir dos 3 anos - 37 Acessórios de médico realistas - 4 Rodas para movimentação - Termômetro que emite som - Porta frontal - Design funcional - Combina diversão e aprendizado em uma única caixa - Ajuda a exercitar o cérebro das crianças - Cores vibrantes e atrativas - Estimula a habilidade prática das crianças - Pequenos suportes laterais para organização - Promove um brincar educativo. - Fácil de montar - Requer 2 pilhas AA (Não Inclusas) - Produto certificado pelo INMETRO Especificações Técnicas: - Conteúdo da Embalagem: 1 Carrinho de Médico + Acessórios + Manual de Instrução - Composição/Material: ABS e PP - Dimensões do produto aberto: A: 53 cm x L: 43 cm x P: 25 cm aprox. - Peso: 2,5 kg (bruto) - Garantia: 90 Dias (Contra Defeito de Fabricação Pelo Fabricante) - Certificação: 004346/2023 - Código do Fabricante: 21857 - EAN: 7899403218579 - Marca: Maxi Toys Imagens meramente ilustrativas. As cores e estampas podem variar de acordo com o lote do fabricante.', 279.9, 149.0, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-824hl-meeh1u24be2qa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340054154%2F20899865963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13433412468', 'Kit 2 Multiuso CIF Cremoso Limão com 250ml', 'O Kit contém: 2 Multiuso CIF Cremoso Limão com 250ml cada. • Cif Cremoso Limão é o produto de limpeza milagrosa que limpa fácil e dá brilho em mais de 100 superfícies, removendo 100% da sujeira difícil, sem esforço • O Cif Cremoso Limão possui um perfume suave, é mais concentrado e rende 3 garrafas do limpador comum • Fórmula com tecnologia poderosa que limpa sem riscar***, removendo toda a sujeira desde a mais pesada até a limpeza de casa do dia a dia, deixando um brilho imbatível • Com o Cif, a limpeza nunca foi tão fácil e versátil. Cif Cremoso possui três variantes: Original, Limão e Laranja • Cif Cremoso Limão é o produto de limpeza milagrosa para todo tipo de objeto como: eletrodomésticos, pias, couro sintético, borracha, plástico, porcelana e serve até como limpador de pisos • Cif promove uma limpeza milagrosa completa com produtos versáteis que atendem a todas as suas necessidades. Cif. Sinta a limpeza acontecer! ***Não usar esponja ácida, como palha de aço, para a limpeza de vidros. A imagem do produto é meramente ilustrativa e o rótulo pode variar. Será enviada a embalagem disponível no momento da compra.', 36.6, 36.6, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rd3m-m79h58uagjvw50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F546513063%2F13433412468', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
