INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198055388', 'Desodorante Antitranspirante Stick Dove Original 45g', 'Quer saber como ter uma pele macia sem comprometer a proteção? O Desodorante Antitranspirante Stick Dove Original oferece 48 horas de proteção eficaz e deixa a pele mais suave. Sua fórmula com ¼ de creme hidratante com óleo protetor, contribui para a hidratação diária da pele, deixando as axilas macias e suaves. Além disso, ajuda a reduzir a irritação causada pela depilação. Este desodorante antitranspirante é eficaz contra suor e mau odor, deixando a pele hidratada e fresca com as notas sutis da clássica fragrância de Dove para uma sensação de limpeza e bem-estar. Este desodorante feminino é sem álcool* e dermatologicamente testado. Nossa missão é elevar a autoestima das mulheres para alcançarem o seu máximo potencial. O Desodorante Antitranspirante Stick Dove Original oferece proteção eficaz e cuidado para a pele, respeitando a pluralidade de axilas, para você se libertar de qualquer inibição e se sentir confiante o dia todo. Aplique o desodorante antitranspirante Dove fazendo movimentos circulares de modo a cobrir toda a região da axila com uma camada fina e uniforme do produto. Dove é certificada Cruelty-Free pela PETA, sendo assim, não realizamos e nem realizaremos testes em animais em nenhum lugar do mundo. *Não contém álcool etílico.', 38.84, 35.65, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-824gr-meg624t1l69yed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F546513063%2F23198055388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
