INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997284512', 'Jogo de Chaves Trafix 9 Peças Tramontina PRO', 'O Jogo de Chaves Trafix 9 Peças (44450/209) - Tramontina Pro, possui seu corpo em forma de L com 2 braços de diferente comprimento, permite a aplicação de torque em parafusos posicionados em diferentes profundidades. Escolha o tamanho e perfil ideal para o seu trabalho e mãos à obra. Descrição do Produto: • Haste em aço ferramenta S2 temperada. • Acabamento fosfatizado. • As chaves tipo L ou Cabo T são submetidas a ensaios de torque e de dureza para analisar a resistência mecânica e atender aos valores da norma específica. • Grande variedade de formas, perfis de pontas e comprimentos para as diversas aplicações automotivas e industriais. • As chaves tipo L possuem dois braços de comprimentos diferentes, e ambas extremidades podem ser utilizadas dependendo do local onde será realizado o trabalho. Ao utilizar o braço mais longo tem-se mais torque, enquanto o braço mais curto promove uma operação mais rápida. • Apertar ou afrouxar parafusos com encaixe trafix. • As ferramentas são produzidas e testadas conforme normas específicas. Medidas Chaves Trafix: T10 - T15 - T20 - T25 - T27 - T30 - T40 - T45 - T50. Referência: 44450/209. Cód. de Fábrica: 44450/209. Marca: Tramontina Pro.', 133.9, 133.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkmhrhooqap4a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F21997284512', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
