INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9070278711', 'Livro - O primo Basílio - Capa comum - Principis', 'Eça de Queirós, neste livro, faz uma crítica severa à sociedade lisboeta do século XIX. O autor mostra a lenta deformação do caráter de Luísa, mulher de formação romântica entediada com o casamento, sob o efeito de leituras e músicas sentimentais. Durante uma viagem do marido Jorge, Luísa envolve-se com seu sedutor primo Basílio. Porém, Juliana, a invejosa e vingativa criada, descobre o caso e arma um esquema de chantagem. Muitas emoções e reviravoltas num clássico do realismo português. Editora: Principis Edição: 1, 2020 Autor: Eça de Queirós Idioma: Português Páginas: 384 Dimensões: L 15.70 x A 22.80 x E 2.00 ISBN: 9786555520927', 34.9, 34.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/6f6316ec167c2078f4539f194d2aa6d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9070278711', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
