INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208104476', 'Gaabor Balança Digital até 180kg LED HD Vidro Temperado USB para Casa e Banheiro Verde GWS-M03A', 'Características Display LED – Visor LED grande, HD e com números bem nítidos Vidro temperado de alta resistência – Firme e resistente a oscilações Carregamento via USB – Com uma carga completa, dura até meio ano Sensor inteligente por indução – Ativação automática por indução de peso, sem interruptor manual Grande e estável – Superfície ampla oferece espaço suficiente para apoiar os pés com conforto Medição inteligente da temperatura ambiente – Detecta variações de temperatura e dá dicas de saúde Da superfície ao material e ao visor: uma experiência otimizada em todos os aspectos Superfície larga (26 x 26 cm): Proporciona um espaço amplo para os pés, permitindo apoiá-los de forma natural. Maior estabilidade ao ficar de pé e sensação de segurança — ideal para diferentes tamanhos de corpo e tipos de uso. Painel de vidro temperado: Design moderno e minimalista, com alta resistência mecânica e contra impactos. Estrutura firme e durável, excelente capacidade de suporte e muito fácil de limpar. Tela LED de tamanho grande: Números grandes e de fácil leitura, sem necessidade de forçar a visão. A tela foi otimizada para não refletir a luz forte e não incomodar em ambientes escuros. Seja pela manhã com os olhos ainda sonolentos, ou à noite com pouca luz, você sempre terá a leitura mais nítida.', 199.0, 79.0, NULL, 'Health > Medical Supplies > Scale & Body Fat Analyzers', 'https://cf.shopee.com.br/file/br-11134207-820m9-mmk4tk6b82yu68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1574084758%2F58208104476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
