INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593426747', 'Livro Falsos Profetas | Fábio Coelho | Jesus Copy', 'Falsos Profetas | Fábio Coelho Cuidado com os falsos profetas. Eles vêm a vocês vestidos de peles de ovelhas, mas por dentro são lobos devoradores. (Mateus 7.15)Na batalha espiritual que se desenrola entre as trevas e a humanidade desde o início da criação (Gn 3:15), o principal alvo do Diabo é o povo da aliança. Nessa guerra, umas das armas mais terríveis do inimigo contra os santos são os falsos profetas. Páginas: 261 Altura: 21 cm Largura: 13,5 cm Profundidade: 1,5 cm', 47.22, 47.22, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdx5-m1ctj13nayvs46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22593426747', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
