INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47754762917', 'Garrafa Térmica Lyor Mini Bambude Plástico Bege 400ml', 'Garrafa Térmica Lyor Mini Bambude Plástico Bege 400ml A Garrafa Térmica de Plástico Mini Bambu da Lyor é sua companheira ideal para manter suas bebidas na temperatura perfeita, aonde quer que vá. Compacta e ConvenienteCom capacidade para 400ml, esta garrafa térmica é compacta e fácil de transportar, ideal para levar para o trabalho, academia, passeios ou viagens. Excelente Isolamento TérmicoFabricada com materiais de alta qualidade, mantém suas bebidas quentes ou frias por várias horas, garantindo que você possa desfrutar delas frescas ou quentes a qualquer momento. Durável e PráticaSeu design em plástico resistente garante durabilidade e facilidade de limpeza, enquanto a tampa rosqueável proporciona vedação segura, evitando vazamentos. Estilo EleganteCom um elegante acabamento em bege e detalhes em bambu, esta garrafa térmica combina estilo e funcionalidade, adicionando um toque de sofisticação ao seu dia. Prática, durável e com um design encantador, a Garrafa Térmica de Plástico Mini Bambu Bege 400ml da Lyor é a escolha perfeita para manter suas bebidas na temperatura ideal em qualquer ocasião. Lyor - Sua Casa Completa. Contém: 1 Garrafa Térmica Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 21,00cm x Largura 10,50cm x Comprimento 13,50cm Peso: 0,48Kg Cor: Prata Material: Plástico Lavar com detergente neutro, esponja macia e secar imediatamente.', 62.0, 46.99, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-8262d-mk142q6m09vp8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F47754762917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
