INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398141469', 'Máquina Para Assentar Piso A Bateria 12v MAP125 Vonder', 'Máquina Para Assentar Piso A Bateria 12v MAP125 Vonder Ferramenta prática e eficiente para assentamento de pisos e porcelanatos, equipada com ventosa de alto poder de sucção e sistema de vibração ajustável em 5 níveis. Conta com display para seleção da intensidade, punho auxiliar ergonômico e alimentação por bateria de íons de lítio, oferecendo mobilidade e precisão durante o uso. Ideal para pisos com superfície lisa de até 100 cm x 100 cm. Itens Inclusos 1 Máquina para assentar piso com ventosa 1 Maleta plástica 1 Bateria 12 V - 2,2 Ah 1 Fonte carregadora bivolt automático Especificações Técnicas Modelo: MAP 125 Potência do motor: 180 W Tipo de bateria: Íons de Lítio 12 V - 2,2 Ah Tempo de carregamento: 2 horas Tensão de saída da fonte: 12 V DC Tensão de entrada da fonte: 100 V~ - 240 V~ (bivolt automático) Diâmetro da ventosa: 145 mm Capacidade de carga: 50 kgf Dimensões: 390 mm x 145 mm x 135 mm Vibrações por minuto (vpm): >Nível 1: 1.500/min >Nível 2: 3.200/min >Nível 3: 4.200/min >Nível 4: 4.800/min >Nível 5: 6.000/min Nível de ruído: >Sem carga: 60 dB(A) >Com carga: 80 dB(A) Aceleração nas mãos - braços do operador: >Nível 1: 32 m/s² >Nível 2: 53 m/s² >Nível 3: 75 m/s² >Nível 4: 110 m/s² >Nível 5: 190 m/s² Incerteza (k): 1,5 m/s² Por que escolher este produto? Produto novo e original Pronta entrega e envio em até 24 horas Compra 100% segura', 699.99, 699.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-milme3hb0q9u2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F19398141469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198679940', 'Kit Terere Inox Copo Cuia Quadrado Bomba Tereré Inox Filete + Escova de Limpeza Cores', 'A Bomba de Tereré Filete foi desenvolvida com foco em qualidade, durabilidade e higiene. Com 19 cm de comprimento, seu diferencial está na base com cortes em filete, que proporcionam um excelente fluxo de água e evitam entupimentos, mesmo com ervas mais finas. Fabricada com chapa grossa de aço inox 100% puro, a bomba é resistente à corrosão, não enferruja e não precisa ser desmontada para limpeza. Acompanha: 1- Copo Inox Quadrado (ESCOLHA COR) 1- Bomba Inox Filete (ESCOLHA COR) 1- Escovinha de Higienização Dimensões: Bomba: 2cm (C) x 1cm (L) x 18cm (A) Copo: 11cm (A) x 5cm (L) Capacidade: 250ml Material: Aço inox, material de alta resistência; não enferruja; não transfere odor e nem gosto. Garantia: 90 dias do Fabricante.', 54.9, 54.9, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbh3k1nqw4u02d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1362877346%2F23198679940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
