INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22916911823', 'Kit com 3 Calcinhas Alta Loba 40351-001', 'Características: Calcinha Alta Clássica. Confeccionada em cotton macio e confortável. Produzida com algodão nobre. Que aliado ao elastano proporciona ajuste perfeito e excelente toque. Fio compactado que reduz a formação de pilling (bolinhas no tecido). Maior brilho e vivacidade nas cores. Calcinha cintura alta com laterais largas e ampla cobertura. Ideal para todos os tipos de quadril. Elástico plano na cintura e nas cavas das pernas, proporciona muito mais conforto. Forro em algodão. Cores: Branco: Todas brancas. Preto: Todas pretas. Bege: Todas naturais. Cinza: 1 cinza, 1 preta e 1 natural. Composição: 92% Algodão e 08% Elastano.', 139.4, 139.4, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/sg-11134201-23010-gh8tq585yzlvdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F22916911823', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
