INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798864297', 'Snoopy | Cozy Time | Livro de Colorir', 'Inspirado no fenômeno do TikTok, o Comfy Cozy do Snoopy é ideal para quem ama transformar momentos simples em experiências relaxantes e acolhedoras. Com 48 páginas e 24 ilustrações encantadoras dos personagens da Turma do Snoopy, impressas em papel de alta gramatura para garantir a melhor qualidade na pintura, este livro permite que você solte a criatividade e mergulhe em um universo de tranquilidade e diversão. 24x24 cm 48 Páginas', 17.9, 12.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824i9-me2swdu7kgld8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22798864297', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099154206', 'Sonho de Uma Noite de Verão | Em Quadrinhos', 'O Duque Teseu, precisa resolver uma uma questão: Hérmia ama Lisandro, mas Egeu, seu pai, não aprova o rapaz e exige que ela se case com Demétrio.Lisandro e Hérmia fogem de Atenas, seguidos por Helena,que ama Demétrio. Os quatro se perdem em uma floresta, onde o brincalhão elfo Puck, faz com que os jovens se apaixonem pelos pares trocados. Tudo isso e mais ainda acontece durante um sonho de uma noite de verão.80 páginas15,5x22,6 cm', 17.9, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821fz-mglp6oy7p2ix44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23099154206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
