INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297006193', '365 | Palavras Cruzadas | Com Histórias Bíblicas', 'Fazer palavras cruzadas com histórias bíblicas é uma forma criativa e divertida de desenvolver o raciocínio e deixar o pensamento ágil com lindas histórias sobre fé, bondade e amor. São 365 histórias, uma para cada dia do ano, com personagens inesquecíveis, para você se encantar e se emocionar, além de enriquecer o vocabulário.Editora: Ciranda CulturalEdição: 1, 2019Autor: Ciranda CulturalIdioma: PortuguêsPáginas: 288Dimensões: L 15.50 x A 23.00 x E 1.30ISBN: 9788538089742Coleção: 365 atividadesLinha Editorial: Ciranda Cultural - BíblicoFaixa Etária: + 6 anosAssuntos (tags): Histórias bíblicas, Palavras-cruzadas, AprendizadoBISAC: Religião / Obras de Referência BíblicasLinha de Produto: 365 atividadesEncadernação: BrochuraAcabamento: Laminação brilhoMaterial: Papel', 19.9, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbl8-lmko9on8iyjd71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22297006193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20905268387', 'Livres da Tirania da Urgência | Charles E. Hummel', 'Você já desejou um dia com trinta horas? Você sabe fazer diferença entre o que é urgente e o que é importante? Mais: qual dos dois fazer primeiro? Se você tem muita coisa para fazer, mas não tem tempo, este livro é para você. Claro, algumas horas a mais aliviariam a pressão sob a qual vivemos. Afinal, nossas vidas deixam um rastro de tarefas incompletas. E-mails não respondidos, livros não lidos, amigos não atendidos assombram nossos poucos momentos de descanso e de avaliação do que temos feito. A pergunta que podemos fazer é: um ou dois dias a mais poderiam mesmo resolver nosso problema? Em Livres da Tirania da Urgência, uma abordagem ampliada e atual do clássico livreto a Tirania do Urgente - com mais de um milhão de exemplares vendidos -, Charles Hummel mostra o ensinamento bíblico sobre a administração do tempo e oferece ao leitor ilustrações e dicas práticas sobre como fazer diferença entre tentar administrar o "tempo" e administrar a "vida". 14X21CM 144 Páginas', 39.9, 39.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/7300bc133e9c4b76b37d1fcea6011172', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20905268387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10765233456', 'MEIA FUTEBOL SELENE 4171-001', 'Características: Meia esportiva futebol. Proporciona conforto e durabilidade. Liberdade de movimentos. Cano: Longo. Modo de Lavagem: Lavar com temperatura máxima de 40°C. Não alvejar. Não secarem em secadora rotativa. Não passar. Não limpar a seco. Composição: 98% Poliamida, 01% Poliester e 01% Elastano.', 42.9, 42.9, NULL, 'Women Clothes > Socks & Stockings > Socks', 'https://cf.shopee.com.br/file/sg-11134201-22110-ft8z3b4ccnjvc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F10765233456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
