INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297777863', 'Par Pneu 100/80-17 + 140/70-17 Pirelli Sport Demon Original', 'Pneu Dianteiro.: 100/80-17 52S Modelo: Sport Demon Marca: Pirelli Índice de Carga: 52 (200kg) Índice de Velocidade: S (180km/h) Uso: Sem Câmara -------------------------------------------------------- Pneu Traseiro.: 140/70-17 66H Modelo: Sport Demon Marca: Pirelli Índice de Carga: 66 (300kg) Índice de Velocidade: H (210km/h) Uso: Sem Câmara -------------------------------------------------------- Antes de finalizar a compra, confira as medidas que sua moto está utilizando atualmente! Aguardamos a sua compra! -------------------------------------------------------- * NÃO ACOMPANHA RODA -------------------------------------------------------- Garantia de 5 anos somente por defeitos de fabricação, ficando inválida em caso de danos por acidentes, buracos na pista, mau uso e ainda má instalação. É necessário e indispensável instalar o pneu com um profissional especializado.', 1625.82, 1207.47, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mge2i2v9181s28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1311725041%2F23297777863', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13263498167', 'Vontade Divina E Escolha Humana | Richard A. Muller', 'Este recente estudo do respeitado professor Richard Muller lança nova luz sobre a discussão acerca de como os reformadores e seus sucessores analisaram e conciliaram os conceitos da soberania divina e da liberdade humana. Muller — um dos maiores especialistas na teologia desenvolvida nos períodos da Reforma e pós-Reforma — argumenta que a ortodoxia reformada tradicional (a qual, segundo o autor, foi influenciada pela filosofia e teologia ocidental) defendeu uma teoria robusta que levava em conta uma vontade divina onipotente, bem como a livre escolha humana. Vontade divina e escolha humana fornece uma perspectiva histórica e sistematizada sobre um dos tópicos mais intricados da teologia protestante e certamente enriquecerá o debate a esse respeito.', 73.9, 73.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/4aff9d3dbb745f84a588f58618213756', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F13263498167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
