INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22996709646', 'Extensor para Bit Magnético e Impacto 1/4 X 76Mm 48-32-4508 - Milwaukee', 'SHOCKWAVE 3 pol. Guia de acionamento magnético As guias de acionamento magnético Milwaukee SHOCKWAVE Impact Duty são projetadas para extrema durabilidade e vida útil de até 30x. Elas apresentam um shockzone otimizado que absorve o pico de torque e evita que elas se quebrem. A luva de aço inoxidável desliza sobre o fixador para maior estabilidade, enquanto o cano possui medidor de profundidade gravado a laser para maior controle do fixador. O guia de acionamento é magnético para segurar o fixador, enquanto um c-ring retém o bit de acionamento. CARACTERÍSTICAS O SHOCKWAVE otimizado absorve o pico de torque e evita a quebra A manga de aço inoxidável se estende para maior estabilidade do fixador Medidor de profundidade gravado a laser para maior controle do fixador O ímã prende os fixadores ao guia de acionamento C-ring retém a broca de inserção O aço Alloy76 personalizado maximiza a resistência ao desgaste e ao choque Para uso com bits de driver de estilo de inserção de 1 pol. Não achou o que procurava ou ficou com dúvidas em relação ao produto? Entre em contato conosco.', 143.09, 143.09, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lktptngkokut04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F998294051%2F22996709646', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201106743', 'Engate Reboque Fixo Fiorino Furgão 1994 a 2012 700 Kg - Brucke FT4013', 'Engate Reboque Fiat Fiorino 1994 a 2012 Fixo 700 Kg Marca: Brucke Modelo: FT4013 - Compatibilidade: Fiat Fiorino 1994 Fiat Fiorino 1995 Fiat Fiorino 1996 Fiat Fiorino 1997 Fiat Fiorino 1998 Fiat Fiorino 1999 Fiat Fiorino 2000 Fiat Fiorino 2001 Fiat Fiorino 2002 Fiat Fiorino 2003 Fiat Fiorino 2004 Fiat Fiorino 2005 Fiat Fiorino 2006 Fiat Fiorino 2007 Fiat Fiorino 2008 Fiat Fiorino 2009 Fiat Fiorino 2010 Fiat Fiorino 2011 Fiat Fiorino 2012 O Engate Reboque para o Fiat Fiorino de 1994 a 2012 Fixo da marca Brucke é a solução ideal para quem busca robustez e confiabilidade. Com uma capacidade de reboque de até 700 Kg, este modelo com ponteira Fixo tem resistência testada e garantida, garantindo que você possa transportar cargas pesadas com segurança! É compatível com carretinhas, trailers, transbikes. - Atributos do Produto: Tipo de ponteira: Fixo Medidas: 23 x 47 x 113 cm, 10kg. Capacidade de reboque tração: Até 700 Kg Capacidade de peso sobre a bola: Até 40 kg Material: Fabricado em Aço carbono Pintura: Acabamento em pintura eletrostática a pó na cor preta Homologação: Produto homologado pelo INMETRO (012587/2022) e regularizado conforme a resolução nº 197 do Contran. Acompanha bola de engate, tomada e acabamento (quando necessário) como nas imagens. Código interno: 696 Instalação: Instalação simples nas furações originais do veículo, sem necessidade de furos ou adaptações. A instalação deve ser feita por um profissional.', 580.83, 522.75, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-8227j-mhjmxxxmknwhb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1625011375%2F58