INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993149070', 'EM ROTA DE COLISAO - ALT', 'Uma estudante exemplar, um atleta de hóquei e uma conexão quente o suficiente para derreter uma pista de geloUm romance esportivo hot ideal para os fãs de Quebrando o geloSummer Preston está dividida entre realizar o sonho de sua vida e se tornar uma psicóloga esportiva ou ficar o mais longe possível de um campo de hóquei, afinal, ela tem um bom motivo para odiar o esporte.Aiden Crawford é o capitão da equipe de hóquei da faculdade e está enfrentando um desafio: os erros de sua equipe ameaçam colocar em risco toda a temporada de jogos. Como punição, seu treinador o nomeia como objeto de estudo de um projeto de pesquisa estudantil e Aiden não tem escolha a não ser aceitar.Só que o projeto de pesquisa em questão é liderado por Summer, que foi praticamente obrigada pela sua orientadora a trabalhar com Aiden. Assim, um encontro explosivo acontece e os dois se vêem em uma inesperada rota de colisão ao encarar suas diferenças gritantes.Summer não suporta a abordagem blasé de Aiden em relação à vida, e Aiden não entende o jeito arisco e metódico de Summer. Mas as brigas logo se transformam em algo a mais ― e quando eles baixam a guarda, não há gelo que segure o calor dos seus sentimentos.Com cenas hot de tirar o fôlego, Em rota de colisão é um romance new adult esportivo da autora canadense Bal Khabra. É o primeiro volume de uma trilogia de mesmo nome com histórias independentes.', 58.4, 58.4, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rfgc-m9yljhjvlstobd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F22993149070', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
