INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693105005', 'Água Micelar Cicatricure - 200ml - 5 em 1', 'O peso líquido do conteúdo é de 200ml. O Cicatricure Água Micelar efetua a limpeza facial 5 em 1 sem irritar a pele, e com efeito demaquilante. Feito para rosto, olhos, lábios e pescoço, o Cicatricure Água Micelar remove restos de maquiagem e impurezas da pele, além de hidratar, tonificar e refrescar. Nossa tecnologia demaquila até a maquiagem à prova d''água, com uma composição livre de álcool ou etanol e feita com extrato de rosas. A Água Micelar Cicatricure é perfeita para a limpeza da maquiagem pós-evento, ajudando a manter a saúde e o vigor do seu rosto. Modo de Uso: Aplique a Água Micelar após o uso da maquiagem; a Água Micelar Cicatricure limpa desde a primeira passada.', 34.68, 27.9, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-7rd41-lwq74tswtowkce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1284050214%2F22693105005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
