INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798092978', 'Estojo Escolar Simples Teen Cairo Verde ACP Compacto, Resistente e Ideal para o Dia a Dia', 'Estojo Escolar Teen Pastel Cor Verde Pastel O Estojo Escolar Simples Teen Cairo da ACP é a escolha ideal para organizar seu material com estilo e praticidade. Com um único compartimento espaçoso, ele é perfeito para guardar lápis, canetas, borrachas e outros itens essenciais, mantendo tudo à mão. O material em PVC resistente e o fechamento em zíper garantem a durabilidade e a segurança dos seus pertences, seja na escola, faculdade ou no dia a dia. Especificações técnicas: Marca: ACP; Referencia: 21964.VD; Código: 482653; Características do produto: Estojo Escolar Simples Teen Cairo Verde ACP - 1 Unidade; Medidas: 5 X 5 X 20 cm; Embalagem: 1 Unidade Com mais de 70 anos de tradição no mercado, a Jandaia é referência nacional na produção de materiais escolares e de escritório. Reconhecida pela qualidade, criatividade e compromisso com a educação, a marca se destaca por oferecer produtos que aliam funcionalidade, design moderno e durabilidade. Presente no dia a dia de milhões de brasileiros, a Jandaia investe constantemente em inovação para atender às necessidades de crianças, jovens e adultos, criando itens que estimulam a organização, a escrita e o aprendizado. Do universo escolar ao ambiente profissional, a Jandaia está presente em cada detalhe com excelência e confiança. Escolher produtos Jandaia é optar por uma marca com história, responsabilidade e dedicação à criação de soluções práticas e inspiradoras para todas as fases da vida.', 41.99, 41.99, NULL, 'Stationery > School & Office Equipment > Pencil Cases', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-mdh5btrz780a5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306190243%2F21798092978', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
