INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697928852', 'Cadeira Sala de Jantar Eames Wood - Cores', '🪑 Cadeira Eames Wood – Design Icônico e Conforto Atemporal Leve para o seu ambiente um dos maiores ícones do design moderno. A Cadeira Eames Wood combina sofisticação, conforto e durabilidade em um só produto. Criada nos anos 1950 por Charles e Ray Eames, ela segue encantando com seu estilo atemporal, adaptando-se a qualquer decoração — do minimalismo ao vintage. Com assento anatômico em polipropileno e base Wood (pés de madeira natural com estrutura metálica reforçada), é ideal para compor salas de jantar, escritórios, recepções ou qualquer ambiente que mereça um toque de elegância. ✅ Design Atemporal • Conforto Ergonômico • Base em Madeira Natural 🌍 Produção Responsável – Qualidade e Estilo que Duram ✨ Diferenciais do Produto ✅ Design Moderno e Versátil: Linhas orgânicas e elegantes que harmonizam com qualquer decoração. ✅ Assento em Polipropileno (PP): Resistente, fácil de limpar e com acabamento fosco. ✅ Base Modelo Wood: Pés em madeira maciça natural com estrutura metálica cruzada, garantindo firmeza e estabilidade. ✅ Ergonomia com Estilo: Encosto curvado e assento anatômico para máximo conforto, mesmo em longos períodos. ✅ Durabilidade: Materiais de alta qualidade que garantem longa vida útil. ✅ Sustentabilidade: Produção com responsabilidade ambiental. 📏 Dimensões Aproximadas Altura total: 82 cm Largura: 46 cm Profundidade: 49 cm Peso suportado: até 110 kg Peso por cadeira: 4,2 kg 📦 Conteúdo da Embalagem 1 Assento Eames (cor e acabamento escolhido) 1 conjunto de pés Wood 1 Kit de parafusos e manual ilustrado para montagem 🛠️ Montagem Rápida e Fácil Montagem simples com kit incluso. Não exige conhecimentos técnicos. 🛡️ Garantia 3 meses contra defeitos de fabricação 📦 Envio Imediato e Seguro Estoque próprio Embalagem reforçada Entrega rápida para todo o Brasil 🔥 Garanta agora sua Cadeira Eames Wood! Um clássico do design mundial, fabricado com qualidade e pronta para valorizar ainda mais o seu espaço.', 399.99, 248.65, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m131tzi5xleb58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F791969908%2F18697928852', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
