INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20473723196', 'Minhas Experiências com Deus | Wanda Freire', 'Uma história de fé, coragem e poder de Deus!“naquele dia, o irmão, chegou lá e Deus começou a usar ele e disse assim: Minha serva, você diz que não casou com pastor. Tu casaste com pastor. Tu não sabias que ele era pastor, mas ele está escolhido desde o ventre de tua mãe. E a ti também te escolhi para estar do lado dele.” Surpreenda-se com a história de Wanda Freire da Costa, esposa de José Wellington Bezerra da Costa, presidente da Convenção Geral das Assembleias de Deus no Brasil.Em uma linguagem simples e cativante, a autora narra sua história de vida, permeada por lutas e adversidades, mas também por muita fé, coragem e poder de Deus.Descubra por trás da pessoa pública a mulher, esposa, mãe, avó e, acima de tudo, serva de Deus, Wanda Freire da Costa. 14x21cm 196 Páginas', 26.9, 26.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-23020-sch6ftub3onvcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20473723196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46459515219', 'Bíblia Infantil Ilustrada | Mensageiros', 'A Bíblia Infantil Mensageiros é o presente perfeito para crianças que estão começando sua jornada de fé. Com uma linguagem simples e acessível, esta bíblia oferece as histórias mais impactantes da Bíblia em um formato que cativa e inspira corações jovens. Cada página é cheia de ilustrações vibrantes, permitindo que as crianças mergulhem nas lições de amor, coragem e fé ensinadas nas Escrituras. Feita especialmente para encantar e ensinar, a Bíblia Infantil Mensageiros é muito mais do que um livro ? é uma ferramenta poderosa para plantar sementes da Palavra de Deus nos corações dos pequenos. Ideal para leituras em família, momentos devocionais ou como presente inesquecível, esta Bíblia ajuda a formar uma base espiritual sólida enquanto estimula a imaginação e a curiosidade. Destaques da Bíblia: Histórias envolventes que transmitem os valores do Evangelho de forma clara e divertida Ilustrações coloridas e cheias de vida que tornam as narrativas bíblicas ainda mais emocionantes Fácil de entender, com uma linguagem adaptada para crianças, permitindo que elas aprendam e compartilhem a Palavra de Deus Perfeita para incentivar a leitura bíblica diária, desenvolvendo o hábito de estudo e oração desde cedo Um presente precioso para aniversários, datas especiais ou como introdução ao mundo da fé cristã 21x14 cm 128 Páginas', 19.9, 10.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-820mx-mnhpbcc0f6rm16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F46459515219', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
