INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17128876362', 'Espátula Reta Inox bicolor Gesso Drywall Cabo Emborrachado Lotus Profissional Vários Tamanhos', 'COMERCIAL VIPASA DISTRIBUIDORA. ESPÁTULA CROMADA RETANGULAR PARA ACABAMENTO em INOX. Espátula retangular de aço inox , cabo de plástico rígido bicolor ergonômico e macio, para conforto e durabilidade, lamina em aço inox temperado com placa suporte de alumínio, lamina especialmente afilada para uso em cantos, para aplicações em gesso e placas de drywall. Super-resistente Tamanhos: 8, 10 e 12 ESPÁTULA RETANGULAR CROMADA LOTUS 8, 10 E 12 POLEGADAS – MODELOS 8720, 8721, 8722 As Espátulas Retangulares Cromadas Lotus são ferramentas versáteis e robustas, ideais para trabalhos de acabamento, nivelamento e aplicação de massas, gesso, rejuntes, argamassas e demais materiais de construção ou reforma. Com lâminas largas em aço cromado e cabos ergonômicos, oferecem resistência, durabilidade e excelente desempenho mesmo em uso contínuo. Disponíveis em três tamanhos distintos (8, 10 e 12 polegadas), as espátulas atendem diferentes necessidades e tipos de aplicação, desde áreas menores e detalhadas até superfícies amplas. A estrutura reforçada e a lâmina reta garantem precisão e agilidade no trabalho, sendo muito utilizadas por profissionais da construção civil, pintores, gesseiros, instaladores e também por usuários domésticos. OPÇÕES DE VARIAÇÃO DISPONÍVEIS 🔹 Espátula Retangular Cromada 8 Polegadas – Lotus 8720 Ideal para acabamentos e aplicações em áreas pequenas e de difícil acesso Largura da lâmina: 8" (aproximadamente 20 cm) 🔹 Espátula Retangular Cromada 10 Polegadas – Lotus 8721 Indicada para aplicações médias, com maior cobertura e rendimento Largura da lâmina: 10" (aproximadamente 25 cm) 🔹 Espátula Retangular Cromada 12 Polegadas – Lotus 8722 Perfeita para nivelamento de grandes áreas com rapidez e precisão Largura da lâmina: 12" (aproximadamente 30 cm) CARACTERÍSTICAS GERAIS DAS ESPÁTULAS Marca: Lotus Modelos: 8720 (8"), 8721 (10"), 8722 (12") Tipo: Espátula retangular cromada Material da lâmina: Aço cromado de alta resistência Acabamento: Polido, facilita a limpeza Cabo ergonômico de plástico rígido Alta durabilidade mesmo em uso profissional Fácil manuseio e excelente controle na aplicação DIMENSÕES E PESO APROXIMADOS POR MODELO 8” (8720): largura 20 cm, altura 8 cm, peso 150 g 10” (8721): largura 25 cm, altura 8 cm, peso 180 g 12” (8722): largura 30 cm, altura 8 cm, peso 210 g APLICAÇÕES INDICADAS Aplicação de massa corrida, gesso, cimento ou argamassa Nivelamento e acabamento em paredes e pisos Trabalhos de pintura e drywall Uso profissional e doméstico espatula retangular cromada lotus 8 10 12 polegadas 8720 8721 8722 espatula de aço cromado para massa gesso cimento obra construção civil acabamento drywall ferramenta profissional nivelamento cabo ergonomico espatula larga lotus Espátula Retangular Cromada Lotus 8 10 12 Polegadas – Variação Espátula Cromada Lotus 8720 8721 8722 Aço Retangular Profissional Espátula Retangular De Aço Cromado Lotus 8 a 12 Pol Acabamento Massa COMERCIAL VIPASA DISTRIBUIDORA.', 37.99, 32.99, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-22110-yhxgd1a246jv63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F17128876362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
