INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54260314486', 'Espelho Lopazzi 150cm Corpo Inteiro Closet Feminino Quarto Look Vidro Temperado', 'Transforme seu ambiente com o Espelho Lopazzi 150cm Corpo Inteiro, uma peça moderna, elegante e funcional, ideal para quem busca praticidade, beleza e um reflexo nítido no dia a dia. Com design alto e estreito, acabamento lapidado e vidro temperado, ele é perfeito para salão de beleza, área de cabelo, closet, quarto, hall de entrada, corredor, provador, boutique e ambientes profissionais. Seu tamanho permite visualizar o corpo inteiro, sendo uma excelente opção para salões que desejam oferecer mais conforto ao cliente na hora da finalização, corte, escova, maquiagem ou conferência do visual. O acabamento lapidado proporciona um visual mais limpo, moderno e sofisticado, combinando facilmente com diferentes estilos de decoração. Principais benefícios Espelho corpo inteiro 150cm Ideal para salão de beleza e cabelo Vidro temperado Acabamento lapidado Reflexo nítido e sem distorções Design moderno e elegante Ótimo para ambientes residenciais e profissionais Acompanha suporte para instalação Visual clean, sem moldura decorativa Combina com salão, closet, quarto, hall e provador Medidas e especificações Marca: Lopazzi Modelo: Espelho corpo inteiro Altura: 150 cm Largura: 40 cm Formato: Corpo inteiro, alto e estreito Vidro: Temperado Acabamento: Lapidado Iluminação: Não possui LED Moldura: Sem moldura decorativa Instalação: Parede Uso indicado: Vertical Ambientes indicados: Salão de beleza, salão de cabelo, closet, quarto, hall, corredor, provador, boutique e barbearia Reflexo: Nítido e sem distorções Estilo: Moderno, clean e sofisticado O que acompanha o produto 1 Espelho Lopazzi 150cm corpo inteiro Suporte para instalação na parede', 289.9, 239.9, NULL, 'Home & Living > Decoration > Mirrors', 'https://cf.shopee.com.br/file/sg-11134201-820nc-mo48du9btrm027', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248180593%2F54260314486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41471879680', 'Amend Kit Millernar Óleos Marroquinos Sh. e Cond. 300ml + Máscara 300g + Proteína Capilar 100g', 'Amend Kit Millernar Óleos Marroquinos Shampoo e Condicionador 300ml + Máscara 300g + Proteína Capilar 100g Transforme sua rotina capilar com o poder dos óleos marroquinos e ativos milenares da Amend. Este kit reúne os melhores tratamentos para proporcionar hidratação profunda, nutrição, brilho e resistência aos fios. Indicado para cabelos ressecados, frágeis, danificados ou com química, garante resultado de salão no conforto da sua casa. O que acompanha o kit: Shampoo Millenar Óleos Marroquinos 300ml - Limpa suavemente sem agredir os fios - Restaura maciez, elasticidade e hidratação - Enriquecido com óleos de Argan e Amêndoas e extrato de Tamarindo Condicionador Millenar Óleos Marroquinos 300ml - Proporciona condicionamento intenso e desembaraço fácil - Hidrata e suaviza os fios, deixando-os macios e brilhantes - Combinação de Argan, Amêndoas e Tamarindo para nutrição e proteção Máscara Hair Butter Millenar Óleos Marroquinos 300g - Tratamento profundo com alto poder de nutrição - Recupera fios ásperos e ressecados, devolvendo elasticidade e toque sedoso - Contém manteiga de Karité, óleos de Argan e Amêndoas e Tamarindo Amend Essencial Proteína Capilar 100g - Reconstrói e fortalece a fibra capilar - Repõe proteínas e aminoácidos essenciais - Ideal para cabelos fragilizados, quimicamente tratados ou danificados - Promove elasticidade, resistência e brilho saudável Benefícios do Kit Completo: - Limpeza delicada e tratamento intensivo em todas as etapas - Hidratação, nutrição e reconstrução em um só kit - Proteção contra calor e raios solares - Redução de frizz, fios alinhados e mais resistentes - Indicado para todos os tipos de cabelo, especialmente os ressecados, danificados e enfraquecidos Como Usar - Lave os cabelos com o Shampoo, massageando suavemente. - Aplique a Máscara do comprimento às pontas, deixe agir e enxágue. - Utilize o Condicionador para selar as cutículas. - Use a Proteína Capilar semanalmente ou conforme a necessidade para reposição intensa de nutrientes. Resultado: Cabelos nutridos, fortes, macios, com brilho radiante e movimento natural, livres do frizz e protegidos contra agressões externas.', 302.5, 190.98, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-820m0-mq4ska0q9vya43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1077804858%2F41471879680', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52604305102', 'BASE MESA RENO 88CM CROMADO PARA MESA 90CM KAPPESBERG', 'ESPECIFICAÇÕES DA MESA RENO: Altura: 76 cm Largura: 88 cm Profundidade: 88 cm Peso: 7 kg Acabamento: Produto acabado com 100% de Polimento Cor da Estrutura: Cromada em processo 100% Automatizado, proporcionando alto padrão de qualidade Mesa Tubular Material: Tubo 30x40 com Parede de Espessura 0,90mm / Tubo 40x40 com Parede de Espessura 0,90mm Pés de Metal Sistema de Montagem: Sistema Philips e Allen Cor: Cromado ****** NÃO ACOMPANHA TAMPO ****** ****** APENAS BASE DE MESA *******', 599.88, 469.9, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-82628-mj79a1ojtp8kbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F52604305102', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14804314104', 'Antipulgas e Carrapatos Simparic Cães de 10,1 a 20kg com 1 Comprimido', '– Indicado para cães de 10,1 a 20kg; – Controle de pulgas e carrapatos; – Combate também três tipos de sarnas: Sarcópticas, Demodécica e Otodécica; – Começa a agir rapidamente; efeito a partir de 3 horas; – Protege por 35 dias; – Contém 1 comprimido mastigável. Simparic é eficaz e altamente palatável, ele é indicado para ação contra pulgas, carrapatos e sarnas. O Antipulgas e carrapatos Simparic 40mg foi desenvolvido para combater as indesejadas pulgas e carrapatos, mantendo sua eficácia por até 35 dias. O simparic ajuda também a combater até três tipos de sarna a Sarcópticas, Demodécica e Otodécica, tem fácil aceitação pelos cachorros pois os comprimidos são palatáveis e saborosos. O antipulgas é ideal para cães a partir de 8 semanas de idade, é importante administrar o comprimido conforme o peso corpóreo do pet. Modo de usar: Administrar via oral, 1 comprimido por mês. Simparic é um comprimido mastigável, sendo altamente palatável, podendo ser administrado com o sem alimentos. Sua fórmula age contra as pulgas resistentes, pode ser utilizado como parte do tratamento estratégico para controle de dermatite alérgica a picada de pulgas (DAPP). Dicas: – Simparic é indicado APENAS para cachorros. – O Simparic pode ser administrado em cães de pequeno, médio e grande porte de acordo com o seu peso corpóreo. – Não administrar em caso de hipersensibilidade por parte do animal à substância ativa ou a algum dos excipientes – Se a sua cadela estiver grávida aconselhe-se com o médico veterinário antes de administrar este medicamento veterinário.', 119.9, 98.32, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134211-7r98o-m62wp7uhg1u885', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F14804314104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193697427', 'Placa Módulo Electrolux DF34A 41003893 - Bivolt', 'Placa Módulo Electrolux DF34A 41003893 - Bivolt Componente eletrônico essencial para o funcionamento de refrigeradores Electrolux, projetada especificamente para modelos compatíveis. Este módulo de controle gerencia diversas funções do refrigerador, incluindo a regulação da temperatura, o acionamento do compressor, e a operação do sistema de degelo, garantindo um desempenho eficiente e confiável do aparelho. Sendo bivolt, ela pode operar em diferentes voltagens (110V e 220V), oferecendo maior versatilidade e facilidade de instalação. Fabricada com componentes de alta qualidade, a Placa Módulo DF34A assegura durabilidade e resistência, contribuindo para a manutenção e prolongamento da vida útil do refrigerador.', 109.9, 109.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mkctktjgs0zk6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23193697427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258757770', 'Limpa Alumínio Roda Chassi Motor Aro Alumax 5L Vintex', '🧪 ALUMAX 5L VINTEX – Desincrustante Para Limpezas de Alta Qualidade 🧼 Desincrustante de alta performance, ideal para limpezas pesadas em rodas, chassis, motores, baús de alumínio e muito mais. Produto concentrado, econômico e de rápida ação. 📦 REFERÊNCIAS COMPATÍVEIS: 35270, 2008005 🏷️ INFORMAÇÕES DO PRODUTO: 🏢 Marca: Vintex 🧴 Tipo: Desincrustante 🌟 Condição: Novo ⚖️ Volume: 5 Litros 👁️ Aparência: Líquido límpido 🖌️ Aplicação: Manual, com pulverizador ou pincel 🔄 Diluição recomendada: 1:10 (pode variar conforme a sujeira) 📊 Rendimento: Varia conforme o grau de sujidade e diluição 🛡️ Garantia: 90 dias 🧰 APLICAÇÕES RECOMENDADAS: ✅ Superfícies metálicas: alumínio, ferro, aço inox ✅ Rodas de alumínio e chassis de veículos ✅ Baús de alumínio e carrocerias metálicas ✅ Motores e peças metálicas oxidadas ✅ Remoção de incrustações pesadas, ferrugens leves e sujeiras minerais ✅ Manutenção pesada em veículos, máquinas agrícolas e equipamentos industriais ✅ Limpeza de resíduos de cimento ou cal ✅ Preparação de superfície antes de pintura ou tratamento 🚫 Não recomendado para: Pintura automotiva Plásticos Vidros Mármore 💡 PRINCIPAIS CARACTERÍSTICAS: 💪 Alta performance na remoção de sujeiras minerais ⚡ Rápida ação na desoxidação e desengraxe 🧴 Produto concentrado e econômico 🔧 Reduz o tempo de limpeza manual 🏭 Indicado para uso profissional (oficinas, indústrias, centros de estética automotiva) 🧑‍🔬 MODO DE USAR: Dilua o produto conforme a necessidade (recomendado 1:10) Aplique com pulverizador ou pincel em toda a superfície Aguarde 1 a 2 minutos Enxágue bem com jato d’água 🛒 DISPONÍVEL NAS LOJAS OFICIAIS: ✅ Camillo Parts ✅ Genuine Automotive ✅ Edumac Parts Garanta seu Alumax 5L Vintex com a qualidade, garantia e suporte