INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293827630', 'Guarda-roupa Casal Easy Slim 8 Portas Com Pés Amendoa Clean/Off White', 'O Guarda Roupa Easy Slim 8 Portas é um móvel compacto e impecável! perfeito para dinamizar a distribuição de espaço de seu quarto, com muito estilo e beleza. Com acabamento elegante, design moderno e interior bem aproveitado, o Easy Slim é um guarda roupa que possui o interno diferenciado, composto por nichos que irão acomodar suas roupas com alta praticidade e organização. Além disso, é um roupeiro projetado 4 gavetas de corrediças telescópicas, muito seguras e agradáveis ao deslizar para abrir. Compostas especialmente com distanciadores em MDF. Além de toda elegância, essa mobilia conta commodernos pés que proporcionam maior estabilidade para sua estrutura. Um requinte que soma inovação e tradição em um único móvel. Sua casa merece possuir a praticidade e o estilo do Easy Slim corAmendoa Clean. Ficha Técnica ALT 2050mm | LAR 23600mm | PROF 470mm Produto em MPD com chapas de chapas de 12mm e 15mm. Interno diferenciado com nichos; 04 gavetas com corrediças telescópicas; Gavetas com distanciadores em MDF; Costas inteiriças; Puxadores em MDF; Cabideiros em PVC; Espaço para roupa longa; Espaço para sapatos.', 1319.9, 1209.9, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-7rd3o-m781lcwlmxsmc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1372644554%2F22293827630', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
