INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392823761', 'Extrato Oleoso de Calêndula - Aromaterapia - Pele e Cabelo - 50ml', 'RICO EM ACIDO LINOLEICO QUE POSSUI PROPRIEDADES HIDRATANTESO extrato oleoso de Camomila Alemã é extraído por maceração das flores em óleo de girassol. É indicado como hidratante, emoliente e calmante. ÓLEO PARA PELES SENSÍVEISO Extrato Oleoso de Calêndula é extraído por maceração das flores em óleo de girassol. Em virtude do ácido oleanólico, possui ação calmante e refrescante para peles sensíveis, avermelhadas e delicadas. PELES RESSECADAS E RACHADASNa pele traz maciez, emoliência e suavidade e é rapidamente absorvido. É especialmente indicado para peles delicadas e ressecadas, mas também pode ser usado em pele mista e oleosa. É rico em vitaminas, ácidos graxos, carotenoides e óleos essenciais presentes na flor de calêndula. VITALIDADE AOS CABELOSNos cabelos o extrato oleoso de Calêndula serve para dar vitalidade, maciez e brilho. Evita caspa e problemas do couro cabeludo, hidrata e acentua a cor dos cabelos claros, trazendo luminosidade. PRODUTOS NATURAISNossos óleos são puros e naturais, sem aditivos, corantes, conservantes, antioxidantes, emulsificantes ou estabilizantes, portanto, estão sujeitos à estação do ano da planta, clima, chuva, entre outras variáveis.', 41.0, 41.0, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Essential Oils', 'https://cf.shopee.com.br/file/sg-11134201-7rcci-lqz8wbwihjs176', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137364730%2F22392823761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599830227', 'Bolsa Para Ferramentas Com 14 Bolsos Sata St95181 13 Pol.13" - Reforçada', 'VENDIDO POR COMASP FERRAMENTAS | EMITIMOS NOTA FISCAL 🔧 BOLSA DE FERRAMENTAS 13" ST95181 - RESISTÊNCIA E PRATICIDADE PARA O SEU DIA A DIA! 🧰 A bolsa de ferramentas 13" modelo ST95181 é ideal para quem busca organização, mobilidade e durabilidade! Com design compacto e funcional, ela é perfeita para profissionais da construção civil, instaladores, mecânicos e também para uso doméstico. ✨ Destaques do Produto: ✅ Tecido reforçado e costuras duplas para maior resistência ✅ Compacta e leve, com ótimo espaço interno ✅ Bolso frontal com velcro + bolsos laterais para acesso rápido às ferramentas ✅ Alça de mão reforçada para transporte seguro ✅ Ideal para uso profissional ou hobby 📏 Dimensões Aproximadas: 📐 Comprimento: 33 cm (13”) 📐 Largura: 18 cm 📐 Altura: 20 cm 💼 Leve suas ferramentas com praticidade e segurança! Tenha tudo sempre à mão com essa bolsa resistente e funcional. Excelente custo-benefício! 🚚 ENVIO RÁPIDO | 💯 PRODUTO ORIGINAL | 🛠️ GARANTIA DE SATISFAÇÃO', 106.72, 99.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdy4-mbpeobcegnp184', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979559296%2F21599830227', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
