INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14424671744', 'Se Deus Existe, Por Que Existem Ateus? R.C. Sproul', 'No livro "Se Deus Existe, Por Que Existem Ateus?", o autor R.C. Sproul aborda 4 argumentos de autores ateístas, ele examina essas obras com bases psicológicas e teológicas, e mostra que existem explicações tanto para a descrença quanto para as crenças. De acordo com Sproul, as afirmações ateístas não devem ser aceitas cegamente.', 38.9, 36.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/b27516a32c962c86537b9add6918b561', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F14424671744', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
