INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997920441', 'Capa Case Capinha Carteira Dual para iPhone 16 Porta-Cartão, Proteção Reforçada - Gshield', 'A Capa Carteira Dual para iPhone 16 é a fusão de proteção e praticidade! Além de proteger o seu iPhone 16, a Capa Carteira Dual da Gshield oferece espaço para seus cartões essenciais e dinheiro, combinando a conveniência de uma carteira com a funcionalidade de uma capa de proteção. Fabricada com materiais de alta qualidade, a Capa Carteira Dual não só protege contra arranhões e quedas, mas também mantém uma aparência elegante ao longo do tempo. A estrutura durável envolve completamente o seu celular, garantindo proteção contra impactos, arranhões e sujeira. Bordas elevadas também protegem a tela e a câmera contra danos acidentais. Além disso, os recortes precisos proporcionam acesso fácil a todas as portas, botões e funções do seu iPhone 16 sem a necessidade de remover a capa. Eleve a praticidade e a proteção do seu iPhone 16 com a Capa Carteira Dual da Gshield, a escolha ideal para quem busca funcionalidade sem abdicar do estilo. ESPECIFICAÇÕES - Material: Polipropileno de alta densidade - Não Amarela - Marca: Gshield - Dimensões: Dimensões exatas do aparelho - Proteção: Contra impactos e riscos à tela - Certificações: Us Military COMPATIBILIDADE - iPhone 16 ITENS INCLUSOS - 1x Capa protetora', 142.97, 142.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rdw0-m0yuyvszap4905', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F19997920441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693399577', 'Película para Xiaomi Poco M6 Pro - Traseira de Fibra de Carbono - Gshield', 'Proteja a traseira com a película para Xiaomi Poco M6 Pro A Película Traseira de Fibra de Carbono para Xiaomi Poco M6 Pro, da GShield, protege seu aparelho contra riscos e arranhões na parte de trás. Para uma maior proteção, as películas traseiras podem ser usadas em conjunto com as capas da Gorila Shield, evitando o acúmulo de detritos no interior do acessório e eventuais arranhões no celular.', 21.97, 21.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rd74-luz25pnphvvpec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23693399577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253258726', 'Capa case capinha para Motorola Moto G56 - Silicon Veloz - Preta - Gshield', 'A capa que garante proteção e estilo para seu Motorola Moto G56! A Capa Silicon Veloz, da Gshield, é a combinação perfeita de estilo e segurança para proteger o seu celular. Feita com silicone de alta qualidade, essa capa proporciona uma proteção robusta contra quedas e impactos, graças à sua avançada tecnologia de absorção de impacto. A Capa Silicon Veloz também conta com recursos especiais, como a tecnologia Tall Grade e a proteção para câmera, que evitam arranhões indesejados, preservando a integridade do seu aparelho. Além disso, ela foi projetada para se adaptar perfeitamente aos botões de volume, ao botão lateral e às curvas do seu smartphone, garantindo uma experência de uso suave e sem interrupções. Sua parte interna é revestida com uma camada de microfibra, que proporciona uma proteção adicional ao seu dispositivo. Seu exterior em silicone é anti-impressão digital, mantendo um aspecto limpo e livre de marcas. Além disso, sua superfície é fácil de higienizar, proporcionando uma aparência sempre impecável. Com a capa Silicon Veloz, você terá a tranquilidade de saber que o seu smartphone está protegido de forma elegante e eficiiente, sem comprometer o estilo e a funcionalidade do aparelho. ESPECIFICAÇÕESMarca: GshieldMaterial: Silicone | MicrofibraDimensões: Dimensões exatas do aparelhoCor: PretaCertificações: Us Military', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-8262k-mjh4wqntg26cc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F58253258726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093959411', 'Tampa Dianteira Compressor CVC Corsa / Astra / Vectra / Gol G5/ Fox / Polo/ Palio/ Idea/ Doblo *', 'Bem-vindo à loja oficial da GM AR PEÇAS E ACESSORIOS! Kit tampa CVC + Rolamento Aplicável nos seguintes veículos: VW CVC GOL SAVEIRO VOYAGE G5 G6 G7 FOX POLO GM CVC CORSA/CELTA 02A...12/PRISMA 06A...12 GM CVC CELTA 1.0 12A.16/PRISMA 1.0 12A.13 GM CVC AGILE 1.4 09A..14/MONTANA 1.4 11A.14 GM CVC ZAFIRA 2.0 01A..12 GM CVC ASTRA 1.8 2.0 02A.12/VECTRA 2.0 06A.12 GM CVC CORSA/MONTANA 04A12 GM CVC CELTA 1.0 12A16/PRISMA 1.0 1.4 12A13 GM CVC CORSA CLASSIC FIAT CVC PALIO 1.8/DOBLO 1.8/STILO 03A09 IDEIA 1.8 PRODUTO A PRONTA ENTREGA ***ENVIO IMEDIATO*** Nossa empresa fica consolidada no estado do Paraná e atuamos no ramo de distribuição de peças com sede em Londrina. Somos especializados em tudo o que é relacionado à ar condicionado de veículos de passeios, máquinas agrícolas e Pesados, contamos também com todas as ferramentas necessárias para manutenção e instalação. Hoje oferecemos ao mercado de peças de reposição, produtos de alta performance e durabilidade, aliadas com toda qualidade exigida pelas montadoras. IMPORTANTE • Recomendamos que a montagem seja feita de forma prática e eficaz, com auxílio de um profissional, evitando assim possíveis danos na peça ou em demais componentes do sistema. • Não nos responsabilizamos pela instalação indevida ou por mau uso da peça, causando assim a perda da GARANTIA. • Prazo de entrega, a GM AR PEÇAS E ACESSORIOS! garante despacho no mesmo dia para pedidos efetuados até as 13 horas. Para compras efetuadas após este horário, finais de semana e feriados serão enviadas no próximo dia útil. • Imagens meramente ilustrativas. E para finalizar, estamos aqui para melhor atender nosso cliente e, portanto, quaisquer eventuais dúvidas estamos à disposição no campo de resposta para lhe instruir. Nosso horário de atendimento: De SEGUNDA a SEXTA das 8:00 as 18:00.', 355.35, 337.59, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Air Conditioning', 'https://cf.shopee.com.br/file/sg-11134201-7reof-m90e0ask42p519', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1528132983%2F22093959411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14491128450', 'Película Gamer Fosca para Samsung Z Flip 4 - Hydrogel Anti-Risco e Anti-Reflexo - Gshield', 'Aumente a resistência com a película para Samsung Galaxy Z Flip 4 5G A Película Gamer de Hydrogel Fosca para Samsung Galaxy Z Flip 4 5G, da Gshield, garante proteção extra para a tela do seu dispositivo e deixa a tela sem reflexos melhorando a experiencia durante jogos. Produzida com a tecnologia hidro nano pet + material semelhante ao silicone, são ultra resistentes contra riscos e com revestimento oleofóbico, atenuando as marcas de digitais na tela do aparelho; a película se adapta às extremidades curvadas, cobrindo todo o visor. ESPECIFICAÇÕES Material: Hidro nano pet + TPU Soft Gel Marca: Gshield - ( Gorila Shiel d ) Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High Definition Certificações: US Military Dimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais. COMPATIBILIDADE Samsung Galaxy Z Flip 4 5G ITENS INCLUSOS 1x películas de hydrogel Kit de instalação', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/af5e476c651a1f4a94725e9f1382beb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F14491128450', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252609172', 'Kit 2 Seringas c/Ponteira Lavagem Nasal Bebê e Adulto Lillo', 'Kit 2 Seringas de Lavagem Nasal 10ml com Ponteira em Silicone para uso Infantil e Adulto Colorida - Lillo O Kit de Seringas para Lavagem Nasal da Lillo foi especialmente desenvolvido para ajudar na tarefa de desobstrução das vias respiratórias. Totalmente livre de Bisfenol-A, elas possuem ponteiras em silicone macio de formato delicado e anatômico que não machuca o nariz na hora da lavagem. A utilização da seringa é extremamente fácil e simples. Basta preenchê-la com soro fisiológico em temperatura ambiente de acordo com a quantidade recomendada pelo médico. Em seguida, sente a criança levemente inclinada para frente, ou no caso de uso adulto, posicione o corpo da mesma forma orientada. Insira a seringa na cavidade nasal que deseja lavar e com uma pressão única, o jato de soro será liberado rapidamente, ajudando a remover a secreção e desobstruir as vias respiratórias. Principais Características: - Idade recomendada: A Partir de 4 Meses - Auxilia na Desobstrução das Vias Respiratórias - Alívio da Congestão Nasal - Ponteira em Silicone Macio - Ponteira Anatômica - Não machuca - Utilização Fácil e Simples - Livre de Bisfenol-A - Seringa de 10ml - Uso Infantil e Adulto Especificações Técnicas: - Conteúdo da Embalagem: 2 Seringas de Lavagem Nasal Lillo - Dimensões do Produto (AxLxP): 17,5 x 7,0 x 2,1cm - Composição/Material: Polipropileno, Borracha natural, Silicone - Peso: 0,090kg - Garantia: 30 Dias (Contra Defeitos de Fabricação Pelo Fabricante) - Certificação: ANVISA N° 80421900008 - Código do Fabricante: 640601 - EAN: 7896033234214 - Marca: Lillo Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante.', 29.0, 27.0, NULL, 'Mom & Baby > Baby Healthcare > N