INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21898019381', 'Refrigerador Brastemp 2 Portas Branco 375L FF 220V BRM44HB', 'Refrigerador Brastemp 2 Portas Branco 375L Frost Free 220V BRM44HB Design sofisticado e grande capacidade para armazenar alimentos, o Refrigerador Brastemp BRM44HBANA conta com compartimento especial que se encaixa perfeitamente no freezer ou na geladeira, possibilitando gelar as bebidas de forma eficaz. Você consegue deixar os alimentos bem organizados no seu refrigerador graças aos compartimentos pensados para o encaixe de todos os alimentos, bebidas e até mesmo seus temperos favoritos. Aproveite melhor o espaço do seu congelador, com a tecnologia Frost Free você não precisa mais fazer o degelo do seu refrigerador, não tem mais o acúmulo de gelo! Gavetão de legumes Fresh Zone Suas frutas e verduras organizadas e conservadas por mais tempo com o sistema Fresh Zone. Compartimento extra frio Gele as bebidas mais rápido e conserve melhor frios e laticínios. Acesso Rápido Compartimento de fácil acesso para armazenar os itens que você mais usa. Temperos Compartimento específico para guardar e deixar seus temperos sempre à mão. Especificações Técnicas: - Marca: Brastemp - Modelo:&nbsp;BRM44HB - Cor: Branco - Capacidade Total: 375 Litros - Tipo: Frost Free - Portas: 2 - Painel de Controle: Externo - Voltagem: 220V - Largura: 62,1cm - Altura: 176cm - Profundidade: 75,5cm - Peso: 58kg - Classificação Energética: A - Garantia: 12 meses - Potência: 104 W - Consumo: 54 kWh - Corrente: 2 A - Frequência: 60 Hz - Selo INMETRO: Sim - Ruído: 42 dBA - Capacidade Freezer: 86 Litros - Capacidade Refrigerador: 288 Litros', 5599.0, 3599.0, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-23010-q0dkanimdomv47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fsho