INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697654787', 'Produto Revitalizador Renovador de Plasticos Intense 500ml Vonixx', 'INTENSE 500ML - RENOVADOR DE PLÁSTICOS INTERNOS DESCRIÇÃO: Intense é um renovador de plásticos com proteção UV, cuja fórmula balanceada promove acabamento natural e toque seco, com durabilidade de 6 meses. O produto deve ser utilizado especificamente na parte interna do automóvel, em superfícies como vinil e plásticos em geral DURABILIDADE: Até seis meses de proteção nos plásticos internos MODO DE USO: 1. Certifique-se que a superfície esteja limpa e seca 2. Aplique uma pequena quantidade de produto de maneira uniforme com o auxílio de um aplicador de microfibra 3. Espalhe bem até o total preenchimento da peça', 62.92, 62.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lt7256gjzen476', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F20697654787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
