INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694312541', 'Tênis Skechers Masculino Arch Fit 2.0', 'Conheça o tênis Skechers Arch Fit 2.0, ideal para quem busca estilo, praticidade e suporte ortopédico no dia a dia, um modelo que já conquistou seu espaço entre os favoritos do mercado. Seu cabedal em jacquard com fechamento por cadarço garante ajuste seguro e visual moderno, enquanto a tecnologia exclusiva Arch Fit® oferece suporte superior ao arco do pé, distribuindo melhor a pressão e aumentando a estabilidade. Além disso, é lavável à máquina, produzido com materiais 100% veganos e projetado para manter o conforto em cada passo. Já a palmilha removível Arch Fit® e a entressola leve em EVA proporcionam amortecimento e conforto prolongado. Não perca tempo e garanta o seu!', 659.89, 479.88, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82614-mm8wuzpfjim942', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F23694312541', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
