INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11354942027', 'Interruptor Limpador Para-Brisa 24V Para Mercedes Caminhões E Ônibus', 'Descrição: Comprando até 12h30, enviaremos seu pedido no mesmo dia (em dias úteis). Receba seu produto rápido. Temos garantia de 3 meses e tiramos todas as dúvidas necessárias no chat. Pontos importantes: Interruptor de lavador do para-brisa de 24V, essencial para manter a visibilidade e segurança durante a condução de caminhões e ônibus Mercedes. Produto original de qualidade, fabricado pela Univel/Micro. Compatível com uma variedade de modelos de caminhões e ônibus da Mercedes-Benz. Ideal para substituir interruptores danificados ou desgastados, garantindo o funcionamento adequado do sistema de limpador de para-brisa. Fácil instalação e alta durabilidade para um desempenho confiável. Aplicação: Compatível com os seguintes veículos Mercedes-Benz: Caminhões Ônibus Identificação do Produto: Marca: Univel/Micro Número da Peça (Part Number): A.350.545.84.14 Código Universal do Produto (EAN): 7895272904643 Código IPI: 87082999 Código NCM: 8871 SKU Universal: 90464 Renove o sistema de limpador de para-brisa do seu caminhão ou ônibus Mercedes com o interruptor original de qualidade. Adquira já e tenha uma condução mais segura e confortável! Se precisar de ajuda, estamos à disposição para atendê-lo. Tags e palavras-chave para SEO: Interruptor Limpador, Para-Brisa, 24V, Mercedes, Caminhões, Ônibus, Peça Original, Acessórios Automotivos.', 122.32, 110.09, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/591f8748493ea8a9a1e47e3c3105ca3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290883399%2F11354942027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598542590', 'Pote Plástico Redondo Hermético Cappuccino 3,2L Flor Sanremo', 'O Pote Plástico Redondo Hermético Cappuccino 3,2L Flor Sanremo conta com design moderno, borracha de vedação integrada na tampa e válvula em forma de flor que libera a saída do vapor: quando aberta, permite que o pote vá tampado ao micro-ondas. É mais estilo para a sua cozinha e funcionalidade para a rotina do seu dia a dia. - Vai no micro tampado, no freezer e na máquina de lavar. - Tampa com vedação em borracha e válvula para saída do vapor. - Possui fechamento hermético: não vaza nada. - Transparente e com linhas de graduação que indicam as quantidades do conteúdo. - Livre de BPA: não prejudica a saúde da sua família. - Alças para transporte. Medidas: 12 x 21,3 x 22,9 cm (A x L x C)', 31.9, 31.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-8259r-mqnh4h2v5vy9e8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F20598542590', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
