INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799181302', 'Caixa Termica Com Rodas 61,5 Litros Coleman Cooler Termico Grande Cinza Com Alça Porta Copos Camping', 'Caixa Térmica com Rodas 61,5L Lakeside Coleman Desfrute de aventuras ao ar livre com a Caixa Térmica 61,5L Lakeside Coleman, uma solução robusta e inovadora para manter suas bebidas e alimentos frescos. Com recursos excepcionais, esta caixa térmica redefine a experiência de refrigeramento portátil. Características Principais: Material Durável: Fabricada em plástico resistente, garante durabilidade e resistência em suas jornadas. Capacidade Generosa: Com capacidade para 61,5 litros, acomoda até 101 latas, proporcionando amplo espaço para suas necessidades de resfriamento. Conservação Térmica Avançada: Mantenha seus itens refrigerados por até 4 dias com gelo, graças ao isolamento em PU com baixo CO2. Design Funcional: Tampa Articulada: Com dobradiças, apresenta 4 porta-copos e régua integrada. Alças Laterais: Facilitam o transporte seguro. Tampa Have-A-Seat™: Suporta até 113kg, proporcionando um assento conveniente. Higiene e Durabilidade: Forro Antimicrobiano: Resistente a odor, mofo e bolor. Cantos Chanfrados: Oferecem isolamento ideal para manter alimentos e bebidas mais frios por mais tempo. Recursos Adicionais: Sistema TempLock™: Revestimento interno em PU. Sistema EZ-CLEAN™: Facilita a limpeza. Sistema Flow no Fundo: Evita contato direto com a superfície, influenciando menos pela temperatura externa. Suporta Termômetro: Para monitoramento preciso. Dreno para Escoar Degelo: Sem necessidade de inclinação, à prova de ferrugem e resistente a vazamentos. Produção nos EUA: Garantia de qualidade e confiabilidade. Explore o mundo com a Caixa Térmica 61,5L Lakeside Coleman, sua parceira ideal para manter a diversão gelada em todas as suas aventuras.', 1765.99, 895.39, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Dry Bags', 'https://cf.shopee.com.br/file/br-11134207-820lw-mqyq2w85v85i8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F18799181302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40682901308', 'ZURU Minha Boneca Mini Baby Surprise, Conjunto de Brincadeira com Carrinho de Bebê Colorido com Bolinhas + Manta de', 'ZURU My Mini Baby Kit Surpresa Dupla Projetado para meninas a partir de 3 anos, acompanha duas bonecas mini bebê idênticas (de macacão rosa com bolinhas), carrinho de bebê, fralda, touca, cueiro, certidão de nascimento e outros acessórios. Tons suaves de rosa, branco e azul claro, com estilo doce e fofo, estimula o afeto e o senso de responsabilidade. Feitas em material macio, fácil de segurar e ideal para brincadeiras de faz de conta.🎁 Embalagem de cápsula surpresa em formato de bola, com acessórios variados como fralda, chapéu, cueiro e carrinho de bebê. Permite passeios com o carrinho, vestir a boneca, preencher o cartão de nascimento e explorar diferentes brincadeiras. Ideal para presente de aniversário de 3 a 6 anos, brincadeiras em creche, interação entre pais e filhos e introdução ao faz de conta.', 106.0, 105.9, NULL, 'Hobbies & Collections > Toys & Games > Capsule Toys', 'https://cf.shopee.com.br/file/sg-11134253-8258b-mqy44vw3ezuo24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F40682901308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
