INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997312215', 'Quebra Sol Automotivo Dobrável Protetor de Raio Solar UV Camada Térmica Logo Techone', 'Quebra Sol Automotivo Universal Dobrável Proteção Raios Solar UV Camada Térmica Sunshade Evitar Ressecamento Reduz Temperatura Interna Ventosas para Fixação Todos Carros Universal Sabia que a temperatura interna de um veículo geralmente é maior do que a temperatura externa que sentimos? Pensando nisso, é essencial manter o carro protegido do sol sempre que possível, utilizando um bom quebra-sol automotivo. Aqui apresentamos um modelo de quebra-sol constituído por material metalizado dobrável, com proteção contra raios UV, que evita o ressecamento do painel e do volante, e ventosa para uma boa fixação. [ESPECIFICAÇÕES / CARACTERÍSTICAS] • Material metalizado dobrável • Proteção contra raios UV • Minimiza o impacto do sol, evitando o ressecamento do painel • Reduz a temperatura interna do veículo • Contém ventosas para fixação • Tamanho: 130cm x 60cm • Código Universal: 4895228227140 [MEDIDAS / PESO DA EMBALAGEM] • Peso: 0,11Kg • Altura: 3cm • Largura: 13cm • Comprimento: 61cm', 24.5, 24.5, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Sun Shade', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lr3aw0p3h0kk4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F22997312215', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
