INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26042125547', 'Fralda Geriátrica Tena Slip Noturna G Leve 32 Pague 28 unidades', 'A Fralda Descartável Adulto Noturna é a escolha ideal para quem busca proteção máxima contra incontinência severa, especialmente durante a noite. Indicada para pessoas com pouca ou nenhuma mobilidade, como usuários acamados, essa fralda unissex oferece até 12 horas de proteção contínua, garantindo conforto, segurança e tranquilidade. Com dupla camada de absorção e núcleo de alta performance, ela mantém a urina longe da pele, ajudando a prevenir irritações e infecções cutâneas. Seu sistema de fechamento Microganchos MultiFix permite ajustes precisos e reutilizáveis, sem danificar o produto. Benefícios e Diferenciais: Indicação: Incontinência urinária severa – uso noturno Zero vazamentos: barreiras protetoras e elásticos nas costas para máxima segurança Sistema MultiFix com microganchos: ajuste perfeito ao corpo, mesmo após múltiplas aberturas Controle de odores: neutraliza cheiros indesejáveis Material macio com aloe vera: toque suave e cuidado com a pele Cobertura externa tipo tecido: mais conforto, menos ruído e melhor ventilação Testada em laboratório e por usuários reais: eficácia comprovada Ideal para quem precisa de uma fralda geriátrica noturna de alta absorção, essa solução garante noites tranquilas e pele protegida. Mais conforto, mais segurança, mais qualidade de vida.', 165.29, 165.29, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-824i1-mf1b5ylwuyvj77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819145905%2F26042125547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18498919757', 'Chave Cabo T Ponta Hexagonal 6x180 mm Tramontina PRO', 'Seu cabo em forma de T permite a aplicação de torque mais elevado aos parafusos. Disponíveis com ponta chata, cruzada, hexagonal, hexagonal abaulada, trafix e canhão. Escolha o tamanho e perfil ideal para o seu trabalho e mãos à obra. Haste em aço ferramenta S2 temperada.Acabamento cromado.Ponta fosfatizada e magnetizada.Cabo injetado.As chaves tipo L ou Cabo T são submetidas a ensaios de torque e de dureza para analisar a resistência mecânica e atender aos valores da norma específica.Grande variedade de formas, perfis de pontas e comprimentos para as diversas aplicações automotivas e industriais.A chave cabo T possui o cabo de plástico injetado no braço curto da chave para ampliar a aplicação de torque.Apertar ou afrouxar parafusos com sextavado interno.Sua forma construtiva possibilita a aplicação de torque mais elevado no parafuso.As ferramentas são produzidas e testadas conforme normas específicas.Utilizada em manutenção de motocicletas. Seu cabo em forma de T permite a aplicação de torque mais elevado aos parafusos. Disponíveis com ponta chata, cruzada, hexagonal, hexagonal abaulada, trafix e canhão. Escolha o tamanho e perfil ideal para o seu trabalho e mãos à obra.', 27.1, 27.1, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbmm-ll56ois0ck9p0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F18498919757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
