INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692187658', 'Pulseira Feminina de Prata 925 Símbolo da Paz', 'Pulseira Símbolo da Paz: Apresentamos a Pulseira Símbolo da Paz em Prata 925, uma joia que combina o poderoso símbolo da paz com a beleza duradoura da prata. Esta pulseira é uma expressão de estilo e uma afirmação de esperança. Especificações da Pulseira: Comprimento: 18,5cm Tamanho do pingente: 14mm x 12mm Peso: 1.2g Material:Prata 925 O símbolo da paz confere um toque de harmonia e significado à pulseira. Cada detalhe foi meticulosamente trabalhado para capturar a luz de maneira encantadora, oferecendo um brilho suave que realça a beleza da prata. Confeccionada em prata 925, esta pulseira combina beleza com qualidade excepcional. O design do símbolo da paz evoca uma mensagem de união e serenidade, tornando esta pulseira uma escolha significativa para quem deseja expressar valores positivos. Use a Pulseira Símbolo da Paz em Prata 925 para adicionar um toque de esperança e estilo à sua coleção de joias. Seja como um acessório que reflete seu desejo por um mundo mais harmonioso ou como um presente que transmite uma mensagem de paz, esta pulseira é uma afirmação de estilo que celebra a beleza do símbolo e da prata.', 82.8, 52.0, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/sg-11134201-7rd48-lvlzkieh5x8hf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F23692187658', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
