INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11274219481', 'Par De Alto Falante Pioneer Ts-1360br Triaxial 5" Polegadas Pioneer 100w Rms', 'O TS-1360BR É O NOVO ALTO-FALANTE DE 5 POLEGADAS DA PIONEER. SEU CONE DE POLIPROPILENO INJETADO GARANTE DURABILIDADE E PERFORMANCE COM BAIXO NÍVEL DE DISTORÇÃO, ENQUANTO O TWEETER PIEZOELÉTRICO TRAZ O BRILHO DOS SONS AGUDOS COM MUITO MAIS MUSICALIDADE. ALIANDO QUALIDADE AO DESIGN, SUA PROFUNDIDADE DE INSTALAÇÃO REDUZIDA FACILITA O USO EM UMA GRANDE VARIEDADE DE VEÍCULOS. *TWEETER PIEZOELÉTRICO TWEETER PIEZOELÉTRICO QUE REPRODUZ AS ALTAS FREQUÊNCIAS COM MUSICALIDADE *PROFUNDIDADE REDUZIDA COM PROFUNDIDADE REDUZIDA DE INSTALAÇÃO, É UMA EXCELENTE OPÇÃO DE DESIGN, QUE FACILITA A SUA ADEQUAÇÃO A UMA GRANDE VARIEDADE DE VEÍCULOS. PRINCIPAIS: * WOOFER COM CONE DE IMPP (POLIPROPILENO MOLDADO POR INJEÇÃO) * BOBINA DE VOZ RESISTENTE AO CALOR * TWEETER PIEZOELÉTRICO DE 11 MM EM PET * SUSPENSÃO BOLEADA * MIDRANGE COM CONE DE FILME DE 30 MM ESPECIFICAÇÕES: * POTÊNCIA RMS: 50 W (CADA) * RESPOSTA EM FREQUÊNCIA - 55 HZ A 20.000 HZ * SENSIBILIDADE (1 W/1M) - 85 DB * IMPEDÂNCIA: 4 OHMS CONTEÚDO DA EMBALAGEM: * 1 PAR DE ALTO-FALANTES * 8 PARAFUSOS * CERTIFICADO DE GARANTIA * LISTA DE POSTOS DE ASSISTÊNCIA TÉCNICA NOTAS DE RODAPÉ: – ALGUNS VEÍCULOS PODEM REQUERER ALGUMAS PEQUENAS ADAPTAÇÕES QUE SOMENTE DEVEM SER FEITAS POR UM TÉCNICO OU PROFISSIONAL DO RAMO. TODA E QUALQUER E ADAPTAÇÃO É DE RESPONSABILIDADE DO PROPRIETÁRIO DO VEÍCULO. – “OUVIR MÚSICA COM POTÊNCIA ACIMA DE 85 DECIBÉIS PODE CAUSAR DANOS AO SISTEMA AUDITIVO” (LEI FEDERAL 11.291/06)', 226.44, 203.8, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/0ccbbffa8c1de7e833bd8949c32a2ae9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F432660571%2F11274219481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597367091', 'Escova Rotativa Gold Brush 1300W - Lizz Pro', 'O que você precisa saber: - 3 em 1: Seca, escova e modela. - Tensões disponíveis: 127V e 220V (Não é Bivolt). - Potência de até 1300W. - Revestimento em cerâmica com Cerdas Mistas. - Sistema de rotação 360° com duas direções. - Controles adaptáveis com 2 ajustes de sopro e 3 de temperatura. - Tecnologia Ion Ceramic, Anti-Frizz Technique e Função Power Rotation. - Cabo giratório de 1,8 mt. - Garantia de 6 Meses. Por que escolher a Escova Rotativa Gold Brush 1300W? A Escova Rotativa Gold Brush 1300W combina tecnologia e eficiência, sendo a escolha ideal para quem busca um cabelo volumoso e bem modelado. Esta ferramenta 3 em 1 é ideal para secar, modelar e dar volume, proporcionando resultados profissionais diretamente em casa. Com design elegante e tecnologia de ponta, ela oferece tudo o que você precisa para ter cabelos impecáveis e radiantes. Características e Especificações técnicas: • Disponível nas tensões 127V e 220V (não é Bivolt) • A Escova Gold Brush é rotativa. • Potência: 1300W • Frequência: 60 Hz • Certificação INMETRO: Garantia de qualidade e segurança. Tecnologia Íon Ceramic: Tecnologia que combina cerâmica de alta qualidade com emissão de íons negativos para oferecer um cuidado mais eficiente e acabamento profissional aos fios. Anti-Frizz Technique: Tecnologia que ajuda na redução do frizz, proporcionam mais alinhamento, mais brilho e um acabamento mais bonito por mais tempo. Função Power Rotation: Faz a escova girar com maior potência, facilitando modelar cachos, ondas ou alisar mechas com rapidez, menos esforço e acabamento uniforme e profissional. Conteúdo da embalagem: 1 Escova, 1 manual de instrução e termo de garantia.', 479.9, 399.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-81zty-mmqjddi6c4jocc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1180886499%2F23597367091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202026310', 'Mini Bateria Infantil Importway Com 5 Tambores', 'Mini Bateria Infantil Importway Com 5 Tambores Vermelha A Mini Bateria Infantil Importway é um excelente brinquedo para desenvolvimento da habilidade motora da criança, como também ritmo e gosto pela música. Acompanha duas baquetas deixando a brincadeira ainda mais divertida. Especificações: *Marca: Importway *Modelo: BW038VM *5 Tambores *1 Estrutura *1 Suporte de prato fixo *2 Baquetas *Indicado para crianças a partir de 3 anos *Produto Certificado Pelo INMETRO Conteúdo da Embalagem: - 01 Mini Bateria Infantil Importway Com 5 Tambores "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Garantia 90 dias. *Imagens meramente ilustrativas Importway Importando Soluções com Qualidade, Inovação e Responsabilidade desde 2007.', 52.0, 52.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Percussion Instruments', 'https://cf.shopee.com.br/file/sg-11134201-822z5-miboj8msgyrle8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1543640059%2F58202026310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
