INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098652545', 'Conjunto Sala de Jantar Mesa Easy Pop 120x80cm Tampo MDF 40mm com 4 Cadeiras Confort Amêndoa/Off', 'Conjunto Sala de Jantar Mesa Easy Pop 120x80cm Tampo MDF 40mm com 4 Cadeiras Confort Veludo Liso Capuccino Amêndoa/Off White – Design Moderno, Conforto e Sofisticação para o seu Lar. Transforme sua sala de jantar com o Conjunto Easy Pop – uma combinação perfeita entre elegância, conforto e resistência. Composto por uma mesa robusta e quatro cadeiras estofadas, esse conjunto foi pensado para proporcionar momentos inesquecíveis à mesa, com estilo e funcionalidade. Mesa com Design Contemporâneo e Acabamento de Alta Qualidade Produzida em MDP/MDF com tampo maciço em MDF de 40mm com bordas chanfradas e arredondadas com toque aveludado, detalhe Off-White na base com pintura U.V alto brilho, tampo de vidro temperado com 4mm de espessura. Sapatas deslizadoras que protegem o piso. Mais do que beleza, ela entrega segurança, durabilidade e praticidade na montagem, suportando até 40kg. Sua embalagem foi desenvolvida com proteção extra para garantir que o produto chegue intacto até você. Dimensões da mesa: 78cm (A) x 120cm (L) x 80cm (P) Cadeiras Estofadas com Conforto e Estilo As cadeiras que acompanham o conjunto aliam conforto e sofisticação. Estofadas com espuma D-20 no assento e D-18 no encosto, as linhas do produto adaptam-se ao corpo e proporcionam maior conforto, oferecem uma experiência confortável em todas as refeições. A estrutura em MDF e MDP com pés reforçados garante estabilidade e resistência, suportando até 100kg. O detalhe das sapatas em PVC protege o piso e aumenta a durabilidade. Disponíveis no tecido Veludo, as cadeiras se adaptam facilmente a qualquer estilo de decoração. Desenho minimalista na espuma do encosto garantindo conforto e harmonia em qualquer ambiente. Dimensões da cadeira: 97cm (A) x 43cm (L) x 57cm (P)', 2033.6, 1329.9, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rase-mb3qijsapf5vd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1372644554%2F23098652545', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693899960', 'Capa de Chuva Motoqueiro Alba Europa Masculino TAM EG Preto', 'Esteja preparado para qualquer imprevisto na cidade ou na estrada. A capa de chuva impermeável da Linha Europa é a mais tradicional da marca Alba. O seu tecido combina flexibilidade com resistência, proporcionando liberdade de movimentos e segurança nas manobras. Prático e seguro, possui um bolso externo, além de refletivos nas costas, manga direita e bolso dianteiro. Especificações Técnicas: - Modelo masculino; - Cor preto; - Material totalmente impermeável; - Material do conjunto em PVC; - Tamanho EG. Conteúdo da Embalagem: - 1x Jaqueta em PVC; - 1x Calça em PVC.', 281.89, 197.33, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Covers', 'https://cf.shopee.com.br/file/sg-11134201-7repi-m8nfyy3cjjthb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F23693899960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394559076', 'WHISKY WOODFORD RESERVE BOURBON 750ML', 'Os aromas e sabores do Woodford Reserve são ricos e complexos, marcados pela laranja, caramelo e carvalho, com ligeiras notas de baunilha, além de traços adocicados de milho. No paladar, é levemente picante, os sabores predominantes são de caramelo e açúcar mascavo, com notas sutis de frutas secas, laranja e baunilha. Graduação alcoólica: 43,2% vol. Volume: 750 ml.', 271.99, 229.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-8259m-mg434wd0ov7wf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F22394559076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
