INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56761950463', 'Kit 3 Colágeno Boost 100ml Creme Firmador Colo Pescoço Seios Antirrugas Elasticidade Beleza Brasileira', 'Creme firmador para seios, colo e pescoço, desenvolvido para melhorar a firmeza, elasticidade e uniformização do tom da pele. Sua fórmula combina Nanoretinol, que estimula a produção de colágeno e a renovação cutânea, Niacinamida que reforça a barreira e uniformiza o tom da pele, Pantenol que promove hidratação profunda e Bioestimulador de Colágeno que auxilia na sustentação e prevenção da flacidez. Com o uso contínuo, a pele fica mais firme, radiante e linhas finas mais suavizada. Ideal para você que: - quer suavizar linhas finas e rugas dessa região - percebe flacidez ou perda de firmeza nos seios, colo e pescoço - busca estimular colágeno de forma contínua - precisa uniformizar marcas e manchas - quer manter o contorno do pescoço em qualquer fase O que só ele faz - Suaviza e uniformiza de forma significativa as rugas e linhas finas. - Estimula a produção de colágeno e melhora a elasticidade para uma pele sem flacidez. - Promove firmeza e hidratação na pele da região do pescoço até os seios. Como usar o Colágeno Boost? Com a pele limpa, aplique o produto na região dos seios, colo e pescoço. Comece pelos seios e suba até o pescoço. Massageie de forma suave até a completa absorção.', 291.0, 247.0, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-820lb-mp9py0fqam0x29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F500017527%2F56761950463', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6486195149', 'Parabarro Estribo VW Constellation - Par', 'Par de parabarro do estribo do caminhão VW Constellation. Produzido em plástico de alta qualidade, oferece durabilidade que esse tipo de peça necessita e ótimo acabamento. Características: - Produto com ótimo acabamento - Altamente resistente - Excelente custo-benefício - Fabricado com materiais padronizados de alta qualidade Especificações técnicas: - Marca: Universo do Caminhão - Modelo: Par de parabarro do estribo - Material: Plástico - Aplicação: Volkswagen Constellation - Código: 10156UN - Garantia: 3 meses Importante: Para instalação, recomenda-se a procura de um profissional especializado. Bem-vindo ao Universo do Caminhão! Desde 2011 somos referência nacional em peças e acessórios para caminhões. Pioneiros no e-commerce do setor, contamos também com lojas físicas em Santo André (SP) e Contagem (MG). Oferecemos qualidade, variedade e atendimento especializado para quem vive da estrada.', 150.0, 150.0, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Mud Flaps', 'https://cf.shopee.com.br/file/3e66bad22f175dcea6dc4f1e0c2637a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F424196763%2F6486195149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
