INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298271452', 'Kit 02 Cadernos Universitário 15 Matérias 240 Folhas Flow - Jandaia CAPA:Skate/Boys', 'Kit De 2 Cadernos Universitário 15 Matérias 240 Folhas Masculino. Pedidos feitos até às 11:00 horas (seg à sex) são enviados no mesmo dia! - DESCRIÇÃO: • Formato: 20x27,5cm - ideal para mochilas e pastas. • Tamanho Padrão (A4) • Capa: Dura com laminação fosca - resistente e fácil de limpar. • Número de Folhas: 240 - espaço para todas as suas anotações. • Matérias: 15 matérias. • Espiral preta - resistente e prática. • Diversas estampas Masculino: escolha a que mais combina com você! - Quantidade Do Kit: • 02 Cadernos Cada Um Com 240 Folhas - Qualidade Jandaia • Papel de alta gramatura: resistente e evita que a tinta marque na folha seguinte. • Arame resistente: garante que suas folhas fiquem firmes no lugar. • Acabamento impecável: um caderno que você vai ter orgulho de usar. • Aproveite a oferta por tempo limitado: Chega de cadernos sem graça! Com o Caderno Universitário 15 Matérias Masculino da Jandaia, você vai organizar seus estudos com muito mais estilo e praticidade. Quem busca um caderno bonito e funcional: as estampas Masculino e o acabamento de qualidade garantem um toque especial no seu dia a dia.', 70.0, 49.96, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-7rdya-mctgsmcgb42c66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F721033344%2F21298271452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892551513', 'Kit 4 Fraldas Geriátricas Bigfral Derma Plus XG com 14un cada', 'O Kit contém: 4 pacotes de Fraldas Geriátricas Bigfral Derma Plus XG com 14un cada. A Bigfral DermaPlus foi desenvolvida para adultos com incontinência urinária severa. Possui o exclusivo sistema de proteção total da pele, com extratos naturais hidratantes que ajudam a prevenir irritações, mantendo a pele protegida e saudável, além de sistema antiodor, trazendo até 10h de proteção e cuidado.', 372.89, 288.89, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7rcdr-lryff96l3pr178', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1131442264%2F23892551513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699842495', 'Kit Cozinha Vinagreen - Detergente + Desengordurante', 'Chegou a combinação perfeita para cuidar da sua cozinha com consciência. O Kit Cozinha Vinagreen une alto poder de limpeza com fórmulas sustentáveis, veganas e seguras para sua saúde e para o meio ambiente. Ideal para quem busca eficiência no dia a dia sem abrir mão dos princípios que realmente importam, o kit é composto por dois aliados indispensáveis: um detergente poderoso e um limpa gordura imbatível – ambos biodegradáveis, hipoalergênicos e livres de crueldade. O que o kit contém: 1x Detergente Gel Concentrado Vinagreen - 500ml Com fórmula concentrada de alto rendimento, limpa louças e utensílios com facilidade, removendo gorduras sem agredir a pele. É vegano, biodegradável e feito com ingredientes suaves que respeitam sua saúde e o planeta. 1x Limpa Gordura Vinagreen - 500ml Desengordurante potente à base de álcool orgânico que dissolve até as sujeiras mais difíceis sem esforço. Ideal para fogões, pias e superfícies engorduradas, promove uma limpeza prática e econômica, sem necessidade de enxágue. Por que escolher o Kit Cozinha Vinagreen? Limpeza poderosa e prática Fórmulas biodegradáveis e veganas Alto rendimento com menos desperdício Sem testes em animais Mais saúde para sua casa e para o planeta Uma cozinha limpa e sustentável começa com escolhas conscientes. Com o Kit Cozinha Vinagreen, você une praticidade, eficiência e cuidado com o meio ambiente em cada detalhe da sua rotina.', 40.98, 28.98, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-mc9p9nh8zpn5f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583886098%2F21699842495', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
