INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10991450024', 'Livro - Atividades para o desenvolvimento da inteligência emocional', 'Neste livro, serão trabalhados cinco blocos de competências emocionais, um bloco por capítulo - consciência emocional, adequação emocional, autonomia emocional, habilidades socioemocionais e habilidades para a vida e o bem-estar emocional. Por isso, a obra Atividades para o desenvolvimento da inteligência emocional nas crianças é uma ferramenta que se dirige aos educadores e pais, no intuito de encontrar nela exemplos de como abordar e avançar nesse tema com crianças entre 8 e 12 anos._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2009_x000D_ Autor: Rafael Bisquerra Alzina_x000D_ Idioma: Português_x000D_ Páginas: 192_x000D_ Dimensões: L 20.10 x A 27.00 x E 1.50_x000D_ ISBN: 9788538004165', 79.9, 79.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/1c3e0dfe7836f5592b3ffc9531c03398', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F10991450024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
