INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098053769', 'Jogo 2 Pneus Bridgestone Aro 16 Ecopia EP150 195/55R16 87V', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores.O pneu Bridgestone EP150 é um modelo com banda de rodagem simétrica que utiliza composto com baixa resistência ao rolamento, que significa muito mais economia, pois além de auxiliar na redução do consumo de combustível, também tem maior durabilidade e vida útil. O EP150 tem ótimo desempenho em aderência e estabilidade, além de garantir conforto de rodagem, graças ao baixo ruído, seja em uso urbano ou rodoviário. A estrutura com reforços garante a proteção necessária para pequenos impactos do dia a dia, como pequenos buracos e desníveis do asfalto. Sobre a marca Bridgestone Nascida em 1931 no Japão, a Bridgestone tem se dedicado a criar pneus que oferecem uma experiência única ao volante. Marcada por inovação, desempenho e compromisso com a segurança, os pneus Bridgestone proporcionam confiança em cada curva. Líder global no mercado de pneumáticos, a Bridgestone também estabeleceu sua marca com pneus de alta durabilidade e resistentes ao desgaste. Com forte investimento em pesquisa e desenvolvimento, a marca japonesa utiliza tecnologia avançada para garantir que cada pneu seja sinônimo de excelência.', 1439.77, 1324.59, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rfh4-m32ahywa9nac93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23098053769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
