INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897166203', 'Pingente de Prata 925 Pandeiro Chinelo e Caipirinha', 'Pingente de Prata 925 Pandeiro, Chinelo e Caipirinha O pingente de Prata 925 Pandeiro, Chinelo e Caipirinha é uma celebração descontraída da cultura brasileira. Com um tamanho de 12mm e um peso leve de 1.0g, este pingente é uma adição divertida e única à sua coleção de joias. Especificações: Tamanho: 12mm Peso: 1.0g Material: Prata 925 Celebre o Estilo Brasileiro O Pingente de Prata 925 Pandeiro, Chinelo e Caipirinha é uma homenagem descontraída à alegria e à diversidade do Brasil. Adicione um toque de brasilidade à sua joalheria e destaque-se com essa peça única. Descubra Mais na Aqua Joias Explore nossa coleção completa de pingentes de prata 925 e descubra peças exclusivas que refletem sua personalidade. Na Aqua Joias, garantimos qualidade e estilo em cada detalhe.', 74.2, 59.99, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-loyezs4wdt4if6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F22897166203', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
