INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29980063867', 'Conjunto Adesivos e Recadinhos Bloco Régua Cute Infantil Escolar Papelaria Fofa Recadinho Infantil', 'O Conjunto de Adesivos e Recadinhos Bloco Cute Infantil Escolar Sortidos é perfeito para dar um toque especial e divertido à rotina escolar das crianças. Com adesivos coloridos e recadinhos fofos, esse conjunto é ideal para personalizar cadernos, agendas, materiais escolares ou até mesmo para trocar bilhetinhos com os amigos. Cada adesivo traz desenhos encantadores, como animais, personagens e elementos fofos, enquanto os recadinhos são perfeitos para mensagens carinhosas e criativas. Compacto e prático, o bloco sortido oferece variedade e pode ser usado em diversas situações, estimulando a criatividade e organização de forma divertida e encantadora! 15 Folhas por Conjunto 6,0cm x21,0cm', 17.9, 10.36, NULL, 'Stationery > Notebooks & Papers > Memo & Sticky Notes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7i11ljmwy1667', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F29980063867', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22695688102', 'Cubo Mágico Esferas Interativo Giro Rápido Antistress Profissional Magic Cube 3x3x3', 'Cubo Mágico Esferas– Brinquedo Educativo de Coordenação e Raciocínio O Cubo Sensorial Infantil Colorido é o brinquedo perfeito para estimular a criatividade, coordenação motora e raciocínio lógico das crianças de forma divertida. Com design moderno e peças coloridas em formato de esferas, ele proporciona uma experiência interativa que prende a atenção dos pequenos por horas. Ideal para crianças a partir de 3 anos, o cubo ajuda no desenvolvimento da concentração, percepção visual e habilidades motoras enquanto a criança brinca montando, girando e explorando diferentes movimentos. Características: ✔ Brinquedo educativo e sensorial ✔ Cores vibrantes e atrativas ✔ Estimula coordenação motora e raciocínio lógico ✔ Material resistente e seguro ✔ Fácil de manusear ✔ Compacto e leve ✔ Ideal para crianças acima de 3 anos Indicações: • Desenvolvimento infantil • Coordenação motora • Estímulo sensorial • Brincadeiras educativas • Presente infantil ATENÇÃO: As cores são enviadas de forma SORTIDAS.', 24.9, 11.9, NULL, 'Hobbies & Collections > Toys & Games > Rubik''s Cubes', 'https://cf.shopee.com.br/file/br-11134207-820m0-mpnom50yqewx6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F22695688102', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
