INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40972434955', 'Sabonete Líquido Pump Bambu 500ml Coala', 'Sabonete Líquido Pump Bambu 500ml Coala O sabonete líquido Coala limpa e perfuma a pele com uma fragrância incrível. Ideal para uso em lavabos e banheiros. Sua composição não resseca a pele. Possui ingredientes suavizantes e nutritivos que deixam a pele completamente limpa, refrescada e suavizada. Infundido com óleos botânicos que hidratam a pele, ao mesmo tempo que nutrem e protegem a pele contra impurezas. Indicação de Uso: - Ideal para as mãos, corpo e rosto. Fragrância: Bambu Cor: Verde Embalagem: 01 frasco pump de 500ml', 31.16, 31.16, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-824hs-mf9nje9hb4ek61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F40972434955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
