INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898088668', 'Pacote 10 unid Bucha De Redução PVC Soldável Curta 50mm X 40mm Fortlev', 'A Bucha de Redução Curta para Esgoto 50mm x 40mm SN Fortlev é um componente essencial para sistemas prediais, garantindo transições suaves entre tubos de diferentes diâmetros. Fabricada em PVC de alta resistência, ela oferece durabilidade excepcional e resistência à corrosão. Com uma vedação eficaz, este produto minimiza vazamentos, assegurando a integridade do sistema de esgoto. Projetada para suportar temperaturas de até 45°C, a bucha é ideal para escoamentos em regime não contínuo. Sua conformidade com a norma ABNT NBR 5688 garante qualidade e segurança nas instalações. Vantagens: Alta estanqueidade que reduz o risco de vazamentos. Material resistente ao desgaste e produtos químicos. Dimensões adequadas para transições entre tubos de 50mm e 40mm. Facilidade de instalação, agilizando o processo. Conformidade com normas que asseguram segurança e qualidade. Especificações técnicas: Marca: Fortlev Material: PVC (Policloreto de Vinila) Cor: Branca Dimensões: 50mm x 40mm Temperatura Máxima: 45°C Norma: ABNT NBR 5688 Tipo: Bucha de Redução Longa Conteúdo da embalagem: Bucha de Redução Curta 50mm x 40mm Garantia: Garantia de 5 anos pelo fabricante', 75.9, 52.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3xh7lhdqjawbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F22898088668', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297605296', '2x Whey Grego Bar - Barra de Proteína - Caixa c/ 12 barrinhas - Nutrata', 'COMPOSIÇÃO DO ANÚNCIO 2x WHEY GREGO BAR - CAIXA COM 12 UNIDADES - NUTRATA DESCRIÇÃO DO ANÚNCIO "WHEY BAR GREGO: Grego Bar é prática, nutricionalmente balanceada e pode ser usada como lanches intermediários para controlar a ingestão excessiva de alimentos durante períodos de perda de peso ou definição, como também sendo importante incremento proteico para minimizar a perda de massa muscular como consequência dos treinos ou durante dietas de restrição calórica. Benefícios: - Fornece alto teor de aminoácidos essenciais; - Contribui para o aumento da saciedade e o bom funcionamento intestinal; - Favorece a síntese proteica; - Estimula a recuperação e construção muscular. Diferencias de Qualidades: - 11g de proteína em 40g de barra; - Aporte de fibra prebiótica de alta tecnologia (Orafti Synergy1); - Adicionado de vitamina D3 e picolinato de cromo; - Possui mix especial de vitaminas e minerais; - Adoçado com poliol. Sugestão de uso: Consumir Whey Bar Grego entre as refeições, complementando a refeição com aporte proteico." CONTÉM LACTOSE. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA.PODE CONTER AMENDOIM, AVELÃ E PISTACHE. NÃO CONTÉM GLÚTEN.', 144.9, 144.9, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1y67dandgm72f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1160496125%2F22297605296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
