INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21299205963', 'Calota Evolution Chrome Black Esportiva Aro 14 Universal 4X100 4X108', 'Calota Evolution Chrome Black Esportiva Aro 14 Universal 4X100 4X108 Características: Produto novo de ótima qualidade; Design moderno; Fabricado em ABS; Fixado por parafuso; Roda aro 14 4x100 4x108; Sistema que evita a perda da calota. Conteúdo da embalagem: 01 Calota. Compatível com os modelos: Roda aro 14 furação 4x100; Roda aro 14 furação 4x108. Obs: valor anunciado referente a unidade. Garantia: 90 dias. Cuidados com a instalação: Retire somente dois parafusos em diagonal, alinhe o suporte nas posições 100 ou 108 indicadas no mesmo e fixe utilizando os mesmos parafusos da roda. Encaixe a calota no suporte observando que a posição do bico de ar coincida com o espaço na calota. Rosquear a tampinha, apertando até o final para a perfeita acomodação da calota. Atenção: para maior durabilidade do produto lavar somente com sabão neutro, não utilizar produtos que contenha solupan, querosene ou diesel. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços! Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 67.68, 60.92, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Wheel Cover', 'https://cf.shopee.com.br/file/br-11134201-7r98o-ls91ep56gu6910', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1147747289%2F21299205963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
