INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57802594420', 'Scarpin Vizzano Salto Alto Bico Fino Elegante 1421-100', '***ENVIO IMEDIATO APÓS A CONFIRMAÇÃO DO PAGAMENTO*** SEJAM BEM VINDOS À KROKODILUS SURF! DESCRIÇÃO: O scarpin Vizzano com salto de 12 cm é a escolha perfeita para quem busca combinar sofisticação e elegância em um único modelo. Com design clássico e atemporal, ele traz bico fino e acabamento moderno que valoriza qualquer produção, seja para eventos, trabalho ou ocasiões especiais. O salto agulha de 12 cm proporciona um visual alongado e imponente, enquanto o forro interno macio oferece mais conforto durante o uso. O modelo conta ainda com palmilha acolchoada e solado aderente, garantindo estabilidade na caminhada. O detalhe metálico com o emblema da marca adiciona um toque de charme e autenticidade ao calçado. ESPECIFICAÇÕES: Marca: Vizzano; Modelo: Scarpin feminino; Altura do salto:12 cm; Bico: Fino; Material externo: Sintético de alta qualidade; Forro interno: Têxtil macio; Palmilha: Acolchoada para maior conforto; Solado: Emborrachado com boa aderência; Detalhes: Aplique metálico com logo da marca. TABELA DE TAMANHOS: 33 - 22cm 34 - 22,5cm 35 - 23,5cm 36 - 24cm 37 - 25cm 38 - 25,5cm 39 - 26cm 40 - 26,5cm', 149.9, 139.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mid206614g765c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F57802594420', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794906976', 'Vaporizador Ferro De Passar Hamilton Beach Vapor Vertical 2 Em 1 Com Vaporizador Azul E Preto 220V', 'Passar as roupas é uma atividade que deve ser feito com cuidado e delicadeza, se não queremos danificar as roupas ou até enrugar mais; por isso, é importante ter um ferro de boa qualidade o que nos permitirá obter bons resultados. Seja no escritório, com amigos ou em uma ocasião especial, vestir suas roupas impecáveis fala muito de você. Este ferro será seu aliado para que fique bem o tempo todo! Uma experiência de passar roupa sem paralelo Uma maneira mais prática e leve de alisar suas roupas favoritas é através desta estação de vapor Hamilton Beach 14525-BZ220. Uma de suas principais características é a leveza gerada por ter o tanque de água independentemente do ferro, além de ajudá-lo a esticar suas roupas mais graças a que o jato de água dura mais que um ferro tradicional. Otimize seus tempos Este ferro presenta a função de passamento vertical, o que lhe permitirá apertar suas roupas penduradas e em menos tempo. Isso evitará queimaduras, pois sua base não faz contato com o tecido.', 199.9, 149.9, NULL, 'Home Appliances > Small Household Appliances > Irons & Steamers', 'https://cf.shopee.com.br/file/br-11134207-820m7-mlsdspf0rvgnf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1771909149%2F23794906976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
