INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899370946', 'Esquadro Magnético Solda 12kg Serralheiro Soldador', 'O Esquadro de Solda 12 kg é uma ferramenta essencial para soldadores e profissionais de metalurgia, proporcionando precisão e estabilidade durante o processo de soldagem. Fabricado com materiais de alta qualidade, este esquadro oferece durabilidade e resistência, suportando pesos de até 12 kg. Características: - Material Resistente: Construído com aço de alta qualidade, garantindo longa vida útil e resistência ao desgaste. - Peso Suportado: Capacidade de suportar até 12 kg, ideal para trabalhos pesados e complexos. - Precisão: Proporciona ângulos exatos para uma soldagem precisa - Versatilidade: Adequado para diversos tipos de soldagem, incluindo MIG, TIG e eletrodo revestido. - Design Ergonômico: Facilita o manuseio e posicionamento, melhorando a eficiência e a segurança no ambiente de trabalho. Benefícios: - Aumento da Produtividade: Reduz o tempo de configuração e ajuste, permitindo um trabalho mais rápido e eficiente. - Melhoria na Qualidade da Solda: Garante alinhamento perfeito e ângulos precisos, resultando em soldas mais fortes e duradouras. - Durabilidade: Feito para resistir às condições adversas de um ambiente de soldagem, garantindo uma ferramenta confiável por muitos anos. SKU: 24032', 21.39, 19.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821f0-mgpghnaznqbwc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F21899370946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
