INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892993604', 'Conjunto Sala de Jantar Olimpia com 4 Cadeiras Grécia Rufato', 'Se é uma sala moderna e sofisticada que você procura, o Conjunto de Mesa Olímpia com cadeiras Grécia é uma ótima opção. A mesa retangular foi desenvolvida pensando na praticidade e elegância, mas sem deixar de lado seu design inovador e harmonia com a cadeira que tem seu encosto super confortável. Dimensões Mesa: Altura: 79,6 cm Largura: 120 cm Profundidade: 80 cm Dimensões Cadeiras: Altura: 98 cm Largura: 42 cm Profundidade: 56 cm Não contém Vidro Material em MDF Informações Importantes: Os objetos que ambientam as fotos não acompanham o produto. Não disponibilizamos a montagem do produto. O produto acompanha manual de montagem. Não nos responsabilizamos por danos no produto causados por montagem de qualquer outra forma que não seja a descrita no manual. Verifique as dimensões do produto e certifique-se que o percurso que ele fará até o local de uso permite sua passagem. A Moderna Mobília reserva o direito de alterar as especificações técnicas sem prévio aviso. As medidas contidas no site podem sofrer variações de acordo com a montagem, tipo de costura etc. As tonalidades das cores podem sofrer alteração de acordo com a configuração de cada monitor. Garantia do fornecedor de 03 meses.', 1409.9, 1162.93, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7rd6m-lv0c1hd3kcb2bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1033307532%2F22892993604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
