INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898068227', 'Ponta De Teste Para Multímetro Cabo 90 Graus 80cm Profissional', 'A ponta de prova ou cabo de teste para multímetro e fontes de alimentação é um acessório indispensável para profissionais do ramo eletrônico, utilizado para os mais diversos tipos de testes em produtos e componentes eletrônicos. [ESPECIFICAÇÕES TÉCNICAS] • Ponta de Teste para Multímetro • 80cm • 90 Graus • Marca: Storm Tech • Dupla Isolação • Tensão de Isolação: 1000V AC/DC [CONTEÚDO DA EMBALAGEM] • 1 Cabo Teste 2 Pontas 80CM Por que adquirir este produto com a Loja do Som e Acessórios? • Todos os produtos à pronta entrega • Produtos de qualidade garantida • Equipe de atendimento especializada • Envio em 24 horas após o pagamento • Compra com segurança e credibilidade • No mercado há mais de 10 anos • Produtos com garantia e nota fiscal IMPORTANTE: A Loja do Som e Acessórios recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto. [DÚVIDAS FREQUENTES] • Como funciona a garantia? R: Nossos produtos têm uma etiqueta de garantia para nosso controle interno, com essa etiqueta identificamos a validade da garantia , portanto NÃO tire a etiqueta do produto. • O produto está disponível a pronta entrega? R: Sim, todos os nossos produtos estão no nosso estoque preparado para ser embalado e enviado pra você!', 17.99, 17.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-22090-ce227f0p9xhv52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800059202%2F22898068227', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693903771', 'Whisky Japonês Yamazaki 12 anos Suntory 700ml', 'O Whisky Yamazaki 12 anos Suntory possui a cor de ouro puro. No olfato tem notas de pêssego, abacaxi, grapefruit, cravo, laranja cristalizada, baunilha, mizunara (carvalho japonês). No paladar tem um sabor de coco, cranberry e manteiga. E no final gengibre doce, canela, final longo. O Yamazaki 12 anos foi premiado com medalha de ouro em duas competições da ISC, 2003 e 2010, double gold pela SWSC em 2009 e medalha de ouro (best in class) pela IWSC em 2011. Fundada em 1923, a Yamazaki é a destilaria mais antiga do Japão. Seus whiskies já receberam diversas premiações internacionais desbancando tradicionais whiskies escoceses nas disputas. Olfato: rico e complexo. Chocolate amargo, laranja, mel, caqui, pêssego, cravos e baunilha. Paladar: oleoso, viscoso e amanteigado. Amadeirado, pêssego, especiarias, manga, coco e canela. Fim de boca: longo, complexo e adocicado. Origem: Japão. Tipo: Single Grain Japanese Whisky. Graduação alcoólica: 43%ABV. Litragem: 700ml. Venda e consumo proibidos para menores de 18 anos.', 1039.9, 1039.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8mamlk5eette5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F23693903771', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213152375', 'VIN ROSE FREIXENET I HEART 750ML', 'O Vinho Rosé Freixenet I Heart 750ml é uma excelente escolha para quem busca uma bebida leve, refrescante e cheia de personalidade. Produzido na Espanha, apresenta uma delicada coloração rosada e aromas marcantes de frutas vermelhas, como morango e cereja, proporcionando uma experiência agradável e equilibrada. Em boca, destaca-se pelo frescor e suavidade, com sabor frutado e final leve, ideal para diversas ocasiões. Versátil e fácil de apreciar, é perfeito para acompanhar saladas, peixes, frutos do mar, massas leves, risotos e aperitivos, além de ser uma ótima opção para momentos de descontração entre amigos e familiares. Deve ser servido bem gelado para que suas características aromáticas e seu frescor sejam melhor apreciados. Com a qualidade e tradição da Freixenet, uma das vinícolas mais reconhecidas do mundo, o I Heart Rosé oferece uma experiência moderna e agradável para quem aprecia vinhos leves e fáceis de beber. Contém 750ml e teor alcoólico de 11,5%. Beba com moderação. Proibida a venda para menores de 18 anos.', 59.9, 40.99, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-824jb-mpv7q9rzj6rvd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F58213152375', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
