INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259792256', 'FILTRO COMBUSTIVEL PALIO/SIENA/STRADA 1.0/1.5/1.6 16V', 'Filtro de Combustível Original – Linha Fiat Palio / Siena / Strada Garanta a saúde do motor e a economia de combustível do seu veículo com o Filtro de Combustível de alta performance. Projetado para reter impurezas, partículas de sujeira e resíduos do tanque, este componente evita o entupimento dos bicos injetores e protege o sistema de alimentação contra corrosão. Benefícios de instalar esta peça: Economia de Combustível: Mantém o fluxo constante e a queima eficiente. Proteção do Motor: Evita que detritos cheguem à câmara de combustão. Partidas Rápidas: Melhora a resposta do carro no momento da ignição. Qualidade Certificada: Fabricado com material filtrante de alta durabilidade. Palio1.0 / 1.5 / 1.6 (8V e 16V)1996 a 2005 Siena1.0 / 1.5 / 1.6 (8V e 16V)1997 a 2005 Strada1.3 / 1.5 / 1.6 (8V e 16V)1998 a 2005 Palio Weekend1.5 / 1.6 (8V e 16V)1997 a 2005 Uno (Mille)1.0 Fire / MPI2001 a 2006 Atenção: Compatível com versões movidas a Gasolina ou Flex (conforme o modelo). Verifique se o seu veículo possui o sistema de engate rápido ou por abraçadeira, este filtro segue o padrão original de fábrica para as datas mencionadas. ESPECIFICAÇÕES TÉCNICAS Tipo de Produto: Filtro de Combustível (Blindado). Instalação: Entrada e saída com sistema de vedação de segurança. Dica de Manutenção: Recomenda-se a troca a cada 10.000 km ou conforme o manual do proprietário para evitar danos à bomba de combustível. N-31278', 50.5, 50.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820lz-mmxax0e9xwjm12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F484632697%2F58259792256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897611844', 'Relógio Smartwatch Galaxy Fit3 R390NZAAZTO Samsung', 'O Novo Galaxy Fit3 possui um Design esportivo e ergonômico em alumínio, que o deixa bem confortável e estiloso no seu punho. Possui um grande display de colorido e interativo, e é ideal para o monitoramento das práticas esportivas e de bem-estar. O Fit3 te ajuda a ter uma vida mais saudável, com o controle avançado da qualidade do sono e através do monitoramento dos seus exercícios (são 6 modalidades de esportes detectadas automaticamente, e 101 tipos programáveis). Possui detecção de queda e Alerta SOS. Além disso, com ele você recebe e responde suas notificações de chamadas e mensagens direto no punho. A bateria do seu Galaxy Fit3 possui uma longa duração, que pode chegar a 13 dias de autonomia de bateria. Ele é resistente contra água suportando até 50m (5ATM) de profundidade, e também resistente contra poeira (IP68). Características: Marca: Samsung Modelo: Galaxy Fit3 Design Esportivo e confortável em alumínio Display de 1.6 polegadas AMOLED colorido Bateria de Longa Duração Controle a câmera e mídia do seu celular Notificações e resposta rápida de mensagens e chamadas Detecção de queda e alerta de SOS Monitoramento de frequência cardíaca e estresse Funções de monitoramento avançado de Sono Suporta 101 tipos de treinos esportivos, sendo 6 detectados automaticamente Resistência à água (5 ATM = 50 metros) Sincronismo de configuração com seu smartphone através do aplicativo Galaxy Wearable Proteção: 5ATM Formato do Aparelho: Banda / Pulseira Interface com o Usuário: Toque na tela, Botão Lateral Sistema Operacional: Free RTOS Tecnologia: AMOLED Tamanho do Display / Luminosidade: 1.6 Polegadas Colorido ANATEL - número certificado: 19830-23-01739 Memória Memória Interna total compartilhada: 256MB Memória RAM: 1