INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198033031', 'Mangueira Radiador Superior FIAT IDEA 1.4 8v 2007 Ate 2017 - 88362 - 8241', 'Mangueira Radiador Superior FIAT IDEA 1.4 8v 2007 Ate 2017 Motor 1.4 8v - (Superior)O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 31.72, 31.72, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8259d-mr21g6dr4paaaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20198033031', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599303582', 'Válvula Solenóide Toyota Corolla 2008 a 2019 - 1339229 - T140002', 'Válvula Solenóide Toyota Corolla 2008 a 2019 1339229 T140002 Todos - (2 Vias) Problemas mais comuns no sistema de partida a frio Estão relacionados ao combustível ruim. A utilização de um combustível de baixa qualidade faz com que as vias de passagem da solenoide venham a entupir e não permitir a passagem do combustível. Outro problema no sistema pode ser a falta do uso. O combustível resseca os locais de passagem, fazendo com que a falta de lubrificação venha a tornar o material mais frágil, pois algumas partes do sistema são feitas de plástico.', 73.3, 73.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-822zg-mo9u7awgie4p8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20599303582', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
