INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097922251', 'Bico de Confeitar Pitanga 18 Pequeno Mago', 'Os nossos bicos de confeitar são essenciais para quem busca qualidade e sofisticação na hora da decoração. Fabricados em aço inoxidável de alta qualidade, são duráveis e resistentes, proporcionando uma aplicação suave e precisa de glacês e cremes. – 100% aço inoxidável; – Sem emendas ou rebarbas; – Única embalagem 100% protegida; Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 16.7, 16.7, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1d2hfleyiw2b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F20097922251', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41502459885', 'Chocolate Wafer Bis Limão C/16 Unidades Lacta', 'Chocolate Wafer Bis Limão C/16 Unidades Lacta – Crocante e Refrescante! O sabor irresistível do limão combinado ao chocolate e crocância única do Bis! O Chocolate Wafer Bis Limão Lacta é um delicioso wafer com camadas fininhas, recheado com um creme sabor limão e coberto com chocolate ao leite Lacta, garantindo uma experiência refrescante e crocante a cada mordida. Ideal para saborear a qualquer hora do dia ou para dividir com amigos e familiares. Principais Características: Marca: Lacta Sabor: Limão com cobertura de chocolate ao leite Conteúdo: 16 unidades por pacote Peso total: Aproximadamente 126g Ingredientes: Açúcar, farinha de trigo enriquecida, gordura vegetal, cacau, aromatizante sabor limão, leite em pó integral, emulsificantes, entre outros. Fabricação: Produto de alta qualidade Lacta, com rigoroso controle de produção. Benefícios do Produto: Perfeito para lanches rápidos, sobremesas ou coffee breaks. Ideal como lembrancinha de festas, eventos ou brindes. Embalagem prática, permitindo consumo individual ou compartilhado. Sabor único e refrescante que agrada adultos e crianças. Instruções de Uso e Armazenamento: Conserve em local seco, fresco e arejado. Após aberto, consuma em poucos dias para manter a crocância. Indicado para: Perfeito como lanche, sobremesa rápida, presente ou lembrancinha em festas infantis, aniversários e confraternizações. Ideal para quem procura um doce saboroso e de alta qualidade para consumo diário. Informações de Entrega: Disponível para envio imediato. Embalagem segura e protegida para garantir a integridade do produto até a entrega. Avisos Importantes: Contém glúten e derivados de leite. Pode conter soja, amendoim e castanhas. Aproveite agora esse delicioso wafer Bis sabor limão da Lacta! Garanta já o seu e surpreenda seu paladar!', 15.99, 15.99, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mabkf8ixvl2x08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F41502459885', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44360683753', 'Batata Tipo Chips 500g Coti-Fritas', 'Batata Tipo Chips Coti-Fritas 500g A Batata tipo Chips da Coti-Fritas é a pedida certa para quem ama uma batatinha chips, leve e saborosa. Feita com batatas selecionadas e frita no ponto ideal, ela vem em uma embalagem prática de 500g — perfeita para dividir com a família, levar pra festa ou simplesmente devorar assistindo sua série favorita. ✅ Batatas fininhas e crocantes ✅ Sabor tradicional e irresistível ✅ Embalagem família com 500g Ideal para petiscar, servir em festas ou acompanhar aquele hambúrguer caprichado.', 34.99, 34.99, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjogxgq5tg5i52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F44360683753', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493522532', 'Kit Bico Injetor CLIO 2000/2005 - 36677 - 1249', 'Kit Bico Injetor CLIO 2000/2005 1.0 16v - (Multi Point) (Sistema Bosch) (4 Ponteiras/4 Filtros) (8 O''rings - Ø Interno - 7,52mm/Ø Secção - 3,53mm) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 43.02, 43.02, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7reoy-m2ewhjnegwjab2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23493522532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8411380775', 'Chipshow TOP Chocolate Ao Leite em Gotas Forneável 1,01kg - Harald', '🍫 Chipshow TOP Chocolate Ao Leite em Gotas Forneável 1,010kg - Harald O chocolate ideal para dar cremosidade, brilho e sabor irresistível às suas receitas! ✅ Descrição do Produto O Chipshow TOP Chocolate Ao Leite em Gotas Forneável 1,010kg Harald é perfeito para uso em padarias, confeitarias e também para quem ama preparar doces em casa. Produzido com a qualidade Harald, suas gotas de chocolate ao leite são fáceis de derreter, têm sabor marcante e equilibrado e garantem acabamento profissional em bolos, tortas, bombons, trufas e sobremesas. 🌟 Diferenciais Praticidade: formato em gotas que facilita o derretimento uniforme. Versatilidade: ideal para coberturas, recheios, modelagens e até cookies. Qualidade Harald: sabor intenso de chocolate ao leite com textura cremosa. 📦 Características Técnicas Peso líquido: 1,010kg Tipo: Chocolate ao Leite Forneável em gotas Marca: Harald – Linha TOP Textura: Cremosa, derrete de forma uniforme Uso: Forneável, resiste ao calor do forno em receitas como cookies e pães doces 🍰 Benefícios Garante acabamento profissional em suas receitas. Derretimento prático e uniforme, sem desperdício. Pode ser usado tanto em sobremesas sofisticadas quanto em receitas caseiras. Resistente ao forneamento, mantendo sabor e formato após o forno. 💡 Dicas de Uso Perfeito para cookies, bolos, pães de mel, muffins e brownies. Pode ser derretido em banho-maria ou micro-ondas para recheios e coberturas. Armazenar em local fresco e seco, longe da luz solar. 🎯 Indicação Ideal para confeitarias, padarias, buffets, doceiras, produção artesanal e uso doméstico. Palavras-chave: chocolate para confeitaria, gotas forneáveis, Harald TOP, chocolate para cookies. 🚚 Entrega Produto com pronta entrega e embalagem segura, garantindo que chegue até você em perfeitas condições. ⚠️ Avisos Contém leite e derivados de soja. Pode conter traços de amendoim, avelã, castanha de caju e castanha-do-pará. Não é vegano. 👉 Garanta já o seu Chipshow TOP Chocolate Ao Leite em Gotas Harald e dê um toque profissional às suas receitas! 📌 Somos uma loja especializada em artigos de festa, confeitaria, embalagens e doces com lojas físicas no estado de São Paulo, desde 2002', 68.99, 68.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzs37s94r1a97c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F8411380775', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4977023027', 'Coloreti Confeito de Chocolate Mesclado Rosa e Branco 500g Jazam', 'Pastilhas confeitadas e coloridas com Sabor delicioso de Chocolate, crocantes por fora e macias por dentro. Coloreti é um produto saboroso e divertido, preferido pelas crianças e adolescentes. Ingredientes: Açúcar, gordura vegetal fracionada, cacau em pó, massa de cacau, glicose, maltodextrina, sal, emulsificante lecitina de soja (INS 322), corante inorgânico dióxido de titânio (INS-171), glaceante cera de carnaúba (INS 903), corantes artificiais (conforme descrito a seguir para cada cor), e aromatizante. Pastilha Branca: corante inorgânico dióxido de titânio (INS 171). Pastilha Rosa: corante artificial eritosina (INS 127). ALÉRGICOS: CONTÉM DERIVADO DE SOJA. PODE CONTER AMENDOIM, LEITE E OVO. NÃO CONTÉM GLÚTEN. Estado de Conservação: Manter em local Seco e Fresco (teme calor) Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 39.99, 39.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2wccm6nzll1a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F4977023027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
