INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211143960', 'Vestido Estampado Bebê Feminina Lilica Ripilica', 'O vestido Lilica Ripilica Alto Verão é a escolha perfeita para unir conforto e delicadeza nos dias mais quentes. Confeccionado em meia malha stretch, oferece maciez, leveza e liberdade de movimento para acompanhar a rotina das pequenas. O detalhe de babado na manga acrescenta charme e feminilidade, enquanto a estampa digital por toda a peça traz modernidade e um visual alegre, traduzindo a essência divertida da marca. Ocasião de Uso Versátil e encantador, é ideal para passeios ao ar livre, viagens de férias, encontros em família ou momentos de lazer durante o verão. Pode ser combinado com sandálias, sapatilhas ou tênis, criando produções fresquinhas, Confortáveis e cheias de personalidade.', 179.0, 125.3, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-823pn-moijjkvb5xjjaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F58211143960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
