INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198166719', 'Cola Branca 793 Uso Geral 100gr Tekbond', 'A Cola 793 Tekbond é uma solução adesiva versátil e de alta performance, ideal para reparos rápidos, trabalhos manuais e aplicações industriais. Com sua fórmula de média viscosidade, ela é excelente para unir diferentes materiais, incluindo superfícies porosas ou de difícil adesão. Características e Benefícios: - Multiuso e Versátil: Indicado para metais, madeira, porcelana, borracha, plástico, cortiça, papel e outros. - Adesão Rápida e Resistente: Fixação extraforte em segundos. - Média Viscosidade: Perfeito equilíbrio entre fluidez e espessura. - Uso Profissional e Doméstico: Ideal para marcenaria, artesanato e pequenos reparos. - Transparente e Discreto: Não interfere na estética das peças. - Alta Durabilidade: Garantia de fixação a longo prazo. - Pronto para Uso: Dispensa armazenamento refrigerado. Modo de Uso: Certifique-se de que as superfícies estejam limpas, secas e livres de poeira ou gordura. Aplique uma fina camada de cola em apenas uma das superfícies (o excesso pode comprometer a adesão). Pressione as superfícies firmemente por aproximadamente 20 segundos. A máxima resistência é atingida em 24 horas após a aplicação. Cuidados e Precauções: Evite contato com os olhos e a pele. Não utilize em materiais sensíveis ao calor ou em aplicações com exposição prolongada a altas temperaturas. Mantenha fora do alcance de crianças. Armazene em local fresco e seco para garantir a durabilidade do produto. Garantia: - 3 meses pelo fabricante.', 75.9, 52.9, NULL, 'Stationery > School & Office Equipment > Glues', 'https://cf.shopee.com.br/file/sg-11134201-7rcdi-m6ijitnq0wduf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23198166719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
