INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8211292005', 'Chicletes De Bola C/100 Unidades Danny Ball', 'Diversão e sabor em cada mordida! O Chicle Bola Danny sortido vem com gummies recheados que explodem em sabor. Colorido, macio e cheio de personalidade, é a escolha perfeita para animar festas, presentear ou deixar à disposição em estabelecimentos. Ingredientes: açúcar, xarope de glicose, base para goma de mascar, emulsificante, lecitina de soja (INS 322), maltodextrina, aroma idêntico ao natural de maçã verde, morango, uva e artificial de tutti-frutti. Contém corantes artificiais, amarelo tartrazina (INS 102), amarelo crepúsculo (INS 110), vermelho 40 (INS 120) e azul brilhante (INS 133). ALÉRGICOS: PODE CONTER TRAÇOS DE LEITE, SOJA E DERIVADOS. NÃO CONTÉM GLÚTEN. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 16.49, 16.49, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhhmk0ry3a4i77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F8211292005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40069454263', 'Kit Cilindro Pistão Motor Cg160 Start Fan Titan Bros 160', 'Seja Bem-vindo(a) a RV Autopeças !! É um prazer imenso tê-lo em nosso anuncio. Abaixo algumas informações sobre o Produto e Aplicação. Por fim, conheça um pouco mais sobre a RV Autopeças. Produtos: - O kit contém cilindro, pistão, pino e jogo de anéis de segmento. Marcas: Mahle Metal Leve Aplicação: Honda CG Titan 160 Honda CG Fan 160 Honda NXR Bros 160 Honda CG Start 160 Garantia 90 dias. Sobre a Loja: A RV Autopeças é uma empresa que trabalha exclusivamente com o setor de peças para veículos leves e médios, sendo eles nacionais ou importados. Oferecemos peças com qualidade, prazo de entrega, parcerias com as melhores marcas e eficiência no atendimento. Temos uma equipe de profissionais qualificados para orientar o cliente nas suas mais variadas necessidades relacionadas à manutenção do seu veículo. Oferecemos também um amplo estoque de peças e envios diários. Visamos constantemente o aperfeiçoamento e melhoria dos serviços para a satisfação total do cliente. - ATENÇÃO Para garantia de AMORTECEDORES, só serão aceitas mediante apresentação do certificado enviado junto ao produto. Sem esse documento, não será possível efetuar a garantia do produto. Em caso do não recebimento do certificado, favor nos enviar assim que receber a mercadoria e notar a ausência.', 276.56, 276.56, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134201-820mg-mqy6108wlrt296', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373135807%2F40069454263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
