INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44360785206', 'Kit com 4 Organizadores Multiuso para Roupas C/ Zíper Guarda Edredom Cobertor', 'Mantenha seu lar sempre em ordem com a Bolsa Organizadora Multiuso Kontuz. Ideal para roupas, colchas e até cobertores leves, essa bolsa é perfeita para otimizar o espaço nos armários e closets. Feita com material ecológico, é à prova de umidade, respirável, durável e resistente ao mofo. Possui visor transparente central para fácil visualização do conteúdo e alças laterais que facilitam o transporte. CONTEÚDO DA EMBALAGEM: - 4 Bolsas organizadoras; ESPECIFICAÇÕES: - Ecológica; - Anti-mofo; - À prova de umidade; - Durável; - Visor transparente; - Alças laterais; - Tamanho pequeno - Ideal para roupas dobradas, colchas e até um cobertor leve ou de solteiro; - Marca: Kontuz. MEDIDAS DO PRODUTO: ( CxAxL ) 45 x 45 x 20 cm IMPORTANTE: - Garantia: 3 Meses a partir da data de recebimento - para defeitos de fabricação (não cobrimos mau uso). Todos os Direitos Reservados Em caso de cópia dessa descrição e fotos, os responsáveis serão cobrados de acordo com a Lei (9.610/98) de Direitos Autorais.', 79.9, 43.9, NULL, 'Home & Living > Home Organizers > Wardrobe Organizers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcrrba34h5ohff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325008325%2F44360785206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
