INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099600173', 'Evaporador de Água para Ar Condicionado 3,5L - Vapoar', 'Evaporador de Água para Ar Condicionado 3,5L - Vapoar O Evaporador de Água para Ar Condicionado 3,5L - Vapoar é a solução ideal para quem busca eficiência e praticidade na climatização de ambientes. Com sua capacidade de 3,5 litros, este evaporador proporciona uma umidade adicional que melhora a qualidade do ar, contribuindo para um ambiente mais confortável e saudável. Ideal para ser utilizado em sistemas de ar condicionado, o Vapoar é projetado para otimizar o desempenho do seu aparelho, garantindo um resfriamento mais eficiente e prolongado. Fabricado com materiais de alta qualidade, o Vapoar é fácil de instalar e manter. Seu design compacto e funcional permite que se encaixe perfeitamente em diversos modelos de ar condicionado, oferecendo uma operação silenciosa e sem complicações. A tecnologia de evaporamento utilizada assegura uma distribuição uniforme da umidade, ajudando a evitar o ressecamento do ar e proporcionando uma sensação agradável de frescor.', 249.0, 249.0, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-820ng-mnkfc3do1zwi51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F20099600173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997302103', 'Painel De Festa Retangular Game Neon Horizontal Sublimado Em Tecido', 'Painel Horizontal Para Decoração de Festa Sublimado Em Tecido PRÁTICO E FÁCIL DE USAR. Impressão de alta qualidade, cores vivas, imagens nítidas e ótimo acabamento, o painel horizontal da Pistache Decor é o detalhe perfeito para ter resultado incrível em sua decoração. Todas as artes são pensadas para a sua festa, deixando sua decoração muito mais cheia de vida! TAMANHO DOS PAINÉIS: (Confira na opção tamanho qual medida é o produto) 1,50m de largura x 1,00m altura 2,00m de largura x 1,50m altura BENEFÍCIOS DOS PAINÉIS CRIATEMA: • Arte Exclusiva. • Não amassa - tecido especial. • Não desbota, pode ser lavado quantas vezes desejar. • Alta durabilidade. • Não reflete luz na hora das suas fotos. • Sem emenda. • Leve elasticidade • Acabamento em overloque evitando que o painel desfie. DICA DE USO: • Decorações de festas de aniversário, confraternização, eventos e festas em geral. • Caso não possua uma estrutura/suporte, o painel pode ser fixado à parede basta utilizar fita adesiva larga ou dupla face 3M FICHA TÉCNICA: • Tecido Malha New (Que estica e não amassa). • Tecido Leve com ótimo caimento • Gramatura: 140g/m de excelente qualidade. • Composição do Tecido: 95% Poliéster e 5% de Elastano. ITEM INCLUSO: 1 Painel Retangular Horizontal em tecido com acabamento em overloque. OBSERVAÇÃO: Todos os nossos produtos não acompanham estrutura/suporte. >>ATENÇÃO AOS PRODUTOS<< • PAINÉIS COM ESTAMPADO GLITTER, FOLHAGEM (MURO INGLÊS) E LANTEJOULA: - Todos os nossos produtos são sublimados, ou seja, estampados em tecido, sendo assim estes temas não possuem glitter, folhagem ou lantejoula de fato, produzidos em altíssima qualidade, dando um aspecto 3D imitando as texturas reais. - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - *** PERGUNTAS E RESPOSTAS: *** - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - ACOMPANHA ESTRUTURA? Não acompanha estrutura/suporte, vendemos somente as capas em tecido TRABALHAM COM PERSONALIZAÇÃO? Não! Nós optamos para uma melhor eficiência no processo de postagem do pedido, trabalharmos com produtos prontos. CONSIGO PENDURAR/FIXAR DIRETO NA PAREDE? Sim, Caso não possua a estrutura/suporte próprio, pode ser fixado à parede basta utilizar fita adesiva larga ou dupla face 3M QUANDO É FEITO O ENVIO? Trabalhamos com produtos à pronta entrega, comprando e sendo aprovado no dia (PIX, CARTÃO DE CRÉDITO ou DÉBITO) o envio já é feito no próximo dia útil. POSSUI GARANTIA? Nosso painel possui garantia contra defeito de fabricação. PRODUTO COM NOTA FISCAL? Todos os produtos acompanham de nota fiscal. >>> Tem alguma dúvida antes de finalizar sua compra? Envie uma mensagem para nós que ajudaremos você! <<<', 88.9, 69.9, NULL, 'Home & Living > Party Supplies > Backdrops & Banners', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lr3bwdn4tfkd54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F23997302103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298026712', 'Placa Interface Electrolux DF47/50 64502351 - Bivolt', 'Placa Interface Electrolux DF47/50 64502351 - Bivolt Componente eletrônico essencial para o funcionamento adequado dos modelos de refrigeradores Electrolux DF47 e DF50. Este item é responsável por gerenciar e controlar diversas funções do aparelho, garantindo a interface entre o usuário e o sistema interno do refrigerador. Sendo bivolt, a placa pode operar em diferentes tensões elétricas, proporcionando maior versatilidade e adaptabilidade em diferentes regiões. A peça é projetada com alta qualidade e precisão, assegurando durabilidade e eficiência no desempenho do refrigerador.', 169.9, 169.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwu-mbsd1emjqgc92a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F21298026712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
