INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4267143928', 'Capsulas Nespresso Café Chocolate Cacau 10 Capsulas', 'KIT 10 CÁPSULAS COMPATÍVEL COM NESPRESSO - SABOR CAFE CACAU CAFÉ COM CACAU CAFÉ COM CACAU ITALLE: Prove nossa versão Café com Cacau, que une o sabor marcante do café com um delicioso toque de chocolate, surpreendendo no paladar. Adicione leite para potencializar a cremosidade da bebida. Experimente seu momento Italle! Café Italle. Compatível com seus melhores momentos. OBS : As cápsulas devem ser mantidas dentro de um "pote" fechado, para que não se perca o sabor e o aroma da bebida. Deve ser preparado curto, em uma única extração. Nunca se esqueça de sempre passar água sem a cápsula, antes e depois de cada extração. Esvazie diariamente o compartimento de Cápsulas.', 29.9, 19.74, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m18ewj58522o58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F334540655%2F4267143928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
