INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22238105999', 'Lanterna Recarregável Com Led Super Potente Original Vonder Resistente Oferta Premium Original', 'Lanterna Super Potente Recarregável LED LRV 100L – Vonder 🔦⚡ A Lanterna Recarregável LRV 100L da Vonder é a escolha certa pra quem quer iluminação forte, prática e sem dor de cabeça. Com LED frontal de alto brilho e LED COB lateral, ela garante ótima visibilidade em qualquer situação, seja no dia a dia, camping ou emergência. Compacta, leve e com excelente alcance, é aquele item essencial pra ter sempre por perto. Itens Inclusos 📦: 1 Lanterna Recarregável LRV 100L 1 Cabo USB para carregamento (plugue não incluso) Especificações Técnicas ⚙️: Modelo: LRV 100L Fluxo luminoso: LED frontal (80 lm) / LED lateral COB (100 lm) 💡 Alcance: Até 200 metros 🌙 Bateria: Íons de lítio (3,7 V – 1,2 Ah) 🔋 Tempo de recarga: Aproximadamente 4 horas ⏱️ Comprimento: 155 mm Diâmetro da lente: 37 mm Peso: 84 g Material: Plástico resistente Cor: Preto e amarelo Indicação de Uso 🏕️ Ideal para camping, uso doméstico, emergências, oficinas, trilhas e atividades noturnas em geral. Destaques 🚀 Iluminação potente com LED frontal e lateral Alcance de até 200 metros Recarregável via USB – mais economia Leve, compacta e fácil de transportar Por que escolher este produto? Produto novo e original Pronta entrega e envio em até 24 horas Compra 100% segura IMPORTANTE: SUA SATISFAÇÃO GARANTIDA! ✔️ -----> Entrega assegurada pela Shopee com garantia', 48.9, 37.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-820ln-mm0rqq7f1d6s88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F22238105999', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
