INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997443328', 'Climatizador de Ar Philco PCL10QF Display Touch 5 em 1 5L', 'Climatizador Philco PCL10QF Display Touch 5 em 1 5L A solução completa para o seu conforto durante todo o ano! Este aparelho inovador oferece cinco funções em um só: climatiza, aquece, umidifica, resfria e ventila, adaptando-se às suas necessidades em qualquer estação. Desfrute de um ambiente mais agradável: • 2 níveis de aquecimento: ideal para os dias mais frios, proporcionando um clima aconchegante. • 3 velocidades de ventilação: escolha a intensidade ideal para o seu conforto. • Função oscilar: distribui o ar fresco por todo o ambiente, garantindo uma temperatura uniforme. • Função timer de 7 horas: programe o desligamento automático do aparelho para maior economia de energia. • Mostrador luminoso com botão touch: facilita a visualização e o controle das funções. Praticidade e conveniência: • Reservatório com capacidade de 5L: garante autonomia de uso por longo período. • Rodas para movimentação: facilita a locomoção do aparelho para diferentes ambientes. • Controle remoto: permite controlar todas as funções à distância. • Aviso sonoro: indica quando o reservatório está vazio. • Alça para transporte: facilita o transporte do aparelho. • Sistema de filtro colméia: retém impurezas do ar, proporcionando um ambiente mais saudável. Garanta já o seu Climatizador Philco PCL10QF Display Touch 5 em 1 5L e desfrute de um ambiente mais agradável e confortável!! Tipo: Climatizador Níveis de aquecimento: 2 Velocidades: 3 Controle de temperatura: Sim Função umidificar: Sim Função ventilar: Sim Função dormir: Não Oscilante: Sim Timer: até 7 horas Possui filtro: Sim Reservatório de água: 5 Litros Controle remoto: Sim, com alcance de 4m Grade protetora: Sim Alça para transporte: Sim Rodízio: Sim Consumo (kWh): • 110V - 1,42 • 220V - 2,37 Potência (W): • 110V - 1500 • 220V - 2000 Peso (kg): 5.75 Referência: PCL10QF Dimensões (AxLxP): 66,5 x 28,5 x 25,4cm Registro INMETRO: SGS OCP 0040 Itens Inclusos: • 1 Climatizador de Ar Philco PCL10QF Display Touch 5 em 1 5L • Manual do produto Tomada (A): • 127v-20A • 220v-10A Informações importantes: Imagens meramente ilustrativas. Objetos que ambientam as fotos não acompanham o produto. As tonalidades das cores dos produtos podem sofrer alterações de acordo com a calibração do seu monitor. Este produto não inclui montagem e instalação. Garantia Fabricante: 12 meses', 870.9, 870.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rd6w-lty91kkjxcw352', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F889942432%2F23997443328', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12648606430', 'Gelo Pan 100g Animais Vetnil', 'Gelo Pan 100g INDICAÇÃO DO PRODUTO Gel de efeito relaxante e refrescante. Indicado nas fadigas de músculos, tendões, articulações e ligamentos, em traumas, contusões, luxações, artrites, reumatismos e dores musculares. NÍVEIS DE GARANTIA Cada 100 g contém: Mentol…………………………………………………………………….1 g Cânfora…………………………………………………………………..1 g Salicilato de Metila………………………………………………………1 g Excipientes q.s.p……………………………………………………..100 g MODO DE USAR Gelo Pan pode ser prontamente utilizado. Aplicar no local afetado massageando a favor do pelo. Também pode ser diluído em água morna: 50 g do produto para 1 litro de água (5 g/100 mL). Massagear a região afetada. EFEITOS COLATERAIS Não há registro de efeitos colaterais. APRESENTAÇÃO Bisnagas plástica contendo 100 g.', 54.9, 45.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5il7holhqbpa2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F12648606430', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
